local config = {
  ui_story_5080_50800100_1_dialog_content = "Meski taktik kita dalam pertempuran ini sangat berhasil, dengan segala hormat, rencanamu sangat berisiko.",
  ui_story_5080_50800100_2_dialog_content = "Heh, situasi yang mendesak membutuhkan tindakan yang mendesak.",
  ui_story_5080_50800100_3_dialog_content = "Namun, aku sedikit terkejut kamu, dari semua orang, berpikir itu berisiko.",
  ui_story_5080_50800100_4_dialog_content = "Melaporkan! Operasi Khusus A4 berhasil, dan operatif kami kembali dengan selamat!",
  ui_story_5080_50800100_5_dialog_content = "Laporan baru telah dikirimkan untuk persetujuan Anda.",
  ui_story_5080_50800100_6_dialog_content = "Baiklah. Ada yang lain?",
  ui_story_5080_50800100_7_dialog_content = "Ya, Grand Marshal. Beberapa operatif telah membuat permintaan pribadi, yang juga telah saya ajukan kepada Anda.",
  ui_story_5080_50800100_8_dialog_content = "Katakan saja padaku.",
  ui_story_5080_50800100_9_dialog_content = "Mereka ingin ditugaskan kembali ke skuad lain. Lebih tepatnya, mereka tidak lagi ingin beroperasi di bawah pemimpin mereka saat ini.",
  ui_story_5080_50800100_10_dialog_content = "Lalu...",
  ui_story_5080_50800100_11_dialog_content = "Pemimpin yang malang adalah...",
  ui_story_5080_50800100_12_dialog_content = "Ini Kapten <color=#FFB400>Rachel</color>, Kapten.",
  ui_story_5080_50800100_13_dialog_content = "Aku paham.",
  ui_story_5080_50800100_14_dialog_content = "Sudah kuduga...",
  ui_story_5080_50800100_15_dialog_content = "Ini adalah kali keempat sekarang. Apakah dia benar-benar tidak berubah sama sekali, Hiiro?",
  ui_story_5080_50800100_16_dialog_content = "Mohon maaf, Grand Marshal. Saya gagal membantu bawahan saya.",
  ui_story_5080_50800100_17_dialog_content = "Sepertinya kita harus melakukan sesuatu tentang ini.",
  ui_story_5080_50800100_18_dialog_content = "Kupikir sudah waktunya kita menempatkan dia dalam misi tersebut.",
  ui_story_5080_50800100_19_dialog_content = "Saya berterima kasih karena kamu bersedia memberinya kesempatan lagi.",
  ui_story_5080_50800100_20_dialog_content = "Hanya saja... Apakah benar-benar membantu ketika sayapnya sudah rusak?",
  ui_story_5080_50800100_21_dialog_content = "Dalam keadaan apapun, kita tidak diperbolehkan kehilangan kapten yang sangat baik seperti ini.",
  ui_story_5080_50800100_22_dialog_content = "Aku hanya berharap ini akan memiliki semacam dampak padanya.",
  ui_story_5080_50800100_23_dialog_content = "Tidak ada yang tahu apakah ini akan berhasil, tetapi mungkin anak burung baru adalah yang dia butuhkan untuk melebarkan sayapnya dan terbang tinggi lagi.",
  ui_story_5080_50800100_24_dialog_content = "Carleen, awas kaki kirimu!",
  ui_story_5080_50800100_25_dialog_content = "Bebek, PlayerName! Tetap fokus!",
  ui_story_5080_50800100_26_dialog_content = "Terima kasih... Vice! Awas belakangmu!",
  ui_story_5080_50800100_27_dialog_content = "Tidak ada kesempatan!",
  ui_story_5080_50800100_28_dialog_content = "Mengapa tiba-tiba ada begitu banyak Eclipsite...?",
  ui_story_5080_50800100_29_dialog_content = "Kami berada di tepi Gurun Rediesel, ingat? Masih banyak area di sini yang belum dibersihkan.",
  ui_story_5080_50800100_30_dialog_content = "Namun, mereka terlalu banyak... Mengapa <color=#FFB400>bawahan</color> Komandan Hiiro menunggu kita di tempat yang jauh ini? Itu tidak masuk akal...",
  ui_story_5080_50800100_31_dialog_content = "Dengarkan dengan baik, Vice. Misi yang akan saya berikan kepada kamu ini datang langsung dari Grand Marshal sendiri.",
  ui_story_5080_50800100_32_dialog_content = "Untuk misi rahasia ini, kamu akan bekerja di bawah komando seseorang, dan akan membantunya dalam menyelesaikan misinya.",
  ui_story_5080_50800100_33_dialog_content = "Anda diizinkan untuk membawa rekan apa pun yang Anda anggap perlu untuk misi, bahkan mereka yang bukan dari Illumina.",
  ui_story_5080_50800100_34_dialog_content = "Aku yakin Grand Marshal punya alasan sendiri untuk mengizinkan ini.",
  ui_story_5080_50800100_35_dialog_content = "Saya rasa saya belum pernah mendengar misi seperti ini, Komandan Hiiro. Siapa sebenarnya orang yang dimaksud?",
  ui_story_5080_50800100_36_dialog_content = "Anda seharusnya tidak asing dengan dia. Bagaimanapun, dia adalah salah satu seniormu—",
  ui_story_5080_50800100_37_dialog_content = "Namanya adalah <color=#FFB400>Rachel.</color>",
  ui_story_5080_50800100_38_dialog_content = "Mereka terus saja datang. Apakah kamu yakin ini jalan yang benar, Vice?",
  ui_story_5080_50800100_39_dialog_content = "Saya yakin. Menurut peta, ini adalah rute terbaik yang mungkin.",
  ui_story_5080_50800100_40_dialog_content = "Kapten yang kita cari adalah orang yang mengirimkan peta itu kepada kamu, bukan? Bagaimana kamu bisa begitu percaya pada seseorang yang bahkan belum pernah kita temui sebelumnya?",
  ui_story_5080_50800100_41_dialog_content = "Kamu tampak sangat serius tentang misi ini, Vice.",
  ui_story_5080_50800100_42_dialog_content = "Bahkan aku bisa bilang kamu antusias tentang hal itu. Kamu sudah mempersiapkan misi ini jauh sebelum matahari terbit hari ini.",
  ui_story_5080_50800100_43_dialog_content = "Yah, itu karena... Orang ini adalah legenda dari Legiun ke-3.",
  ui_story_5080_50800100_44_dialog_content = "Saat aku masih di akademi, kami belajar tentang semua pencapaian brilian dari dia dan diharapkan untuk mengikuti teladannya.",
  ui_story_5080_50800100_45_dialog_content = "Dia sudah menjadi kapten yang sangat dihormati sebelum dia seumur saya!",
  ui_story_5080_50800100_46_dialog_content = "Sebuah legenda dari Legiun ke-3... Mengapa kita belum pernah mendengar tentang dia sebelumnya?",
  ui_story_5080_50800100_47_dialog_content = "Saya tidak yakin mengapa, tapi setelah dia tiba-tiba menghilang suatu hari, tidak ada yang pernah melihatnya lagi...",
  ui_story_5080_50800100_48_dialog_content = "Graah—",
  ui_story_5080_50800100_49_dialog_content = "Jumlah Eclipsite terlalu banyak.",
  ui_story_5080_50800100_50_dialog_content = "Tempat ini adalah zona pendaratan yang sangat buruk...",
  ui_story_5080_50800100_51_dialog_content = "Bagaimana jika saya minta <color=#FFB400>Soroz</color> untuk menjemput kita sekarang? Tunggu, itu hanya akan menarik lebih banyak Eclipsite.",
  ui_story_5080_50800100_52_dialog_content = "Hal itu bahkan akan membahayakan Kapten ini!",
  ui_story_5080_50800100_53_dialog_content = "Sepertinya kita tidak punya pilihan. Carleen, aku akan menahan Eclipsites sementara kamu mencari tempat yang lebih tinggi!",
  ui_story_5080_50800100_54_dialog_content = "Apa? Jangan kehilangan fokus, PlayerName! Kembali berdiri di belakangku!",
  ui_story_5080_50800100_55_dialog_content = "Graaah!",
  ui_story_5080_50800100_56_dialog_content = "(Mereka menyerang dari bawah pasir?! Tidak baik, aku tidak bisa menghindar tepat waktu!)",
  ui_story_5080_50800100_57_dialog_content = "PlayerName!",
  ui_story_5080_50800100_58_dialog_content = "Kamu harus belajar melindungi dirimu sendiri sebelum khawatir tentang orang lain, <color=#FFB400>Caelestite One</color>.",
  ui_story_5080_50800100_59_dialog_content = "Ini hanya tes kecil. Apakah benar-benar sulit bagimu?",
  ui_story_5080_50800100_60_dialog_content = "Tidak masalah. Menilai kekuatan sebenarnya Anda juga merupakan salah satu tanggung jawab saya.",
  ui_story_5080_50800100_61_dialog_content = "Kau tidak apa-apa, PlayerName?",
  ui_story_5080_50800100_62_dialog_content = "A-Aku baik-baik saja... Siapa orang itu...",
  ui_story_5080_50800100_63_dialog_content = "Seorang wanita dengan tatapan tajam, dikelilingi oleh drone...",
  ui_story_5080_50800100_64_dialog_content = "Dan mengenakan seragam dari seorang kapten elit...",
  ui_story_5080_50800100_65_dialog_content = "Kau pasti...!",
  ui_story_5080_50800100_66_dialog_content = "Apakah kamu kapten dari <color=#FFB400>Skuad Eagleeye</color>? T-Terima kasih telah menyelamatkan PlayerName!",
  ui_story_5080_50800100_67_dialog_content = "<color=#FFB400>Eagleeye</color>... Tidak perlu disebutkan lagi.",
  ui_story_5080_50800100_68_dialog_content = "Commander mengatakan bahwa kalian telah bekerja sama selama ini. Bagaimana bisa kalian masih membuat begitu banyak kesalahan amatir?",
  ui_story_5080_50800100_69_dialog_content = "Kamu terlalu banyak menanamkan emosi yang tidak perlu pada rekan satu skuadmu, Caelestite.",
  ui_story_5080_50800100_70_dialog_content = "Menurut pendapat saya, lancer Anda lebih dari mampu melindungi Anda dan membela dirinya sendiri.",
  ui_story_5080_50800100_71_dialog_content = "Daripada meninggalkan posisimu dengan sembrono, seharusnya kamu membiarkan Vice menyingkirkan target yang lebih penting.",
  ui_story_5080_50800100_72_dialog_content = "Dan kamu. Kamu juga kapten, bukan?",
  ui_story_5080_50800100_73_dialog_content = "Y-Ya, Bu!",
  ui_story_5080_50800100_74_dialog_content = "Keahlianmu juga ada di bidang pengintaian. Tidak ada alasan bagi kamu... untuk terlalu memaksakan diri.",
  ui_story_5080_50800100_75_dialog_content = "(Apakah dia... menunjukkan kepedulian pada Vice?)",
  ui_story_5080_50800100_76_dialog_content = "Untuk skuad tiga orang yang menghadapi gelombang Eclipsites, prioritas pertama Anda haruslah menembus barisan musuh dengan cepat.",
  ui_story_5080_50800100_77_dialog_content = "Dengan adanya penembak jitu di skuad, serangan hampir sepenuhnya harus ditinggalkan kepada lancer sementara yang lainnya fokus pada tujuan mereka.",
  ui_story_5080_50800100_78_dialog_content = "Tapi karena kamu memilih untuk bertarung secara defensif... Lancer, kenapa kamu terus mengalihkan perhatianmu untuk melindungi penembak jitu kamu? Mengingat dia lebih gesit daripada kamu, seharusnya kamu fokus melindungi orang di belakangmu.",
  ui_story_5080_50800100_79_dialog_content = "(S-Sangat ketat.)",
  ui_story_5080_50800100_80_dialog_content = "Entah kenapa, aku teringat akan seseorang...",
  ui_story_5080_50800100_81_dialog_content = "Kenapa kalian semua menatapku?",
  ui_story_5080_50800100_82_dialog_content = "Namun tetap saja, saya merasa sulit untuk mempercayai seseorang yang telah menguji kita dengan cara yang begitu berbahaya.",
  ui_story_5080_50800100_83_dialog_content = "... Bagi saya tidak ada bedanya. Pemahaman saya awalnya hanya dua orang yang ditugaskan untuk misi ini; saya tidak menyangka putri Lumopolis juga ada di sini.",
  ui_story_5080_50800100_84_dialog_content = "Kamu telah menyelidiki latar belakangku?",
  ui_story_5080_50800100_85_dialog_content = "Jangan terlalu terkejut. Aku mengetahui semua ini hanya dengan melihatmu.",
  ui_story_5080_50800100_86_dialog_content = "Untukmu, The Last Caelestite... Menurut peraturan Illumina, orang luar tidak diizinkan dalam misi kami. Tapi karena Komandan bersedia membuat pengecualian untukmu, saya tidak punya apa-apa lagi untuk dikatakan.",
  ui_story_5080_50800100_87_dialog_content = "Har-Haruskah aku berterima kasih untuk itu...?",
  ui_story_5080_50800100_88_dialog_content = "Nama saya Rachel. Saya akan menjadi komandan Anda untuk misi ini.",
  ui_story_5080_50800100_89_dialog_content = "Uh, senang bertemu denganmu. Aku...",
  ui_story_5080_50800100_90_dialog_content = "Selama misi ini, kita akan melakukan operasi sebagai unit yang solid. Setelah misi selesai, skuad akan dibubarkan; sampai saat itu, kita akan berkomunikasi menggunakan nama kode.",
  ui_story_5080_50800100_91_dialog_content = "Kamu adalah Caelestite Satu.",
  ui_story_5080_50800100_92_dialog_content = "Kamu adalah Penetasan Dua.",
  ui_story_5080_50800100_93_dialog_content = "...",
  ui_story_5080_50800100_94_dialog_content = "Untukmu, putri Lumopolis, kamu adalah orang luar total bagi militer Federasi Illumina. Namun, karena kamu datang bersama, itu berarti kamu juga telah menyetujui kondisi misi ini.",
  ui_story_5080_50800100_95_dialog_content = "Mulai sekarang, aku akan menyebutmu sebagai White Lancer.",
  ui_story_5080_50800100_96_dialog_content = "Haruskah saya setuju dengan itu? Saya memang mengharapkan hal seperti itu dari seorang prajurit Illumina...",
  ui_story_5080_50800100_97_dialog_content = "Ini sangat tidak sopan.",
  ui_story_5080_50800100_98_dialog_content = "Ini pasti cara pasukan khusus kita beroperasi. Saya tidak berpikir dia bermaksud apa-apa dengan itu, Carleen.",
  ui_story_5080_50800100_99_dialog_content = "Ketiganya bisa memanggil saya Eagle Hunter Zero atau Kapten.",
  ui_story_5080_50800100_100_dialog_content = "Baik... Pemburu Elang Zero.",
  ui_story_5080_50800100_101_dialog_content = "(Dia tampak begitu peduli hanya beberapa menit yang lalu... kenapa dia tiba-tiba terasa begitu dingin dan jauh?)",
  ui_story_5080_50800100_102_dialog_content = "Kapten Rach—Kapten! Mungkin Anda tidak mengenalku, tapi aku adalah salah satu juniormu. Meskipun aku berada di bidang studi yang berbeda, aku tahu semua tentangmu.",
  ui_story_5080_50800100_103_dialog_content = "Semua tentang... saya...?",
  ui_story_5080_50800100_104_dialog_content = "Benar sekali! Saat aku masih di sekolah, kami mendengar semua tentang pencapaianmu dan bagaimana kamu memimpin Skuad Eagleeye.",
  ui_story_5080_50800100_105_dialog_content = "Komandan Hiiro selalu mengatakan kepada kami untuk belajar dari contohmu setiap kali kamu kembali dari misi yang berhasil.",
  ui_story_5080_50800100_106_dialog_content = "Meskipun banyak yang terjadi sejak saat itu, dan meskipun saya jarang kembali ke Illumina karena petualangan saya dengan PlayerName, saya masih mengagumimu.",
  ui_story_5080_50800100_107_dialog_content = "Kami hanya bisa menebak apa yang terjadi ketika kami berhenti mendengar tentangmu. Tapi sekarang sudah jelas bahwa kamu dan Skuad Eagleeye pasti sedang menjalankan misi rahasia, bukan?",
  ui_story_5080_50800100_108_dialog_content = "...",
  ui_story_5080_50800100_109_dialog_content = "Dan dengan Anda yang memimpin misi kami, saya yakin itu akan menjadi sukses besar! Ini adalah kesempatan sempurna bagi saya untuk mempelajari pekerjaan Anda secara langsung juga.",
  ui_story_5080_50800100_110_dialog_content = "Mari kita kesampingkan obrolan kosong untuk saat ini. Ikutlah denganku agar kita bisa membahas misi.",
  ui_story_5080_50800100_111_dialog_content = "(Sepertinya dia sama sekali tidak ingin mengungkit masa lalu... Tapi kenapa? Dia kan legenda...)",
  ui_story_5080_50800100_112_dialog_content = "Untuk misi ini, saya akan membimbing Anda masuk ke dalam gurun, wilayah Rediesel Wrench, untuk menyelidiki keberadaan Eclipsite unik.",
  ui_story_5080_50800100_113_dialog_content = "Eclipsite jenis ini mengendalikan kekuatan lava. Oleh karena itu, ia hanya muncul di lingkungan suhu tinggi, di mana ia cenderung meninggalkan tanda-tanda jelas dari gerakannya.",
  ui_story_5080_50800100_114_dialog_content = "Eclipsite seperti ini merupakan ancaman serius dan harus ditangani dengan hati-hati.",
  ui_story_5080_50800100_115_dialog_content = "Semua dari kalian harus mengikuti perintahku tanpa menyimpang jika kalian ingin menghindari korban yang tidak diharapkan.",
  ui_story_5080_50800100_116_dialog_content = "Selain itu, akan ada saat-saat ketika saya harus menyelidiki hal-hal lain. Kamu bebas untuk bergerak sendiri selama waktu-waktu tersebut.",
  ui_story_5080_50800100_117_dialog_content = "Hal lain apa, boleh saya tanya?",
  ui_story_5080_50800100_118_dialog_content = "Beritahu saya, apakah Anda tahu sesuatu tentang Skuad <color=#FFB400>Freebird</color>?",
  ui_story_5080_50800100_119_dialog_content = "Aku tidak bisa mengatakan bahwa aku melakukannya... Maaf.",
  ui_story_5080_50800100_120_dialog_content = "Lalu tidak ada yang perlu kamu khawatirkan. Itu berada di luar cakupan misi kita, jadi tidak perlu bagi kamu untuk membantuku... Meski kamu dipersilakan untuk memberi saya petunjuk apa pun yang mungkin kamu temukan.",
  ui_story_5080_50800100_121_dialog_content = "Kami cukup akrab dengan Sinsa. Jika misi kami adalah menyelidiki Eclipsite, kita harus mencoba meminta bantuannya.",
  ui_story_5080_50800100_122_dialog_content = "Saya mengerti... Mungkin inilah sebabnya Grand Marshal memilihmu untuk misi ini. Bertukar informasi bisa terbukti berguna dan efisien. Kamu memiliki izin saya untuk menghubungi dia, sekarang pergi.",
  ui_story_5080_50800100_123_dialog_content = "Hah? Tapi bagaimana dengan kamu, Kapten...?",
  ui_story_5080_50800100_124_dialog_content = "Sebagai seorang petugas dari Federasi Illumina, saya tidak memiliki urusan untuk dibicarakan dengan bandit yang melarikan diri. Jika kita bertemu, saya tidak punya pilihan selain menangkap mereka dan membawa mereka ke pengadilan.",
  ui_story_5080_50800100_125_dialog_content = "Sekarang pergi. Saya masih memiliki urusan sendiri untuk diselidiki.",
  ui_story_5080_50800100_126_dialog_content = "Sendirian? Tapi tempat ini sangat berbahaya, Kapten... Bukankah kita seharusnya berpisah menjadi pasangan saja?",
  ui_story_5080_50800100_127_dialog_content = "Mengingat sejarah kalian berjuang bersama, sinergi tempur kalian akan lebih efektif tanpa penambahan petarung asing seperti saya.",
  ui_story_5080_50800100_128_dialog_content = "Sekarang menuju ke kamp dasar Rediesel Wrench dan mulailah mengumpulkan intel—Itu adalah perintah.",
  ui_story_5080_50800100_129_dialog_content = "Aku akan bertemu denganmu di waktu yang akan datang.",
  ui_story_5080_50800100_130_dialog_content = "Dan begitu saja, dia pergi.",
  ui_story_5080_50800100_131_dialog_content = "Meskipun kurang sopan, dia adalah seorang prajurit yang tidak dapat disangkal kemampuannya.",
  ui_story_5080_50800100_132_dialog_content = "... Hei, Vice? Aku masih memikirkan sesuatu yang Rachel katakan barusan.",
  ui_story_5080_50800100_133_dialog_content = "Skuad Freebird yang dia sebutkan... Mungkinkah itu terhubung dengan Skuad Eagleeye entah bagaimana?",
  ui_story_5080_50800100_134_dialog_content = "Aku tidak yakin. Mereka mungkin hanya mirip dalam nama saja, tapi... Hah? Skuad Freebird sebenarnya dari Illumina...",
  ui_story_5080_50800100_135_dialog_content = "Jika misi kita saat ini adalah untuk menyelidiki keberadaan Eclipsite tertentu, mengapa Kapten juga menyelidiki salah satu skuad rekan kalian?",
  ui_story_5080_50800100_136_dialog_content = "Saya tidak melihat hubungannya sama sekali... Tapi melihat dari karakternya, saya ragu dia akan melakukan sesuatu tanpa alasan.",
  ui_story_5080_50800100_137_dialog_content = "Oh, kamu membuatku penasaran juga... Anyway, Kepala Philyshy pasti punya jawabannya. Biarkan aku bertanya padanya.",
  ui_story_5080_50800100_138_dialog_content = "Meong? Sebuah komunikasi mendadak dari Vice. Apakah kamu menemui masalah?",
  ui_story_5080_50800100_139_dialog_content = "Saya hanya ingin bertanya apakah kamu memiliki informasi tentang sebuah grup yang dikenal sebagai Freebird Squad?",
  ui_story_5080_50800100_140_dialog_content = "Hmm... Yah, konvensi penamaannya terdengar seperti milik kita, tapi itu pasti dari beberapa waktu yang lalu. Saya yakin saya bisa menemukan sesuatu di file kami.",
  ui_story_5080_50800100_141_dialog_content = "Terima kasih, Kepala Philyshy. Saya sangat penasaran tentang itu. Saya pasti akan membawakan Anda dendeng ikan berkualitas tinggi saat kita bertemu berikutnya!",
  ui_story_5080_50800100_142_dialog_content = "Selama informasinya tidak rahasia, tidak ada salahnya membagikannya denganmu—Tapi bagaimanapun, aku tetap menunggu ikan itu!",
  ui_story_5080_50800100_143_dialog_content = "Maaf telah menunggu, meong! Tertulis di sini bahwa Skuad Freebird sudah ada hampir empat puluh tahun yang lalu. Mereka adalah tim operasi khusus elit dengan lebih dari selusin misi berbahaya yang berhasil diselesaikan dengan sempurna.",
  ui_story_5080_50800100_144_dialog_content = "Namun, selama misi terakhir mereka, mereka dikirim ke Gurun Rediesel untuk mencari sesuatu. Dan misi itu... berakhir dengan kegagalan, meong.",
  ui_story_5080_50800100_145_dialog_content = "Sayangnya, detail lainnya dalam file ini sangat rahasia sehingga saya bahkan tidak memiliki otorisasi untuk melihatnya.",
  ui_story_5080_50800100_146_dialog_content = "Apa? Ada file yang bahkan kamu tidak bisa akses?",
  ui_story_5080_50800100_147_dialog_content = "Saya bahkan tidak bisa melihat nama pemimpin skuad mereka... Tapi ketika sesuatu dirahasiakan selama ini, biasanya mengimplikasikan bahwa seseorang telah membelot dari Federasi.",
  ui_story_5080_50800100_148_dialog_content = "Ini cukup menarik. Dari mana kamu menemukan nama ini, meong?",
  ui_story_5080_50800201_1_dialog_content = "Aku bertanya-tanya kenapa Sinsa begitu lama?",
  ui_story_5080_50800201_2_dialog_content = "Mereka jauh dari kita sekarang, dan mereka semua terlalu sibuk bekerja pada semacam proyek.",
  ui_story_5080_50800201_3_dialog_content = "...",
  ui_story_5080_50800201_4_dialog_content = "Apakah kamu baik-baik saja, Vice? Kenapa tampak begitu serius?",
  ui_story_5080_50800201_5_dialog_content = "Hah? Oh, aku baik-baik saja... Aku hanya bertanya-tanya mengapa Kapten membawa upaya skuad dari waktu yang sangat lama.",
  ui_story_5080_50800201_6_dialog_content = "Bukan hanya itu, ada juga skuad yang kaptennya dicurigai sebagai desertir.",
  ui_story_5080_50800201_7_dialog_content = "Mengingat cara dia melakukan hal-hal, saya akan bilang dia mungkin spesialis dalam mengumpulkan intelijen.",
  ui_story_5080_50800201_8_dialog_content = "Mungkin itu yang sedang dia lakukan: mengumpulkan informasi tentang orang yang dicurigai sebagai pembelot?",
  ui_story_5080_50800201_9_dialog_content = "Mungkin, tapi itu hampir empat puluh tahun yang lalu. Apa gunanya melanjutkan penyelidikan yang begitu lama?",
  ui_story_5080_50800201_10_dialog_content = "Apa mungkin Rachel entah bagaimana terhubung dengan orang itu?",
  ui_story_5080_50800201_11_dialog_content = "Skuad Freebird... Dan Skuad Eagleeye...",
  ui_story_5080_50800201_12_dialog_content = "Yo! Kenapa semua wajah tampak serius begitu?",
  ui_story_5080_50800201_13_dialog_content = "Sinsa!",
  ui_story_5080_50800201_14_dialog_content = "Lama tak jumpa! Kamu tampak jauh lebih kuat sekarang juga! Akhirnya kamu memutuskan untuk bekerja untuk kita?",
  ui_story_5080_50800201_15_dialog_content = "Uh, mungkin itu masih...",
  ui_story_5080_50800201_16_dialog_content = "Ha ha ha! Jangan khawatir tentang itu. Kamu bisa menemukan kami kapan saja kamu memutuskan! Jadi apa yang membawa kamu ke sini hari ini, huh?",
  ui_story_5080_50800201_17_dialog_content = "Sebenarnya, kami di sini dalam misi khusus... Apakah kamu tahu tentang Eclipsite yang unik atau abnormal di gurun ini?",
  ui_story_5080_50800201_18_dialog_content = "Eh? Seperti...?",
  ui_story_5080_50800201_19_dialog_content = "Anu, biar aku pikir... Mungkin yang tampak seperti terbakar? Atau yang sering berada di sekitar gunung berapi?",
  ui_story_5080_50800201_20_dialog_content = "Apa yang kamu bicarakan? Ada banyak Eclipsite yang bersembunyi di sekitar gunung berapi.",
  ui_story_5080_50800201_21_dialog_content = "Ya, tetapi Eclipsite ini khususnya tertarik pada gunung berapi, dan bahkan bisa menggunakan kekuatan lava.",
  ui_story_5080_50800201_22_dialog_content = "Mereka sangat kuat, dan mereka meninggalkan tanda-tanda jelas dari gerakan mereka di mana pun mereka pergi.",
  ui_story_5080_50800201_23_dialog_content = "Bisakah kamu memikirkan Eclipsites mana yang sesuai dengan tagihan?",
  ui_story_5080_50800201_24_dialog_content = "Eclipsite Lava... Tidak mungkin. Sudah lebih dari satu dekade...",
  ui_story_5080_50800201_25_dialog_content = "Jadi, kamu memang tahu sesuatu tentang mereka?",
  ui_story_5080_50800201_26_dialog_content = "Tolong beritahu kami apa yang kamu ketahui. Kami membutuhkan sebanyak mungkin informasi tentang mereka sekarang juga.",
  ui_story_5080_50800201_27_dialog_content = "Sejauh yang kebanyakan orang tahu, hal ini adalah sejarah kuno. Ini juga sangat berhubungan dengan keluarga kita...",
  ui_story_5080_50800201_28_dialog_content = "Tapi, karena ini sangat penting bagi kalian, aku rasa aku bisa memberi tahu kalian tentang itu.",
  ui_story_5080_50800201_29_dialog_content = "Aku tahu tentang Eclipsite yang kamu cari... Atau lebih tepatnya, anggota lama dari <color=#FFB400>Rediesel Wrench</color> memiliki dendam kesumat dengan mereka.",
  ui_story_5080_50800201_30_dialog_content = "Apa maksud kalian?",
  ui_story_5080_50800201_31_dialog_content = "Itu terjadi selama <color=#FFB400>Darkover Crisis</color>. Saat itu, saya hanya seorang anak laki-laki yang menjalankan tugas untuk pemimpin Rediesel Wrench.",
  ui_story_5080_50800201_32_dialog_content = "Suatu hari, Eclipsite merobohkan rumah lama kami seperti badai pasir, dan kami tidak punya pilihan selain meninggalkannya.",
  ui_story_5080_50800201_33_dialog_content = "Untuk memberi kita waktu untuk melarikan diri, pemimpin kami membawa beberapa pejuang terbaik kami untuk melindungi belakang kami.",
  ui_story_5080_50800201_34_dialog_content = "Aku masih ingat apa yang aku lihat hari itu... Sebuah monster nyata, yang membakar pasir di bawah kakinya menjadi kaca cair...",
  ui_story_5080_50800201_35_dialog_content = "Ha?",
  ui_story_5080_50800201_36_dialog_content = "Apa, kau tidak mendengarku? Aku bilang...",
  ui_story_5080_50800201_37_dialog_content = "Apa?!",
  ui_story_5080_50800201_38_dialog_content = "Wah—!",
  ui_story_5080_50800201_39_dialog_content = "Maafkan saya! Tolong saya, <color=#FFB400>Kesatria Terkutuk</color>!",
  ui_story_5080_50800201_40_dialog_content = "Awas, PlayerName!",
  ui_story_5080_50800201_41_dialog_content = "Ahhh—Hentikan, sekarang juga!",
  ui_story_5080_50800201_42_dialog_content = "Aaaaaahhh—",
  ui_story_5080_50800201_43_dialog_content = "Maaf, sayang, tapi tidak ada yang bisa menghentikan kekuatan musik!",
  ui_story_5080_50800201_44_dialog_content = "Terima kasih untuk <color=#FFB400>Kesatria Terkutuk</color> dan kekuatan anehnya!",
  ui_story_5080_50800201_45_dialog_content = "Zeta? Barbara dan Tiny One juga?! Kalian sedang apa?!",
  ui_story_5080_50800201_46_dialog_content = "Kamu hanya menabrak masuk ke dalam basis dengan trukmu, itu hanya...",
  ui_story_5080_50800201_47_dialog_content = "Tidak ada waktu untuk menjelaskan! Sekarang masuklah!",
  ui_story_5080_50800201_48_dialog_content = "Hah?",
  ui_story_5080_50800201_49_dialog_content = "Jangan bilang kamu tidak mendengarku, <color=#FFB400>Kesatria Terkutuk</color>?! Suara langkah kaki dari negeri yang jauh—",
  ui_story_5080_50800201_50_dialog_content = "Dia disini! Pemburu Pasir!",
  ui_story_5080_50800201_51_dialog_content = "Lihat ke sana! Itu—",
  ui_story_5080_50800201_52_dialog_content = "<size=45>Rachel!!!</size>",
  ui_story_5080_50800201_53_dialog_content = "Dan siapa itu? Baiklah Zeta, kau punya lima detik untuk memberitahuku apa jenis masalah yang telah kau ciptakan!",
  ui_story_5080_50800201_54_dialog_content = "Oh, ini buruk...",
  ui_story_5080_50800201_55_dialog_content = "Airbag menahan saya di tempat. Aku tidak bisa keluar!",
  ui_story_5080_50800201_56_dialog_content = "Bertahanlah, aku akan membebaskanmu.",
  ui_story_5080_50800201_57_dialog_content = "Tidak! Kita harus menjauh darinya! Dia adalah Minion dari Raja Iblis!",
  ui_story_5080_50800201_58_dialog_content = "Bandit Gurun Rediesel! Serahkan apa yang telah kau curi!",
  ui_story_5080_50800201_59_dialog_content = "Hmph, kau punya nyali, Lady.",
  ui_story_5080_50800201_60_dialog_content = "Dengan melihat lebih dekat, kamu dari Illumina, bukan?",
  ui_story_5080_50800201_61_dialog_content = "Tunggu! Sinsa, Rachel, dengarkan kami dulu...",
  ui_story_5080_50800201_62_dialog_content = "Diam!",
  ui_story_5080_50800201_63_dialog_content = "Seorang prajurit Illumina yang mencoba mengejar sekelompok anak-anak kami, dan memaksa mereka untuk menabrakkan mobil mereka ke pangkalan kami...",
  ui_story_5080_50800201_64_dialog_content = "Beberapa penjahat gurun yang berani mencuri teman-teman senegaraku... Aku tidak akan menunjukkan belas kasihan padamu!",
  ui_story_5080_50800201_65_dialog_content = "Mencari pertarungan, ya? Bagus! Sudah terlalu lama aku tidak menghajar kalian!",
  ui_story_5080_50800201_66_dialog_content = "Datanglah padaku!",
  ui_story_5080_50800201_67_dialog_content = "Ini tidak benar! Vice, Carleen, kita harus menghentikan mereka!",
  ui_story_5080_50800201_68_dialog_content = "Kita akan melakukannya bersama, ayo kita pergi sekarang!",
  ui_story_5080_50800202_1_dialog_content = "Serangga terbang yang menjengkelkan—Aku akan menghancurkan kalian semua sampai tak bersisa!",
  ui_story_5080_50800202_2_dialog_content = "Apa lagi yang kamu dapatkan sekarang?",
  ui_story_5080_50800202_3_dialog_content = "Jangan bergerak. Kecuali jika kamu ingin terpelanting ke langit, itu terserah...",
  ui_story_5080_50800202_4_dialog_content = "Jadi kamu baru saja menanam bahan peledak di tubuhku, huh? Tidak buruk.",
  ui_story_5080_50800202_5_dialog_content = "Dengan jarak ini, tak ada satu pun dari kita yang akan selamat dari ledakan.",
  ui_story_5080_50800202_6_dialog_content = "Dan meski kamu tampaknya tidak takut sama sekali... Aku suka itu! Sekarang, mari kita cari tahu apa yang terjadi selanjutnya!",
  ui_story_5080_50800202_7_dialog_content = "Saya lebih dari bersedia untuk mengorbankan hidup saya jika itu berarti bisa menumbangkan pemimpin Rediesel Wrench...",
  ui_story_5080_50800202_8_dialog_content = "Hei, hei, hei! Sudah cukup, kalian berdua!",
  ui_story_5080_50800202_9_dialog_content = "Misi itu, Kapten! Pikirkan tentang misi itu!",
  ui_story_5080_50800202_10_dialog_content = "Apa yang akan dilakukan orang lain jika sesuatu terjadi padamu, Sinsa?!",
  ui_story_5080_50800202_11_dialog_content = "Anak-anak di sini masih membutuhkanmu!",
  ui_story_5080_50800202_12_dialog_content = "\"Anak-anak\"?",
  ui_story_5080_50800202_13_dialog_content = "Huu-huu—",
  ui_story_5080_50800202_14_dialog_content = "Ayo kita turunkan senjata dan cari tahu apa yang terjadi, oke?",
  ui_story_5080_50800202_15_dialog_content = "Akulah yang telah memprovokasi Minion Raja Iblis. Saya akan bertanggung jawab penuh, jadi biarkan saja teman-temanku pergi!",
  ui_story_5080_50800202_16_dialog_content = "...",
  ui_story_5080_50800202_17_dialog_content = "Apa yang sedang terjadi di sini, Zeta?",
  ui_story_5080_50800202_18_dialog_content = "Semuanya dimulai dengan legenda Zeta, pejuang terhebat sepanjang masa—",
  ui_story_5080_50800202_19_dialog_content = "Setelah berlatih keras dalam seni balapan, saya masih tidak bisa mengalahkan Penyihir Sirkuit dalam kontes kecepatan.",
  ui_story_5080_50800202_20_dialog_content = "Aku yakin ini ada hubungannya dengan dia yang memiliki Caelestite Terakhir sebagai sekutu, jadi aku memutuskan untuk mencari kawan yang kuat untukku sendiri.",
  ui_story_5080_50800202_21_dialog_content = "Itulah saat aku menemukan Barbara, <color=#FFB400>Penyanyi Supernova</color> dan Regina sedang berdebat tentang semacam kompetisi menyanyi!",
  ui_story_5080_50800202_22_dialog_content = "\"O pejuang perkasa Zeta, tolong pinjamkan aku kekuatanmu!\"",
  ui_story_5080_50800202_23_dialog_content = "\"Dengan kamu di sisiku, aku bisa mengumpulkan kerumunan yang lebih besar daripada yang bisa Regina harapkan! Hadirinku adalah sumber kekuatanku!\"",
  ui_story_5080_50800202_24_dialog_content = "\"Sepertinya menyenangkan! Jangan lupa tentang saya: Zeta's setia <color=#FFB400>Penguasa Senjata</color>!\"",
  ui_story_5080_50800202_25_dialog_content = "Ah! Apakah ini sekutu yang saya cari? Mereka pasti tertarik oleh keagungan saya!",
  ui_story_5080_50800202_26_dialog_content = "Dan begitu, kami memulai perjalanan mulia kami untuk mengadakan tur di gurun yang ganas dan mengumpulkan lebih banyak penggemar!",
  ui_story_5080_50800202_27_dialog_content = "Dan dengan penemuan terbaru dan terhebat kami, <color=#FFB400>Rediesel Super Idol-mobile</color>, kami berangkat ke medan pertempuran—",
  ui_story_5080_50800202_28_dialog_content = "Apa? Bisakah kamu langsung ke bagian yang penting saja?!",
  ui_story_5080_50800202_29_dialog_content = "... Mendesah.",
  ui_story_5080_50800202_30_dialog_content = "Saat rombongan kami berkelana melalui gurun dengan lagu yang membara di hati kami, tiba-tiba saya menyadari sesuatu!",
  ui_story_5080_50800202_31_dialog_content = "Seekor elang tunggal bertengger di atas pasir.",
  ui_story_5080_50800202_32_dialog_content = "\"Aku yakin kita bisa menggunakan pria kecil ini untuk pencahayaan atau suara!\"",
  ui_story_5080_50800202_33_dialog_content = "Itu adalah kata-kata dari Guru Senjataku—Tapi aku bisa melihat kekuatan sebenarnya dengan mata kepala sendiri.",
  ui_story_5080_50800202_34_dialog_content = "Jadi saya memutuskan untuk membawa elang tersebut sebagai anggota dari pesta kita!",
  ui_story_5080_50800202_35_dialog_content = "Tapi tidak lama setelah itu, makhluk jahat datang mengejar elang itu. Dia tak kenal lelah dalam pengejarannya, dan dia bahkan menyerang kami.",
  ui_story_5080_50800202_36_dialog_content = "Tembakannya adalah salah satu yang paling menakutkan yang pernah saya lihat. Saya terlalu takut untuk menghentikan mobil... Maksud saya, saya terlalu khawatir untuk keselamatan teman-teman saya!",
  ui_story_5080_50800202_37_dialog_content = "Jadi kamu menabrak rumah kami dengan kecepatan penuh?!",
  ui_story_5080_50800202_38_dialog_content = "A-Aku yakin bahwa Kesatria Terkutuk akan bisa menghentikan kita tepat waktu!",
  ui_story_5080_50800202_39_dialog_content = "Astaga, Zeta...",
  ui_story_5080_50800202_40_dialog_content = "... Sudah cukup.",
  ui_story_5080_50800202_41_dialog_content = "Kembalikan <color=#FFB400>Eagle Hunter Three</color> kepadaku sekarang juga.",
  ui_story_5080_50800301_1_dialog_content = "Jadi namanya adalah <color=#FFB400>Eagle Hunter Three</color>, huh... Itu nama yang sangat keren!",
  ui_story_5080_50800301_2_dialog_content = "Baiklah... Mengingat <color=#FFB400>Eagle Hunter Three</color> sudah memiliki pemilik, saya akan mengembalikannya... Tolong berhenti bertengkar...",
  ui_story_5080_50800301_3_dialog_content = "Hei! Kamu mau ke mana, hah?!",
  ui_story_5080_50800301_4_dialog_content = "Kamu tidak akan pergi begitu saja setelah merusak perkemahan kami dan melukai anak-anak malang ini, 'kan?!",
  ui_story_5080_50800301_5_dialog_content = "Tidak peduli apa yang kamu katakan, mereka lah yang pertama kali mencuri <color=#FFB400>Eagle Hunter Three</color> dariku.",
  ui_story_5080_50800301_6_dialog_content = "Mungkin begitu, tapi kami bandit Rediesel selalu mendukung satu sama lain tidak peduli apa yang terjadi.",
  ui_story_5080_50800301_7_dialog_content = "Jadi kamu masih ingin bertarung?",
  ui_story_5080_50800301_8_dialog_content = "Sudahi saja, kalian berdua!",
  ui_story_5080_50800301_9_dialog_content = "Apa yang terjadi di luar sini? Seluruh tempat ini berantakan dan setiap orang tampak begitu gugup!",
  ui_story_5080_50800301_10_dialog_content = "J-Jeriah?!",
  ui_story_5080_50800301_11_dialog_content = "Dan apa yang sedang kamu lakukan di sini, hah?",
  ui_story_5080_50800301_12_dialog_content = "Bukan berarti aku ingin datang... Tapi, kamu tidak mendengar gunung berapi itu bergumam barusan, Sinsa?",
  ui_story_5080_50800301_13_dialog_content = "Gunung Berapi yang Mengaum telah terbangun, sama seperti <color=#FFB400>lima belas tahun yang lalu</color>.",
  ui_story_5080_50800301_14_dialog_content = "Ya?",
  ui_story_5080_50800301_15_dialog_content = "Hei bos! Kau baik-baik saja?",
  ui_story_5080_50800301_16_dialog_content = "Akhirnya kita berhasil membersihkan sebagian besar puing di luar sana. Apakah semua orang baik-baik saja?",
  ui_story_5080_50800301_17_dialog_content = "Tiny One! Barbara! Zeta! Di mana kalian bertiga?",
  ui_story_5080_50800301_18_dialog_content = "Jangan asal menerobos masuk, kalian!",
  ui_story_5080_50800301_19_dialog_content = "Kita sedang membicarakan hal penting! Hei! Sudahlah, kalian idiot—!!!",
  ui_story_5080_50800301_20_dialog_content = "Mereka bilang Gunung Berapi yang Mengaum itu bangun lagi. Apakah itu benar?",
  ui_story_5080_50800301_21_dialog_content = "Apa kabar, Zeta? Kamu tidak terluka, 'kan?",
  ui_story_5080_50800301_22_dialog_content = "Tidak! Saya benar-benar baik-baik saja, Putri Kindheart!",
  ui_story_5080_50800301_23_dialog_content = "Bahkan saya juga mendengar gemuruh tadi. Tidak ada keraguan tentang itu: Gunung Berapi yang Menderu kembali aktif.",
  ui_story_5080_50800301_24_dialog_content = "Terakhir kali meletus adalah saat <color=#FFB400>Darkover Crisis</color>, dan sejak itu telah tidak aktif. Apa yang mungkin terjadi—",
  ui_story_5080_50800301_25_dialog_content = "<size=45>Semua kalian diam saja!!!</size>",
  ui_story_5080_50800301_26_dialog_content = "Sialan, kemana perginya bajingan Illumina itu?!",
  ui_story_5080_50800301_27_dialog_content = "Hah? Siapa brengsek Illumina itu? Kamu tidak sedang membicarakan tentang saya, bukan?",
  ui_story_5080_50800301_28_dialog_content = "Hosh—Hosh—",
  ui_story_5080_50800301_29_dialog_content = "*terengah-engah* Kita... seharusnya... aman... di sini.",
  ui_story_5080_50800301_30_dialog_content = "J-Jangan bicara, coba atur napasmu saja.",
  ui_story_5080_50800301_31_dialog_content = "Nyaris saja. Kalau kita tidak berhubungan baik dengan Sinsa, itu pasti akan menjadi bencana yang lebih besar.",
  ui_story_5080_50800301_32_dialog_content = "Beruntung, pemikiran cepatmu memungkinkan kita untuk melarikan diri saat dia teralihkan.",
  ui_story_5080_50800301_33_dialog_content = "... Aku punya firasat orang-orang itu akan tidak masuk akal.",
  ui_story_5080_50800301_34_dialog_content = "Bagaimanapun juga, mereka hanyalah bandit dan pengkhianat.",
  ui_story_5080_50800301_35_dialog_content = "Bukan begitu!",
  ui_story_5080_50800301_36_dialog_content = "Rediesel Wrenches tidak seburuk itu... Jika kita hanya mendekati Sinsa dengan baik, dia pasti akan bersikap masuk akal!",
  ui_story_5080_50800301_37_dialog_content = "Mereka juga telah tinggal di Gurun Rediesel selama bertahun-tahun. Jika ada yang tahu lebih banyak tentang Freebird Squad, itu adalah mereka...",
  ui_story_5080_50800301_38_dialog_content = "Mendebatkan kredibilitas sekelompok pembelot tidak ada gunanya, jadi mari kita abaikan saja.",
  ui_story_5080_50800301_39_dialog_content = "Saat kamu sedang mengumpulkan info intel di kamp mereka, aku berhasil menemukan jejak target kita. Ikut denganku.",
  ui_story_5080_50800301_40_dialog_content = "Anda setidaknya bisa mendengarkanku...",
  ui_story_5080_50800301_41_dialog_content = "Lihatlah. Pasir di sini telah terbakar, dan area ini memiliki jejak abu vulkanik.",
  ui_story_5080_50800301_42_dialog_content = "Tidak ada kesalahan. Itu hanya di depan.",
  ui_story_5080_50800301_43_dialog_content = "Tapi... Ada beberapa set jejak.",
  ui_story_5080_50800301_44_dialog_content = "Ada kemungkinan target kita sudah bereproduksi. Tetap waspada.",
  ui_story_5080_50800301_45_dialog_content = "Target terlihat, Kapten!",
  ui_story_5080_50800301_X45_dialog_content = "Graah... Urk—",
  ui_story_5080_50800301_46_dialog_content = "Apakah ini... lava? Tidak, itu adalah Eclipsites!",
  ui_story_5080_50800301_47_dialog_content = "Mereka benar-benar berbeda dari apa pun yang pernah kita lihat sebelumnya. Mereka terlihat seperti tumpukan lava yang berjalan...",
  ui_story_5080_50800301_48_dialog_content = "Kamu benar, dan penampilan aneh mereka membuatnya sulit untuk menentukan bagian lemah mereka.",
  ui_story_5080_50800301_49_dialog_content = "Dengan panas yang intens itu melindungi mereka, saya ragu serangan jarak jauh akan memiliki efek yang signifikan.",
  ui_story_5080_50800301_50_dialog_content = "Bersiap untuk bertempur.",
  ui_story_5080_50800301_51_dialog_content = "Namun...",
  ui_story_5080_50800301_52_dialog_content = "Kekuatanmu lebih dari cukup untuk menghadapi mereka, White Lancer. Karena kamu paling cocok untuk bertarung langsung, kamu akan berdiri di garis depan formasi kita.",
  ui_story_5080_50800301_53_dialog_content = "Maaf, tapi kau masih tidak memiliki otoritas atas diriku.",
  ui_story_5080_50800301_54_dialog_content = "Kamu bisa memanggil kekuatan seekor kuda terbang, kan? Kamu harus menggunakannya untuk melancarkan serangan udara mendadak saat pertempuran.",
  ui_story_5080_50800301_55_dialog_content = "Berdasarkan komposisi tubuh mereka, tampaknya sulit bagi mereka untuk mempertahankan perlindungan tubuh penuh mereka. Menemukan celah terkecil dalam pertahanan mereka akan membuat serangan Anda menjadi fatal.",
  ui_story_5080_50800301_56_dialog_content = "...",
  ui_story_5080_50800301_57_dialog_content = "Sementara White Lancer melibatkan Eclipsites dalam pertempuran, Hatchling Two, gunakan Rapid Torrent Anda untuk menyerang mereka dari jauh.",
  ui_story_5080_50800301_58_dialog_content = "Tidak peduli jenisnya, semua Eclipsite akan menunjukkan titik lemah mereka saat berada di bawah serangan berat. Itulah saat Anda untuk menyerang.",
  ui_story_5080_50800301_59_dialog_content = "Mereka pasti akan kehilangan keseimbangan segera setelah kita memanfaatkan kelemahan mereka, yang akan memungkinkan White Lancer untuk melakukan pukulan mematikan.",
  ui_story_5080_50800301_60_dialog_content = "Baik!",
  ui_story_5080_50800301_61_dialog_content = "Para Pemburu Elang dan saya akan memberikan tembakan penekan dan mengarahkan Eclipsite menuju White Lancer.",
  ui_story_5080_50800301_62_dialog_content = "Daya tembak yang konstan harus mencegah mereka berkumpul, membuatnya lebih mudah untuk mengalahkan mereka satu per satu.",
  ui_story_5080_50800301_63_dialog_content = "Itu cukup strategi... Baiklah, kita akan melakukan seperti yang kamu katakan.",
  ui_story_5080_50800301_64_dialog_content = "(Meskipun dia hanya melihat mereka bertarung sekali, Rachel tahu persis kemampuan mereka dan bagaimana memanfaatkannya sebaik mungkin...)",
  ui_story_5080_50800301_65_dialog_content = "Caelestite Satu.",
  ui_story_5080_50800301_66_dialog_content = "Baik!",
  ui_story_5080_50800301_67_dialog_content = "Kamu akan bertugas untuk memimpin pertempuran ini.",
  ui_story_5080_50800301_68_dialog_content = "Ha?",
  ui_story_5080_50800301_69_dialog_content = "Bahkan persiapan tempur yang paling teliti sekalipun bisa menjadi sia-sia dalam panasnya pertempuran.",
  ui_story_5080_50800301_70_dialog_content = "Kemampuan unikmu untuk memahami jejak cahaya membuatmu menjadi komandan yang jauh lebih mampu dalam pertempuran ini.",
  ui_story_5080_50800301_71_dialog_content = "... Tidak hanya itu, kalian bertiga memiliki banyak pengalaman bertarung sebagai tim.",
  ui_story_5080_50800301_72_dialog_content = "Jika ada yang harus memimpin mereka dalam pertempuran... Itu adalah kamu.",
  ui_story_5080_50800301_73_dialog_content = "Rachel, kamu...",
  ui_story_5080_50800301_74_dialog_content = "Itu \"Kapten\" untukmu.",
  ui_story_5080_50800301_75_dialog_content = "Sekarang bersiaplah untuk pertempuran, Caelestite One!",
  ui_story_5080_50800302_1_dialog_content = "Awas, Kapten!",
  ui_story_5080_50800302_2_dialog_content = "Argh... Sekarang, White Lancer!",
  ui_story_5080_50800302_3_dialog_content = "Menembus Kerudung!",
  ui_story_5080_50800302_4_dialog_content = "Oh tidak, Kapten terluka! Kita harus...",
  ui_story_5080_50800302_5_dialog_content = "Fokus pada pertempuran, Hatchling Dua! Masih ada Eclipsite lain yang menuju ke arahmu!",
  ui_story_5080_50800302_6_dialog_content = "Eagle Hunter Satu, Eagle Hunter Dua, bersiap untuk intercept!",
  ui_story_5080_50800302_7_dialog_content = "Graaaaah—!",
  ui_story_5080_50800302_8_dialog_content = "... Tepat waktu.",
  ui_story_5080_50800302_9_dialog_content = "Hampir saja... Saya pikir kita sudah mendapatkan yang terakhir dari mereka.",
  ui_story_5080_50800302_10_dialog_content = "Apa itu tadi, Anak Pemangsa Dua?",
  ui_story_5080_50800302_11_dialog_content = "Aku...",
  ui_story_5080_50800302_12_dialog_content = "Jangan biarkan emosimu mengaburkan penilaianmu, prajurit.",
  ui_story_5080_50800302_13_dialog_content = "Meskipun aku terluka, misi tetap menjadi prioritas utama. Ingat itu.",
  ui_story_5080_50800302_14_dialog_content = "Kami berhasil membasmi satu skuadron Eclipsite yang kuat. Luka ini adalah harga terkecil yang bisa kami bayar untuk kemenangan kami.",
  ui_story_5080_50800302_15_dialog_content = "Katakan padaku... setelah menghabiskan begitu banyak waktu bersama teman-temanmu, apakah kamu telah lupa apa artinya menjadi seorang prajurit Illumina?",
  ui_story_5080_50800302_16_dialog_content = "T-Tidak, Nyonya... Sama sekali bukan begitu.",
  ui_story_5080_50800302_17_dialog_content = "Kamu terlalu keras, Rachel. Vice hanya khawatir tentangmu.",
  ui_story_5080_50800302_18_dialog_content = "...Nama kode, Caelestite Satu. Kehilangan fokus di medan perang bisa berakibat fatal. Bagaimana jika dia juga terluka baru saja?",
  ui_story_5080_50800302_19_dialog_content = "Jika kamu mengikuti instruksi saya dan misi masih berakhir dengan kegagalan, maka salahnya ada pada saya.",
  ui_story_5080_50800302_20_dialog_content = "Saya bertanggung jawab penuh atas keselamatan dan kesejahteraan bawahan saya... Selama kamu mempercayai saya.",
  ui_story_5080_50800302_21_dialog_content = "Sebagai kapten veteran, semua yang kamu katakan barusan benar adanya.",
  ui_story_5080_50800302_22_dialog_content = "Aku mengerti dan setuju dengan cara berpikirmu.",
  ui_story_5080_50800302_23_dialog_content = "Carleen?",
  ui_story_5080_50800302_24_dialog_content = "Oh... Vice, apakah kamu baik-baik saja?",
  ui_story_5080_50800302_25_dialog_content = "Ya...",
  ui_story_5080_50800302_26_dialog_content = "Eclipsites ini... Lihatlah mayat mereka...",
  ui_story_5080_50800302_27_dialog_content = "Kapten, Anda masih berdarah...",
  ui_story_5080_50800302_28_dialog_content = "Biarkan saja dia. Dia tidak akan mendengarkanmu juga.",
  ui_story_5080_50800302_29_dialog_content = "Dia memikul beban yang tak satu pun dari kita bisa mengerti.",
  ui_story_5080_50800302_30_dialog_content = "Aku tahu sorot matanya itu terlalu baik. Aku telah melihatnya begitu banyak kali di Lumopolis...",
  ui_story_5080_50800302_31_dialog_content = "Saya telah bertempur di garis depan untuk waktu yang lama sekarang, dan saya telah melihat lebih banyak Eclipsites daripada yang bisa saya hitung.",
  ui_story_5080_50800302_32_dialog_content = "Tapi, aku belum pernah bertemu dengan Eclipsite seperti ini sebelumnya.",
  ui_story_5080_50800302_33_dialog_content = "Berdasarkan penampilan kepala mereka, Eclipsite ini telah berada di luar Zona Gelap untuk waktu yang sangat lama.",
  ui_story_5080_50800302_34_dialog_content = "Selain itu, anatomi mereka menunjukkan bahwa evolusi mereka tidak diarahkan untuk bertarung.",
  ui_story_5080_50800302_35_dialog_content = "Daging mereka sangat tahan panas, dan tubuh mereka dapat menyimpan jumlah energi yang signifikan... Eclipsite ini berevolusi untuk beradaptasi dengan lingkungannya.",
  ui_story_5080_50800302_36_dialog_content = "Cukup aneh, mayat mereka bertahan jauh lebih lama dibandingkan Eclipsite lainnya...",
  ui_story_5080_50800302_37_dialog_content = "... Saya juga menyadari sesuatu. Mereka semua tampak sangat mirip.",
  ui_story_5080_50800302_38_dialog_content = "Sangat peka dari kamu untuk menyadari... Selain kecenderungan emosionalmu, kamu adalah kapten pengintaian yang layak.",
  ui_story_5080_50800302_39_dialog_content = "Maaf, tapi apa yang kamu maksud dengan \"sangat mirip\"? Bukankah kebanyakan Eclipsite terlihat sama?",
  ui_story_5080_50800302_40_dialog_content = "Saya akan bilang Eclipsite lainnya persis sama.",
  ui_story_5080_50800302_41_dialog_content = "Banyak prajurit berpikir bahwa Eclipsite tidak berkembang biak dalam arti normal.",
  ui_story_5080_50800302_42_dialog_content = "Di sisi lain, Eclipsites ini tampaknya berasal dari nenek moyang yang sama... mereka tampak serupa, tetapi mereka tidak persis sama.",
  ui_story_5080_50800302_43_dialog_content = "Ciri-ciri yang mereka miliki mirip dengan yang diturunkan dari orang tua ke anak.",
  ui_story_5080_50800302_44_dialog_content = "Catatan kami menunjukkan bahwa penyelidikan terakhir terhadap Eclipsite ini dilakukan lebih dari tiga puluh tahun yang lalu.",
  ui_story_5080_50800302_45_dialog_content = "Mereka lebih kecil dibandingkan yang diamati waktu itu, dan juga kurang kuat. Ini mungkin hasil dari bentuk reproduksi yang tidak diketahui...",
  ui_story_5080_50800302_46_dialog_content = "Benar.",
  ui_story_5080_50800302_47_dialog_content = "Selama <color=#FFB400>Krisis Darkover</color>, banyak orang di Rediesel Wrench yang melihat para Eclipsite ini. Dibandingkan dengan yang sebelumnya, Eclipsite yang kamu kalahkan hampir bisa dibilang lemah sekali.",
  ui_story_5080_50800302_48_dialog_content = "Jeriah?! Bagaimana ini—jangan muncul begitu saja seperti ini!",
  ui_story_5080_50800302_49_dialog_content = "Yah, toh aku ditugaskan untuk mengawasi seluruh gurun ini.",
  ui_story_5080_50800302_50_dialog_content = "Kamu... Bagaimana kamu bisa lolos dari deteksi Pemburu Elang Tiga?",
  ui_story_5080_50800302_51_dialog_content = "Oh, apakah itu nama dronemu? Sepertinya sedikit mengalami kerusakan.",
  ui_story_5080_50800302_52_dialog_content = "Apa? Pemburu Elang Tiga, kembali!",
  ui_story_5080_50800302_53_dialog_content = "Namun, aku tak pernah menyangka akan mendengar gunung berapi itu menggelegar seperti lima belas tahun lalu atau melihat orang-orang ini lagi...",
  ui_story_5080_50800302_54_dialog_content = "Apa yang Anda ketahui tentang mereka?",
  ui_story_5080_50800302_55_dialog_content = "Heheh, aku di sini mencari <color=#FFB400>jawaban</color>, sama seperti kamu.",
  ui_story_5080_50800302_56_dialog_content = "Pemancar Eagle Hunter Three telah rusak. Ada juga sesuatu yang aneh menempel padanya...",
  ui_story_5080_50800302_57_dialog_content = "Halo? Kalian bisa dengar aku? Halooo—",
  ui_story_5080_50800302_58_dialog_content = "Suara itu...",
  ui_story_5080_50800302_59_dialog_content = "Zeta?",
  ui_story_5080_50800302_60_dialog_content = "Terima kasih kepada <color=#FFB400>Master Senjata</color> yang brilian, kita bisa mengambil ini, uh... Apa kamu sebut itu lagi?",
  ui_story_5080_50800302_61_dialog_content = "Oh ya, kita \"meretas\" itu! Sungguh hal yang terdengar keren... Anyway, kami meretas drone Anda dan menempelkan komunikator ini padanya.",
  ui_story_5080_50800302_62_dialog_content = "Jika kamu ingin kami untuk <color=#FFB400>memperbaikinya</color>, temui kami di rumah Jeriah Sang Penyihir.",
  ui_story_5080_50800302_63_dialog_content = "... Jangan lihat aku! Apakah kamu benar-benar berpikir aku akan menciptakan nama seperti itu?",
  ui_story_5080_50800302_64_dialog_content = "Musuh telah merusak Eagle Hunter Three. Saya perlu memperbaikinya segera—",
  ui_story_5080_50800302_65_dialog_content = "!!!",
  ui_story_5080_50800302_66_dialog_content = "Toolkitku... Kapan ini terbakar?!",
  ui_story_5080_50800302_67_dialog_content = "Anda begitu fokus pada misi sebelumnya sehingga ketika Anda terluka, toolkit Anda juga terbakar.",
  ui_story_5080_50800302_68_dialog_content = "Mereka bilang mereka sedang menunggu kita di rumahmu. Apa hubunganmu dengan semua ini, Courier?",
  ui_story_5080_50800302_69_dialog_content = "Seperti yang saya katakan, saya hanya datang mencari jawaban. Saya tidak di sini untuk alasan lain.",
  ui_story_5080_50800302_70_dialog_content = "Namun, saya merasakan kehadiran yang sangat akrab dari Anda.",
  ui_story_5080_50800302_71_dialog_content = "Mengapa kita tidak semua kembali bersama? Kita bahkan mungkin menemukan beberapa jawaban lagi jika kita melakukannya.",
  ui_story_5080_50800302_72_dialog_content = "...",
  ui_story_5080_50800302_73_dialog_content = "Jeriah adalah anggota senior dari Serikat Kurir. Kita bisa mempercayainya.",
  ui_story_5080_50800302_74_dialog_content = "Kalau begitu, ayo.",
  ui_story_5080_50800401_1_dialog_content = "Maaf telah merepotkanmu seperti ini, Jeriah.",
  ui_story_5080_50800401_2_dialog_content = "Jangan khawatir tentang itu, sekarang duduklah. Ini bukan pertama kalinya juga.",
  ui_story_5080_50800401_3_dialog_content = "… Hmm…",
  ui_story_5080_50800401_4_dialog_content = "Ah! Turun! Kamp Rediesel Wrench tepat di depan!",
  ui_story_5080_50800401_5_dialog_content = "Jangan khawatir, mereka sedang sibuk sekarang.",
  ui_story_5080_50800401_6_dialog_content = "Argh, benda ini benar-benar rusak!!! Zeta, kau monster kecil... Tunggu saja sampai aku menangkapmu!!!",
  ui_story_5080_50800401_7_dialog_content = "Hei, bukankah itu mobil Jeriah? Hei, Jeriah! Makanan sudah siap, jika kamu ingin makan bersama kami!",
  ui_story_5080_50800401_8_dialog_content = "Lain kali!",
  ui_story_5080_50800401_9_dialog_content = "Silakan saja! Saya akan bertanya pada Azure saja.",
  ui_story_5080_50800401_10_dialog_content = "Pelan sedikit, Jeriah. Banyak jebakan di depan.",
  ui_story_5080_50800401_11_dialog_content = "Terima kasih atas pengingatannya.",
  ui_story_5080_50800401_12_dialog_content = "Yo Jeriah, lihat buku ini! Apakah benar tertulis \"Cara Menjadi Bos dari Rediesel Wrench\" di sampulnya? Para bajingan itu sebaiknya jangan coba-coba menggodaku hanya karena aku tidak bisa membaca dengan baik!",
  ui_story_5080_50800401_13_dialog_content = "Tentu saja tidak ada tulisan seperti itu. Jika Anda ingin mereka berhenti, maka belajarlah cara membaca.",
  ui_story_5080_50800401_14_dialog_content = "Terima kasih lagi karena telah membawa alat-alat itu pada lari terakhirmu, Jeriah. Saya akan mencoba menemukan waktu minggu ini untuk bekerja pada mobil Anda.",
  ui_story_5080_50800401_15_dialog_content = "Sepertinya sepakat.",
  ui_story_5080_50800401_16_dialog_content = "Jeriah... Saya pikir kamu telah berubah sejak terakhir kali saya melihatmu.",
  ui_story_5080_50800401_17_dialog_content = "Dulu kamu tinggal di tempat yang sulit ditemukan, tapi sekarang kamu akrab dengan setiap orang di Rediesel Wrench.",
  ui_story_5080_50800401_18_dialog_content = "Heheh, bagus sekali kamu bisa menyadari, PlayerName.",
  ui_story_5080_50800401_19_dialog_content = "Setiap orang berubah seiring waktu.",
  ui_story_5080_50800401_20_dialog_content = "Berkat kamu, aku juga mulai memikirkan untuk membangun hubungan dengan orang lain.",
  ui_story_5080_50800401_21_dialog_content = "... H-Hey, Vice? Sedikit sempit di belakang sini—",
  ui_story_5080_50800401_22_dialog_content = "Jika Anda ingin musik Anda mencapai setiap sudut dunia, maka Anda harus memainkannya keras, keras, KERAS!",
  ui_story_5080_50800401_23_dialog_content = "Silakan, berikan yang terbaik! Orang yang paling berisik di ruangan selalu yang paling bodoh!",
  ui_story_5080_50800401_24_dialog_content = "Kegagalan, frustrasi, dan ketakutan membuatmu lari dariku!",
  ui_story_5080_50800401_25_dialog_content = "Dan tidak ada yang membuat saya lebih marah daripada seorang pengecut!",
  ui_story_5080_50800401_26_dialog_content = "Zeta belum pandai mengemudi! Tapi seorang teman sejati tidak akan pernah marah!",
  ui_story_5080_50800401_27_dialog_content = "Ada masalah, Vice? Kamu terlihat tidak sehat...",
  ui_story_5080_50800401_28_dialog_content = "I-Ini bukan apa-apa... Kapten, sebenarnya Anda tidak seharusnya mencoba mengganti perban Anda saat perjalanan mobil yang berguncang seperti ini.",
  ui_story_5080_50800401_29_dialog_content = "Saya bisa merawat lukamu setelah kita tiba, jadi tolong jangan memaksakan diri.",
  ui_story_5080_50800401_30_dialog_content = "Tidak apa-apa, aku terbiasa bekerja sendiri.",
  ui_story_5080_50800401_31_dialog_content = "Ini tidak ada apa-apa... Lagipula, tak perlu terlalu sopan. Saya tidak jauh lebih tua dari kamu.",
  ui_story_5080_50800401_32_dialog_content = "Anda hanya setahun lebih muda dariku, namun Anda sudah berhasil menjadi kapten yang luar biasa. Tidak perlu terlalu hormat.",
  ui_story_5080_50800401_33_dialog_content = "Anda seorang pengintai Illumina, bukan? Dari pakaian Anda, saya asumsikan Anda juga seorang prajurit elit.",
  ui_story_5080_50800401_34_dialog_content = "Aku bisa melihat bahwa kamu berbeda dari burung kecil lainnya. Kamu adalah burung pemangsa sejati, bukan?",
  ui_story_5080_50800401_35_dialog_content = "Misi jenis apa yang memerlukan layanan dari seseorang seperti kamu?",
  ui_story_5080_50800401_36_dialog_content = "Itu sangat rahasia, dan juga bukan urusanmu.",
  ui_story_5080_50800401_37_dialog_content = "Aku benci mengatakannya, tapi terkadang takdir bisa sangat tidak terduga.",
  ui_story_5080_50800401_38_dialog_content = "Nah, saya yakin pasti ada alasan yang baik bagi seorang pemburu seperti dirimu untuk muncul di tempat seperti ini.",
  ui_story_5080_50800401_39_dialog_content = "Lihat, Sinsa muda, <color=#FFB400>jejak-jejak</color> itu lagi.",
  ui_story_5080_50800401_40_dialog_content = "Mereka persis seperti yang Kafka temukan. Ini pasti <color=#FFB400>jejak</color> yang Jeriah bicarakan sebelumnya.",
  ui_story_5080_50800401_41_dialog_content = "Aku sudah bilang jangan panggil aku seperti itu... Anyway, trek ini hanya gumpalan lava, bukan?",
  ui_story_5080_50800401_42_dialog_content = "Kenapa ada lava di tempat seperti ini?",
  ui_story_5080_50800401_43_dialog_content = "Mungkin kita akan menemukan lebih banyak jika kita terus melanjutkan?",
  ui_story_5080_50800401_44_dialog_content = "Hei, Roy! Ini adalah sisa-sisa Eclipsite, bukan? Mereka telah hancur berkeping-keping, tapi tidak bisa dipungkiri, bukan?",
  ui_story_5080_50800401_45_dialog_content = "Seseorang mengeluarkan mereka... Tapi yang lebih aneh adalah tubuh mereka masih belum hilang.",
  ui_story_5080_50800401_46_dialog_content = "Lihatlah mereka dengan baik, Roy. Apakah mereka sama dengan <color=#FFB400>Eclipsite</color> yang kamu lihat waktu itu?",
  ui_story_5080_50800401_47_dialog_content = "Lima belas tahun yang lalu, ketika kami mencoba melarikan diri... Ketika <color=#FFB400>bos</color> mencoba memberi kami lebih banyak waktu sebelum <color=#FFB400>Eclipsite itu</color>...",
  ui_story_5080_50800401_48_dialog_content = "Kaulah satu-satunya yang bisa mengonfirmasinya.",
  ui_story_5080_50800401_49_dialog_content = "Mereka tampak mirip dengan <color=#FFB400>Eclipsite itu</color> tetapi tidak sama. Jika ada, mereka tampak seperti <color=#FFB400>keturunannya</color>.",
  ui_story_5080_50800401_50_dialog_content = "Monster terkutuk... Jadi selama ini dia telah berkembang biak selama bertahun-tahun, huh?",
  ui_story_5080_50800401_51_dialog_content = "Waktunya berburu! Kita akan melacak <color=#FFB400>makhluk itu</color> kembali ke sarangnya dan menghancurkannya sekali dan untuk selamanya!",
  ui_story_5080_50800401_52_dialog_content = "Kita berada di sekitar gunung berapi, dan suhunya pasti jauh lebih panas. Sepertinya Jeriah yang muda benar—gunung berapi ini memang benar-benar bangun lagi.",
  ui_story_5080_50800401_53_dialog_content = "Mengapa jejaknya tiba-tiba menghilang di sini?",
  ui_story_5080_50800401_54_dialog_content = "Jejak-jejak ini milik Eclipsite yang berbeda... Mungkin mereka yang membuat kekacauan.",
  ui_story_5080_50800401_55_dialog_content = "Gunung Berapi Roaring sebenarnya terletak jauh di bawah tanah. Mungkin saja masih ada lebih banyak jalan tersembunyi tepat di bawah kaki kita.",
  ui_story_5080_50800401_56_dialog_content = "Dan tanpa target yang jelas, berlari tanpa arah akan sangat berbahaya.",
  ui_story_5080_50800401_57_dialog_content = "Berhenti bersembunyi, pengecut besar! Keluarlah dan hadapi aku!",
  ui_story_5080_50800401_58_dialog_content = "Aku bukan lagi bocah ingusan yang sama dari lima belas tahun yang lalu, sekarang tunjukkan dirimu! Saatnya mengakhiri ini!!!",
  ui_story_5080_50800401_59_dialog_content = "Sialan!!!",
  ui_story_5080_50800401_60_dialog_content = "Berhenti, Sinsa! Tempat ini bisa runtuh kapan saja—Ahhh—!",
  ui_story_5080_50800401_61_dialog_content = "<color=#e8d9bb>Dinding berguncang saat pukulan Sinsa bergema lebih dalam ke dalam gua. Tak lama, suara berjibaku dari banyak Eclipsite dapat terdengar.</color>",
  ui_story_5080_50800401_62_dialog_content = "Gua ini hampir runtuh, tapi sepertinya teman lama kita akhirnya keluar untuk menyambut kita!",
  ui_story_5080_50800401_63_dialog_content = "Lihat ke sana, Roy! Itu mereka, bukan?",
  ui_story_5080_50800401_64_dialog_content = "Butuh waktu yang cukup lama untuk mereka muncul! Sarang mereka pasti dekat sini!",
  ui_story_5080_50800401_65_dialog_content = "Hati-hati, Sinsa muda... Mari kita selesaikan ini dengan cepat.",
  ui_story_5080_50800401_66_dialog_content = "Hmph, aku tidak akan berhenti sampai kunci pas ku puas. Ayo, Roy!",
  ui_story_5080_50800402_1_dialog_content = "Masuk dan anggap saja rumah sendiri. Saya tidak punya banyak, karena saya hampir tidak pernah memiliki tamu—",
  ui_story_5080_50800402_2_dialog_content = "Lihatlah! Sebuah karya agung dari satu-satunya Zeta!",
  ui_story_5080_50800402_3_dialog_content = "Wah! Ini terlihat sangat hidup!",
  ui_story_5080_50800402_4_dialog_content = "Ha! Ini bukan apa-apa bagi seorang pejuang legendaris seperti saya!",
  ui_story_5080_50800402_5_dialog_content = "Memasuki dan menggantung sekelompok gambar lagi, begitu?",
  ui_story_5080_50800402_6_dialog_content = "Rumahmu terlalu kuno, Penyihir! Ambil gambar indah ini untuk mencerahkan ruang tinggalmu dengan senyuman yang lebih lebar, karena ini adalah sebuah kebaikan dari Zeta legendaris!",
  ui_story_5080_50800402_7_dialog_content = "... Tidak apa-apa. Coba untuk tidak merusak apa pun.",
  ui_story_5080_50800402_8_dialog_content = "Dan berhenti memanggilku Penyihir. Jika ada yang pantas mendapatkan gelar itu, itu adalah Nona Naroxel.",
  ui_story_5080_50800402_9_dialog_content = "Aku belum pernah bertemu dengannya, tapi namanya terdengar sangat keren! Oh, ngomong-ngomong, ini suratmu!",
  ui_story_5080_50800402_10_dialog_content = "Kami telah menyortir tumpukan amplop yang berantakan dan membuang sampah untuk Anda.",
  ui_story_5080_50800402_11_dialog_content = "Betulkah? Anda sangat baik.",
  ui_story_5080_50800402_12_dialog_content = "Heehee, sudah sepantasnya aku membalas budi dengan benar atas semua hadiah quest yang telah kamu berikan padaku!",
  ui_story_5080_50800402_13_dialog_content = "Tentu, sekarang bisakah kamu berhenti menodai surat dengan cat? Untuk kalian yang lain, jangan hanya berdiri di situ. Silakan duduk.",
  ui_story_5080_50800402_14_dialog_content = "Kamu benar-benar telah berubah banyak, Jeriah... Kamu tampak jauh lebih bahagia sekarang setelah kamu menjalin hubungan dengan begitu banyak orang lain.",
  ui_story_5080_50800402_15_dialog_content = "Dan aku tidak bisa lebih bahagia untukmu!",
  ui_story_5080_50800402_16_dialog_content = "Begitu ya? Anak-anak ini bisa jadi segelintir kadang-kadang, tapi setidaknya hari-hariku tidak sebosan dulu lagi.",
  ui_story_5080_50800402_17_dialog_content = "Eagle Hunter Three adalah drone bionik dengan kemampuan tempur dan pengintaian, dan merupakan produk dari teknologi paling canggih Illumina... Apakah kalian berdua yakin bisa memperbaikinya?",
  ui_story_5080_50800402_18_dialog_content = "Serahkan saja pada Penguasa Senjataku!",
  ui_story_5080_50800402_19_dialog_content = "Mari kita mulai dengan sedikit tes tusuk. Kiri, kanan, kiri... Yep, sepertinya pemancar rusak karena benturan yang berlebihan.",
  ui_story_5080_50800402_20_dialog_content = "Lihat? Tidak ada yang berada di luar jangkauan kemampuan Penguasa Senjata kita yang bangga!",
  ui_story_5080_50800402_21_dialog_content = "Nah, jadi? Kamu bisa melakukannya?",
  ui_story_5080_50800402_22_dialog_content = "Aku pasti akan berusaha sebaik mungkin!",
  ui_story_5080_50800402_23_dialog_content = "Pinjamkan aku alatmu. Aku seharusnya juga bisa membantu.",
  ui_story_5080_50800402_24_dialog_content = "Drone-drone ini adalah mitra saya dalam pertempuran... Saya tidak mau menyerahkan mereka begitu saja.",
  ui_story_5080_50800402_25_dialog_content = "Jangan terlalu khawatir, Eagle Huntershot sang Pahlawan Netralitas!",
  ui_story_5080_50800402_26_dialog_content = "...",
  ui_story_5080_50800402_27_dialog_content = "Jangan pedulikan Zeta, dia memang begitu.",
  ui_story_5080_50800402_28_dialog_content = "Sekarang saya tahu bahwa elang-elang ini adalah teman kesayanganmu, saya tidak akan menyentuh mereka sedikit pun.",
  ui_story_5080_50800402_29_dialog_content = "Ini salahku yang ini terluka, jadi biarkan aku yang merawatnya untukmu!",
  ui_story_5080_50800402_30_dialog_content = "Tapi kamu membuat Tiny One melakukan semua pekerjaan...",
  ui_story_5080_50800402_31_dialog_content = "K-Kita bertemu lagi, The Last Caelestite! Aku melihat takdir telah memberimu sekutu yang kuat lagi!",
  ui_story_5080_50800402_32_dialog_content = "Kamu bisa berbicara normal denganku, tahu kan?",
  ui_story_5080_50800402_33_dialog_content = "Tapi aku, pejuang legendaris Zeta, belum menyerah harapan!",
  ui_story_5080_50800402_34_dialog_content = "Sebagai Pahlawan Netralitas, jika kamu bisa bersekutu dengan The Last Caelestite, maka itu berarti kamu juga bisa bergabung dengan saya dalam pencarian saya!",
  ui_story_5080_50800402_35_dialog_content = "Jika itu berarti memiliki prajurit yang kuat seperti kamu di timku, aku bahkan akan mengabaikan masa lalu jahatmu!",
  ui_story_5080_50800402_36_dialog_content = "Aku...",
  ui_story_5080_50800402_37_dialog_content = "Tak perlu mengucapkan sepatah kata pun! Aku sudah tahu persis apa yang ada di pikiranmu!",
  ui_story_5080_50800402_38_dialog_content = "Saya yakin, seorang prajurit yang bangga seperti Anda tidak mudah diyakinkan.",
  ui_story_5080_50800402_39_dialog_content = "Tapi tidak apa-apa! Kamu dan aku bisa bertarung secara adil setelah Weapon Master-ku memperbaiki drone-mu.",
  ui_story_5080_50800402_40_dialog_content = "Dan setelah aku mengalahkanmu secara adil dan jujur... Kamu akan menjadi tambahan yang sangat berharga untuk grupku, dan penyihir itu tidak akan pernah berpeluang melawanku!",
  ui_story_5080_50800402_41_dialog_content = "Sumpahmu terdengar lebih seperti deklarasi perang bagi saya.",
  ui_story_5080_50800402_42_dialog_content = "Jangan terlalu khawatir tentang dia, Kapten. Zeta hanya memiliki cara berbicara yang... berbeda.",
  ui_story_5080_50800402_43_dialog_content = "B-Benar, Kapten. Setelah Eagle Hunter Three diperbaiki, kami akan permisi.",
  ui_story_5080_50800402_44_dialog_content = "Tidak apa-apa.",
  ui_story_5080_50800402_45_dialog_content = "Dengar itu, Zeta? Sekarang, kenapa kamu tidak minta maaf... Huh?",
  ui_story_5080_50800402_46_dialog_content = "Meskipun kamu berafiliasi dengan bandit Rediesel itu...",
  ui_story_5080_50800402_47_dialog_content = "Kamu tampaknya tidak sadar tentang masa lalu, jadi saya bersedia mengabaikannya kali ini.",
  ui_story_5080_50800402_48_dialog_content = "Kamu masih muda, jadi jangan biarkan mereka merusakmu dengan cara hidup liar mereka di gurun.",
  ui_story_5080_50800402_49_dialog_content = "Heheh, sepertinya kamu salah paham! Impianku adalah menjadi pahlawan legendaris, dan juga penyelamat gurun ini!",
  ui_story_5080_50800402_50_dialog_content = "Saya senang mendengar kamu memiliki tujuan yang mulia seperti itu. Saya tidak menyakitimu sebelumnya, bukan?",
  ui_story_5080_50800402_51_dialog_content = "Hah? T-Tidak sama sekali! Serangan seperti itu bahkan tidak bisa membuat goresan di tubuhku! Dan aku pasti tidak menangis karena takut atau apa pun itu!",
  ui_story_5080_50800402_52_dialog_content = "Bagus. Kamu memang seorang pejuang yang berani.",
  ui_story_5080_50800402_53_dialog_content = "Apakah saya melihat sesuatu...?",
  ui_story_5080_50800402_54_dialog_content = "Dia baru saja menangani Zeta dengan sempurna.",
  ui_story_5080_50800402_55_dialog_content = "... Aku tidak tahu dia bisa seperti ini.",
  ui_story_5080_50800402_56_dialog_content = "Mungkin dia persis seperti yang kamu deskripsikan sebelumnya, Carleen. Sangat masuk akal bagi seorang kapten yang berpengalaman dan dewasa untuk merawat bawahannya.",
  ui_story_5080_50800402_57_dialog_content = "Namun...",
  ui_story_5080_50800402_58_dialog_content = "(Apakah ini dia yang sebenarnya? Jika iya, lalu kenapa dia begitu dingin terhadap kita?)",
  ui_story_5080_50800402_59_dialog_content = "(Apakah dia menekan emosinya demi misi? Atau... bisakah dia menyembunyikan rasa sakit yang lebih dalam?)",
  ui_story_5080_50800402_60_dialog_content = "Menarik. Saya telah melihat burung-burung dari berbagai bentuk dan ukuran melewati padang pasir dalam rute migrasi mereka, tetapi ini adalah pertama kalinya saya melihat seekor falcon yang bisa menyembunyikan cakarnya.",
  ui_story_5080_50800402_61_dialog_content = "Uh, Zeta? Celah-celah drone ini penuh dengan pasir, yang menjelaskan mengapa beberapa rangkaian listriknya rusak.",
  ui_story_5080_50800402_62_dialog_content = "Saya tidak terbiasa bekerja pada hal-hal yang disetel dengan halus seperti ini. Memperbaikinya tidak akan mudah.",
  ui_story_5080_50800402_63_dialog_content = "A-Apa?",
  ui_story_5080_50800402_64_dialog_content = "Jika kamu tidak bisa melakukannya, berikan saja alatnya padaku agar aku bisa mengurusnya.",
  ui_story_5080_50800402_65_dialog_content = "S-Sekarang tunggu sebentar saja!",
  ui_story_5080_50800402_66_dialog_content = "Sebagai seorang prajurit yang bangga, aku telah berjanji bahwa aku akan bertanggung jawab penuh atas ini! Bagaimana lagi kita seharusnya melakukan pertempuran epik kita?!",
  ui_story_5080_50800402_67_dialog_content = "Kamu tidak bisa terbakar sebelum mengambil langkah pertama. Kamu tidak akan menyerah, kan?",
  ui_story_5080_50800402_68_dialog_content = "Tahu siapa yang hebat dalam pekerjaan seperti ini? Odi Maniak Mesin! Kamu tidak ingin kalah darinya, bukan?!",
  ui_story_5080_50800402_69_dialog_content = "Apa... Apa yang kau katakan?!",
  ui_story_5080_50800402_70_dialog_content = "Mundur dan lihat, semua kalian! Pekerjaan ini bukan apa-apa bagi orang seperti saya!",
  ui_story_5080_50800402_71_dialog_content = "Saya akan memperbaiki ini secepat kilat! Keterampilan Odi bahkan tidak bisa dibandingkan dengan saya!",
  ui_story_5080_50800402_72_dialog_content = "Saya rasa saya tahu bagaimana Zeta terus melibatkan Tiny One dalam rencananya sekarang.",
  ui_story_5080_50800402_73_dialog_content = "Sudah larut, dan sepertinya perbaikan tidak akan selesai dalam waktu dekat. Kalian semua harus tinggal di sini untuk malam ini.",
  ui_story_5080_50800402_74_dialog_content = "Kami tidak akan mengganggu, bukan?",
  ui_story_5080_50800402_75_dialog_content = "Jangan khawatir, saya sudah terbiasa dengan \"gangguan\" seperti ini sekarang.",
  ui_story_5080_50800402_76_dialog_content = "Selain itu... Saya rasa saya memiliki banyak hal untuk dibahas dengan burung pemangsa tertentu.",
  ui_story_5080_50800500_1_dialog_content = "<color=#e8d9bb>Saat malam turun di gurun, suhu mulai merosot drastis. Tiba-tiba, sebuah bukit pasir bergerak di lahan yang tampaknya kosong.</color>",
  ui_story_5080_50800500_2_dialog_content = "<color=#e8d9bb>Dengan suara berdesis, sosok itu meledak keluar dari bawah pasir!</color>",
  ui_story_5080_50800500_3_dialog_content = "Ach—Ptui!",
  ui_story_5080_50800500_4_dialog_content = "Ptui, ptui, ptui!",
  ui_story_5080_50800500_5_dialog_content = "*batuk* R-Roy...! Apa... Apa kau baik-baik saja?",
  ui_story_5080_50800500_6_dialog_content = "Urgh... Aku terlalu tua untuk hal semacam ini, Sinsa muda. Kali berikutnya jika kamu memutuskan untuk menjatuhkan gunung di atas kepala kita, setidaknya beri aku peringatan terlebih dahulu!",
  ui_story_5080_50800500_7_dialog_content = "Heheh—Sudah lama ya, sejak kita terakhir bersenang-senang seperti itu?",
  ui_story_5080_50800500_8_dialog_content = "Ya, tetapi lepas dari canda dan tawa, kita masih belum tahu lokasi pasti sarang mereka... Dan jumlah mereka juga bukan hal yang bisa ditertawakan.",
  ui_story_5080_50800500_9_dialog_content = "Tidak masalah, sekarang mari kita kembali ke kamp. Jika ada yang bertanya, katakan saja kita telah menghancurkan sarang Eclipsite dan meninggalkannya begitu saja.",
  ui_story_5080_50800500_10_dialog_content = "Tapi, apakah itu benar-benar baik? Kita telah membunuh banyak Eclipsite, tapi jelas itu bukan semua dari mereka.",
  ui_story_5080_50800500_11_dialog_content = "Dengan semua lorong bawah tanah yang melintasi tempat ini, mungkin saja monster-monster leleh itu bersarang di dalam gunung berapi.",
  ui_story_5080_50800500_12_dialog_content = "Maka ayo kita menerjang ke gunung berapi itu!",
  ui_story_5080_50800500_13_dialog_content = "Apakah itu benar-benar ide terbaik yang kita miliki?",
  ui_story_5080_50800500_14_dialog_content = "Aku khawatir Eclipsite yang sama, yang telah membunuh pemimpin kita, masih bersembunyi di suatu tempat di gunung berapi, yang lebih kuat dari apa pun yang pernah kita hadapi.",
  ui_story_5080_50800500_15_dialog_content = "Kita perlu memberi tahu semua orang segera dan memastikan mereka siap untuk bertarung saat waktunya tiba.",
  ui_story_5080_50800500_16_dialog_content = "Jika situasi menjadi berbahaya, tentu saja, saya akan memberi tahu mereka. Tetapi jika kita berhadapan dengan <color=#FFB400>hal itu</color>, saya tidak bisa membiarkan nakal kecil itu berada dalam bahaya.",
  ui_story_5080_50800500_17_dialog_content = "Apa yang begitu berbeda sekarang? Dulu kau juga hanya seorang punk berhidung meler, tapi sekarang kau adalah pemimpin kami.",
  ui_story_5080_50800500_18_dialog_content = "Aku merasakan itu, tapi tidak mungkin aku memberi tahu semua orang! Masalah kita dengan <color=#FFB400>monster itu</color>? Tidak, itu tidak ada hubungannya dengan anak-anak di rumah!",
  ui_story_5080_50800500_19_dialog_content = "Kunci pas ini diwariskan kepada saya, bersama dengan dendam itu. Sebagai pemimpin, tugas saya untuk membalas dendam atas bos lama kita dan saudara-saudara kita yang telah gugur. Itulah sebabnya...",
  ui_story_5080_50800500_20_dialog_content = "Berjanjilah padaku kamu tidak akan mengatakan apa-apa, Roy.",
  ui_story_5080_50800500_21_dialog_content = "Jadi kamu melakukannya untuk anak-anak, ya? Bos juga pernah mengatakan hal seperti itu di masa lalu.",
  ui_story_5080_50800500_22_dialog_content = "Meskipun kita cukup beruntung untuk bisa melarikan diri, hatiku telah dipenuhi penyesalan sejak saat itu.",
  ui_story_5080_50800500_23_dialog_content = "Jika kita membiarkan anak-anak itu melawan <color=#FFB400>makhluk itu</color>, dan mereka akhirnya merasakan keputusasaan dan putus asa yang sama seperti yang kita rasakan dulu, mereka akan berakhir seperti...",
  ui_story_5080_50800500_24_dialog_content = "Tidak, mereka tidak akan, Sinsa muda. Setelah semua yang telah kita lalui, jangan bilang kamu belum melihat betapa mereka telah tumbuh?",
  ui_story_5080_50800500_25_dialog_content = "Ya, beberapa dari mereka tidak berpengalaman atau tidak ingat apa yang terjadi waktu itu, tetapi anak-anak itu sudah menjadi anggota Rediesel Wrench yang bangga dan berpengalaman.",
  ui_story_5080_50800500_26_dialog_content = "Zeta baru berusia dua tahun ketika dia kehilangan orang tuanya. Dia tidak lebih tinggi dari ban saat itu, tetapi sekarang dia cukup kuat untuk menjelajahi gurun sendirian.",
  ui_story_5080_50800500_27_dialog_content = "Apakah kamu benar-benar akan merampas kesempatan darinya untuk menghadapi masa lalunya?",
  ui_story_5080_50800500_28_dialog_content = "Itu bukan yang saya maksud. Anda lebih mengenal saya daripada itu.",
  ui_story_5080_50800500_29_dialog_content = "Saya tahu, dan saya juga tahu bahwa Anda terlalu mendominasi untuk melepaskan tangan mereka.",
  ui_story_5080_50800500_30_dialog_content = "Apakah kamu ingat apa yang sering dikatakan oleh bos lama kita? Dia percaya bahwa kita harus menghormati setiap keputusan yang dibuat oleh seorang anak kecil, karena setiap orang berhak atas kebebasan.",
  ui_story_5080_50800500_31_dialog_content = "Sekarang anak-anak sudah dewasa, orang tua seperti kita perlu belajar bagaimana melepaskan.",
  ui_story_5080_50800500_32_dialog_content = "Ketika badai datang, kita harus menghadapinya bersama-sama, bukan mencoba melindungi mereka dari badai itu.",
  ui_story_5080_50800500_33_dialog_content = "Badai, huh...",
  ui_story_5080_50800500_34_dialog_content = "Sinsa! Roy!",
  ui_story_5080_50800500_35_dialog_content = "Eve? Kami baru saja membicarakan tentangmu. Apa yang sedang kamu lakukan di sini, hah?",
  ui_story_5080_50800500_36_dialog_content = "Saya sangat khawatir tentang kalian berdua, jadi kami datang ke sini untuk mencari kalian.",
  ui_story_5080_50800500_37_dialog_content = "Ayo, Sinsa! Mari pulang!",
  ui_story_5080_50800500_38_dialog_content = "Roy... Ketika badai datang kala itu, saya tidak ingin melepaskan Eve... Karena saya takut akan kehilangan dia...",
  ui_story_5080_50800500_39_dialog_content = "Tapi pada akhirnya, dialah yang menyelamatkan kita berdua...",
  ui_story_5080_50800500_40_dialog_content = "Tidak peduli apa yang terjadi, aku tidak akan pernah melepaskan keluargaku. Tapi... Aku pikir kamu mungkin benar tentang anak-anak ini. Mereka jauh lebih kuat dari yang bisa kita bayangkan.",
  ui_story_5080_50800500_41_dialog_content = "Ya, tapi itu tidak berarti saya harus membawa mereka bersama saya. Mereka bisa membantu dengan mempertahankan rumah kita.",
  ui_story_5080_50800500_42_dialog_content = "Pokoknya, kita bisa membahas penataan kerja setelah kita kembali... Hei, kenapa dengan saputangan itu?",
  ui_story_5080_50800500_43_dialog_content = "Saya sangat terharu, Sinsa muda... Kau sudah tumbuh begitu besar dalam lima belas tahun terakhir.",
  ui_story_5080_50800500_44_dialog_content = "Berhenti bicara sembarangan, kau idiot! Aku sudah menjadi pemimpin Wrench selama bertahun-tahun, jadi berhenti menganggapku sama dengan anak-anak lainnya!",
  ui_story_5080_50800500_45_dialog_content = "Kenapa kalian lama sekali? Ah, tidak apa-apa. Saatnya makan, jadi jangan menghalangi! Tunggu aku, Rabbie!",
  ui_story_5080_50800500_46_dialog_content = "Apa yang terjadi di luar sana? Kalian berdua tampak seperti baru saja berguling-guling di dalam tungku.",
  ui_story_5080_50800500_47_dialog_content = "Tidak ada yang terjadi, kami hanya pergi untuk melihat gunung berapi.",
  ui_story_5080_50800500_48_dialog_content = "Tch—Kudengar Azure akan kembali segera. Lain kali kalian pergi sendiri, ingatlah untuk membawa kami beberapa minuman keras.",
  ui_story_5080_50800500_49_dialog_content = "Ayo kita makan saja! Aku hampir kelaparan di sini!",
  ui_story_5080_50800500_50_dialog_content = "Hah? Di mana Zeta dan Tiny One?",
  ui_story_5080_50800500_51_dialog_content = "Tidak tahu, tapi dendeng kadal ini sangat enak! Mungkin mereka mengalami masalah dan harus melarikan diri melalui terowongan rahasia?",
  ui_story_5080_50800500_52_dialog_content = "Aku agak khawatir, mengingat sudah begitu larut.",
  ui_story_5080_50800500_53_dialog_content = "Hei Barbara, kamu tadi membuat keributan dengan mereka. Ada ide kemana mereka pergi?",
  ui_story_5080_50800500_54_dialog_content = "Hmm... Semuanya terlalu heboh untuk diingat dengan jelas, tapi aku rasa mereka pergi dengan Jeriah.",
  ui_story_5080_50800500_55_dialog_content = "Dia mengatakan sesuatu tentang merekrut anggota baru ke dalam partainya. Apakah dia maksud wanita dari sebelumnya?",
  ui_story_5080_50800500_56_dialog_content = "Dia pergi dengan Jeriah, eh... Jika mereka ingin mencari prajurit Illumina itu, maka saya katakan biarkan mereka.",
  ui_story_5080_50800500_57_dialog_content = "Tapi kita hampir tidak tahu apa-apa tentang wanita itu. Dan dengan semua aktivitas gunung berapi ini, terlalu berbahaya untuk hanya meninggalkan mereka sendirian di luar sana...",
  ui_story_5080_50800500_58_dialog_content = "Kami akan pergi mencari mereka. Kami hampir selesai makan.",
  ui_story_5080_50800500_59_dialog_content = "Kamu akan membutuhkan pengemudi yang baik. Aku juga ikut!",
  ui_story_5080_50800500_60_dialog_content = "Sebaiknya kita...",
  ui_story_5080_50800500_61_dialog_content = "Kamu yakin bisa mengemudi di malam hari tanpa membuat mobil terbalik?",
  ui_story_5080_50800500_62_dialog_content = "Aku ikut! Lagipula, aku tidak perlu makan banyak sekarang ini.",
  ui_story_5080_50800500_63_dialog_content = "Aku masih berpikir kita harus...",
  ui_story_5080_50800500_64_dialog_content = "Aku juga ikut! Nyanyian penuh semangatku akan memandu anak-anak kecil kita sepanjang malam!",
  ui_story_5080_50800500_65_dialog_content = "Itu hanya karena suaranya akan terlalu keras dan mengganggu untuk diabaikan.",
  ui_story_5080_50800500_66_dialog_content = "Kamu ingin mengatakan itu langsung ke wajahku?!",
  ui_story_5080_50800500_67_dialog_content = "Cukup!",
  ui_story_5080_50800500_68_dialog_content = "Aku akan mencarinya, jadi kalian semua diam dan makan saja!",
  ui_story_5080_50800500_69_dialog_content = "Silakan makan, semua orang! Huh? Ada yang salah dengan makanannya?",
  ui_story_5080_50800500_70_dialog_content = "Maafkan jika aku terdengar kasar, tapi apakah ini benar-benar dihitung sebagai makanan... Hah?!",
  ui_story_5080_50800500_71_dialog_content = "Wow! Sandworm goreng ini jauh lebih renyah dari sebelumnya!",
  ui_story_5080_50800500_72_dialog_content = "Dan ekor ular panggang ini sangat lembut dan segar!",
  ui_story_5080_50800500_73_dialog_content = "Mengapa kamu tidak makan, Carleen? Jangan khawatir, Vice dan saya juga merasa begitu sebelumnya, tetapi makanan ini benar-benar lezat!",
  ui_story_5080_50800500_74_dialog_content = "A-Aku menghargai perhatianmu... Tapi bisakah kau memegang satai itu sedikit lebih jauh dariku?",
  ui_story_5080_50800500_75_dialog_content = "Rasa ini...!!!",
  ui_story_5080_50800500_76_dialog_content = "Ini bahkan lebih baik dari makanan kaleng terbaik milik militer kita!",
  ui_story_5080_50800500_77_dialog_content = "Sepertinya, Illumina Federation bisa sedikit lebih baik dalam memperlakukan prajuritnya...",
  ui_story_5080_50800500_78_dialog_content = "Saya tidak menyangka Anda akan menikmati makanan Gurun Rediesel sebanyak ini, Kapten.",
  ui_story_5080_50800500_79_dialog_content = "Sejujurnya, saya tidak terlalu tertarik dengan kenikmatan kuliner.",
  ui_story_5080_50800500_80_dialog_content = "Ahh, itu sangat menyenangkan! Saatnya kembali bekerja, jadi jangan ganggu aku!",
  ui_story_5080_50800500_81_dialog_content = "Jadi kamu juga suka tikus pasir madu panggang seperti saya, ya?",
  ui_story_5080_50800500_82_dialog_content = "Heheh, bahkan seorang tentara yang menyeramkan dari Illumina pun tak bisa menolak nikmatnya makanan enak!",
  ui_story_5080_50800500_83_dialog_content = "Jika ada yang jahat, itu adalah Rediesel Wrench. Saya menolak untuk menerima... bahwa kita memiliki kesamaan apapun.",
  ui_story_5080_50800500_84_dialog_content = "(Hah? Kenapa tiba-tiba dia jadi begitu jahat?)",
  ui_story_5080_50800500_85_dialog_content = "Benarkah? Karena menurut saya, hebat kita memiliki kesamaan! Jangan takut, penyelamat legendaris dunia ini akan menyelamatkanmu dari organisasi jahatmu juga!",
  ui_story_5080_50800500_86_dialog_content = "Selalu ada tempat untukmu di kendaraanku!",
  ui_story_5080_50800500_87_dialog_content = "Kedengarannya keren, kan? Aku selalu ingin mengatakan itu!",
  ui_story_5080_50800500_88_dialog_content = "Rediesel Wrench... tidak lebih dari geng pengecut yang memalukan dari Illumina.",
  ui_story_5080_50800500_89_dialog_content = "Tidak hanya mereka melupakan identitas dan kehormatan mereka, tetapi mereka juga terjerumus ke dalam kejahatan dan mengarahkan senjata mereka ke warga sipil.",
  ui_story_5080_50800500_90_dialog_content = "Tidak ada yang bisa menyetujui tindakan mereka. Bahkan... anak kecil seperti kamu.",
  ui_story_5080_50800500_91_dialog_content = "Aku bukan anak kecil, dan kami tidak seperti itu! Kamu pasti salah mengira kami dengan kelompok lain!",
  ui_story_5080_50800500_92_dialog_content = "Dan membiarkan anak-anak yang tidak bersalah seperti kamu jatuh ke tangan mereka adalah kesalahan Illumina, itulah sebabnya kami akan melakukan segala yang kami bisa untuk memperbaiki keadaan.",
  ui_story_5080_50800500_93_dialog_content = "Dan dengan itu, apakah kamu maksud menyerahkan mereka ke <color=#FFB400>Eksekutor</color> Illumina?",
  ui_story_5080_50800500_94_dialog_content = "Apa?! Aku belum pernah mendengar hal seperti itu sebelumnya...!",
  ui_story_5080_50800500_95_dialog_content = "Sebelum gurun ini memiliki nama, ketika <color=#FFB400>Rediesel Wrench</color> masih belum ada, Illumina memiliki cukup banyak penghianat yang datang ke tempat ini.",
  ui_story_5080_50800500_96_dialog_content = "Keinginan mereka akan kebebasan mendorong mereka untuk meninggalkan Illumina dan mencari perlindungan di tanah yang keras dan tandus ini.",
  ui_story_5080_50800500_97_dialog_content = "Tapi pada akhirnya, <color=#FFB400>Executioners</color> dari Illumina mengejar mereka ke gurun dan membasmi mereka.",
  ui_story_5080_50800500_98_dialog_content = "Astaga...",
  ui_story_5080_50800500_99_dialog_content = "Illumina adalah alasan mengapa penduduk asli gurun ini mengambil senjata, dan mengapa mereka begitu curiga satu sama lain.",
  ui_story_5080_50800500_100_dialog_content = "... Tapi itu semua adalah masa lalu. Grand Marshal saat ini tidak menyetujui metode-metode tersebut tetapi menganjurkan sistem baru.",
  ui_story_5080_50800500_101_dialog_content = "Illumina tidak lagi memburu para desertirnya! Selama bandit Rediesel menyerahkan senjata mereka dan kembali dengan damai, tidak ada yang akan—",
  ui_story_5080_50800500_102_dialog_content = "Selama Krisis Darkover, Sinsa dan yang lainnya bahkan pergi ke Kota Gannon untuk memberikan bantuan... Sayangnya, mereka tidak pernah dibalas dengan layak atas kebaikan mereka.",
  ui_story_5080_50800500_103_dialog_content = "Pasti ada semacam kesalahpahaman. Saya yakin kedua belah pihak bisa mencapai kesepakatan jika mereka hanya mendiskusikan hal-hal dengan wajar.",
  ui_story_5080_50800500_104_dialog_content = "Jika memungkinkan... Saya lebih memilih untuk tidak menyakiti kalian. Tapi sebagai orang luar, mustahil bagi kalian untuk memahami arti penting dari desersi.",
  ui_story_5080_50800500_105_dialog_content = "Keputusan egois satu orang bisa merugikan banyak orang lain... Itu bisa merusak segalanya, termasuk keluarga mereka.",
  ui_story_5080_50800500_106_dialog_content = "(Dia tampaknya terguncang secara aneh sekarang... Apa yang mungkin dia ingat?)",
  ui_story_5080_50800500_107_dialog_content = "Begitukah? Kenapa sayap burung harus diikat hanya karena ia lahir di Illumina?",
  ui_story_5080_50800500_108_dialog_content = "Saya lahir di Rediesel Wrench, meskipun saya tidak pernah benar-benar cocok dengan mereka. Meski begitu, saya bisa melihat bahwa mereka hanyalah sekelompok orang bodoh yang mencintai kebebasan.",
  ui_story_5080_50800500_109_dialog_content = "Saya diperbolehkan pergi dan membangun hidup saya sendiri kapan pun saya mau. Semua dari mereka juga memiliki pilihan mereka sendiri untuk dibuat.",
  ui_story_5080_50800500_110_dialog_content = "Meminta mereka untuk kembali ke Illumina dan dikendalikan oleh sistem, kehilangan individualitas mereka. Saya tidak bisa membayangkan mereka akan setuju dengan itu.",
  ui_story_5080_50800500_111_dialog_content = "Tidak adil jika mengatakan begitu, aku sama sekali tidak merasa seperti itu terhadap Illumina!",
  ui_story_5080_50800500_112_dialog_content = "Jadi kita tidak bisa melakukan apa saja di Illumina? Bagaimana dengan balapan liar? Apakah balapan liar masih diizinkan?",
  ui_story_5080_50800500_113_dialog_content = "Nah, Undercity memiliki banyak mesin yang berharga dan halus, jadi... tidak.",
  ui_story_5080_50800500_114_dialog_content = "Kedengarannya mengerikan! Aku tidak akan pernah ingin pergi ke sana!",
  ui_story_5080_50800500_115_dialog_content = "I-Ini benar-benar tidak terlalu buruk! Kami memiliki berbagai jenis kompetisi lainnya juga! Dan kamu selalu bisa mendaftar untuk tugas transportasi!",
  ui_story_5080_50800500_116_dialog_content = "Misi Illumina adalah melindungi semua Aurorian. Pengorbanan individu diperlukan demi kebaikan bersama.",
  ui_story_5080_50800500_117_dialog_content = "Oh, burung pemangsa kecilku. Illumina pasti tidak mengenal lelah untuk melatih prajurit yang begitu teguh seperti ini.",
  ui_story_5080_50800500_118_dialog_content = "Tidak perlu mempersulit hal-hal. Aku berasal dari garis keturunan pahlawan yang bangga, dan keyakinan keluargaku pada Illumina lebih kuat daripada yang bisa kamu bayangkan.",
  ui_story_5080_50800500_119_dialog_content = "Tidak ada pengorbanan yang terlalu besar untuk kejayaan Illumina! Hidup kita adalah sementara, tetapi kejayaan adalah abadi!",
  ui_story_5080_50800500_120_dialog_content = "Dan ketika semua telah dikorbankan, siapa yang akan tersisa untuk mengenang para pahlawan?",
  ui_story_5080_50800500_121_dialog_content = "Kamu bilang kamu berasal dari keturunan pahlawan yang panjang, tapi apakah kamu ingat apa yang telah dicapai oleh kakek dari kakekmu? Atau apa yang dia nikmati dalam hidupnya?",
  ui_story_5080_50800500_122_dialog_content = "Saya yakin kamu diberitahu tentang kehebatan leluhurmu sejak usia muda... Tapi apa yang sebenarnya kamu ketahui tentang keberadaan mereka?",
  ui_story_5080_50800500_123_dialog_content = "Aku...",
  ui_story_5080_50800500_124_dialog_content = "... Meskipun perbuatan berani mereka mungkin terlupakan seiring waktu, buah dari pencapaian seorang pahlawan akan selalu ada.",
  ui_story_5080_50800500_125_dialog_content = "Dalam dunia yang dikuasai oleh Eclipsites, kita harus terus hidup, tumbuh, dan meneruskan keinginan kita... Sama seperti banyak pahlawan yang telah gugur sebelum kita. ",
  ui_story_5080_50800500_126_dialog_content = "Meski saya mungkin tidak mengenal semua nama mereka, pengorbanan dan pencapaian mereka tetap hidup melalui kita, pewaris Astra.",
  ui_story_5080_50800500_127_dialog_content = "Para pahlawan itu telah mempengaruhi saya, memberi saya tekad untuk menyeberangi ribuan jalan untuk sampai di sini... Saya tidak memiliki penyesalan!",
  ui_story_5080_50800500_128_dialog_content = "Cerita dan keberadaan mereka tidak akan pernah benar-benar hilang! Mereka akan terus mencapai hati dan kehidupan orang lain dengan lebih banyak cara daripada yang bisa kita bayangkan!",
  ui_story_5080_50800500_129_dialog_content = "Carleen...",
  ui_story_5080_50800500_130_dialog_content = "Putri Lumopolis benar-benar tahu cara memberikan pidato yang sangat baik.",
  ui_story_5080_50800500_131_dialog_content = "White Lancer... Anda benar sekali.",
  ui_story_5080_50800500_132_dialog_content = "Hei bos, kau tidak akan masuk? Kamu telah menguping selama ini!",
  ui_story_5080_50800500_133_dialog_content = "Ssst! Diam, Tiny One. Aku masih mencoba mendengar...",
  ui_story_5080_50800500_134_dialog_content = "White Lancer membuat poin yang sangat baik! Aku... pernah menjadi bagian dari skuad prajurit setia yang rela memberikan nyawa mereka demi keadilan. Mereka memberiku kebaikan, dan aku akan selalu bangga akan hal itu.",
  ui_story_5080_50800500_135_dialog_content = "Contoh mereka adalah satu yang patut untuk ditiru.",
  ui_story_5080_50800500_136_dialog_content = "Betul sekali... Karena jika aku tidak, aku...",
  ui_story_5080_50800500_137_dialog_content = "Hah? Kemana kamu pergi, Kapten—",
  ui_story_5080_50800500_138_dialog_content = "Beri dia ruang.",
  ui_story_5080_50800500_139_dialog_content = "Hmph... Zeta, Tiny One, mari kita pulang.",
  ui_story_5080_50800500_140_dialog_content = "P-Pemimpin bandit Rediesel?! Kapan kamu...",
  ui_story_5080_50800500_141_dialog_content = "Selesai! Saya memperbaikinya! Ohhh, tunggu sampai Odi mengetahui bahwa saya telah memperbaiki sesuatu yang belum pernah dia kerjakan sebelumnya!!!",
  ui_story_5080_50800500_142_dialog_content = "Tapi <color=#FFB400>Kesatria Terkutuk</color>... Saya benar-benar ingin tinggal...",
  ui_story_5080_50800500_143_dialog_content = "...Lanjutkan saja. Kalian sudah dewasa setelah semua ini. Tolong awasi bocah-bocah ini, bisa, Jeriah?",
  ui_story_5080_50800500_144_dialog_content = "Tunggu! Kamu... Kamu tahu tentang Eclipsite itu, bukan?",
  ui_story_5080_50800500_145_dialog_content = "Setelah bertahun-tahun berkeliaran di gurun, Rediesel Wrench pasti tahu lebih banyak tentang keberadaannya. Bisakah kamu beri tahu saya di mana menemukan sarangnya?",
  ui_story_5080_50800500_146_dialog_content = "Kamu bukan prajurit Illumina pertama yang mencari itu, sama sekali bukan... Tapi sayangnya, tidak ada satu pun dari mereka yang pernah kembali.",
  ui_story_5080_50800500_147_dialog_content = "Kamu tidak lebih istimewa dibanding mereka, jadi sudahlah menyerah. Tidak ada alasan untuk membahayakan dirimu sendiri demi misi.",
  ui_story_5080_50800500_148_dialog_content = "Membuatku kesal mengetahui bahwa setelah bertahun-tahun, mereka masih mengirim orang-orang ke kematian mereka.",
  ui_story_5080_50800500_149_dialog_content = "Kamu tidak mengerti! Inilah perintah kami sebagai prajurit, dan harta karun tak terbayangkan yang tersembunyi di dalam Wilayah Rahasia layak untuk setiap pengorbanan noble!",
  ui_story_5080_50800500_150_dialog_content = "Kamu terus mengucapkan kata itu berulang-ulang, tapi apakah kamu benar-benar tahu apa arti \"pengorbanan\"?",
  ui_story_5080_50800500_151_dialog_content = "Ayo, katakan padaku apa menurutmu artinya!",
  ui_story_5080_50800500_152_dialog_content = "Ini adalah kesediaan untuk mengorbankan nyawa sendiri demi kejayaan Illumina dan kebaikan yang lebih besar!",
  ui_story_5080_50800500_153_dialog_content = "Serta... tekad untuk menyelesaikan misi dengan segala cara!",
  ui_story_5080_50800500_154_dialog_content = "Hahahaha—",
  ui_story_5080_50800500_155_dialog_content = "Mengapa kamu tertawa? Kamu pikir ini bercanda?!",
  ui_story_5080_50800500_156_dialog_content = "Ya, benar. Kau memang tak ada bedanya dengan orang-orang yang datang sebelummu, jadi pulanglah. Gurun ini sudah merenggut terlalu banyak nyawa.",
  ui_story_5080_50800500_157_dialog_content = "Ayo pergi, Tiny One.",
  ui_story_5080_50800500_158_dialog_content = "Kamu tidak tahu apa-apa... Kita tidak sama... Kamu tidak tahu apa jenis tekad yang membawaku ke sini...",
  ui_story_5080_50800500_159_dialog_content = "Aku tidak akan mempermalukan keluarga ku lagi... Aku harus... membersihkan aib kita...",
  ui_story_5080_50800601_1_dialog_content = "Apakah kamu tidak akan tidur, Vice?",
  ui_story_5080_50800601_2_dialog_content = "Menguap—Aku masih perlu menyelesaikan laporan misi hari ini... Tapi jangan khawatir tentang aku! Kamu pergi dan istirahatlah.",
  ui_story_5080_50800601_3_dialog_content = "Menurutku, kamu tampak cukup lelah.",
  ui_story_5080_50800601_4_dialog_content = "Ini adalah kesempatan besar untuk bekerja dengan Kapten... Ini adalah pengalaman yang sangat langka...",
  ui_story_5080_50800601_5_dialog_content = "Saya harus... mencatat semuanya...",
  ui_story_5080_50800601_6_dialog_content = "Sini, biarkan aku membantu kamu dengan itu.",
  ui_story_5080_50800601_7_dialog_content = "Nng... Itu tidak... akan berhasil...",
  ui_story_5080_50800601_8_dialog_content = "Tidak apa-apa. Hanya sedikit lagi yang harus ditulis. Aku akan menyelesaikannya untukmu.",
  ui_story_5080_50800601_9_dialog_content = "Setelah menghabiskan begitu banyak waktu dengan Vice, bahkan PlayerName sudah terbiasa melakukan ini untuknya.",
  ui_story_5080_50800601_10_dialog_content = "Aku tidak yakin kapan ini terjadi, tapi mungkin karena semua ceramah yang dia berikan padaku... Jangan khawatir, ini tidak akan lama. Pergi dan tidurlah, Carleen.",
  ui_story_5080_50800601_11_dialog_content = "Sepertinya kau masih ada yang mengganjal di pikiran... Tapi jika kau memaksa. Selamat malam.",
  ui_story_5080_50800601_12_dialog_content = "(Saya hanya perlu menambahkan satu bagian terakhir, dan laporannya akan selesai.)",
  ui_story_5080_50800601_13_dialog_content = "Tapi tunggu, masih ada lagi... Dan ini juga bagian terbaiknya!",
  ui_story_5080_50800601_14_dialog_content = "(Apakah itu suara Zeta? Aku bisa mendengarnya dari sini... Bagaimana dia masih memiliki energi sebanyak ini?)",
  ui_story_5080_50800601_15_dialog_content = "Dan begitu gadis penyihir dan saya melompat ke dalam mobil balap kami!",
  ui_story_5080_50800601_16_dialog_content = "(Siapa yang dia ajak bicara? Aku sudah selesai menulis sekarang... Sepertinya tidak ada salahnya melihat sebentar.)",
  ui_story_5080_50800601_17_dialog_content = "Wuuss! Mobilku melaju ke depan dan kita nyaris terhindar dari cakar naga itu! Bang! Brak!",
  ui_story_5080_50800601_18_dialog_content = "Saya menabrak naga itu dengan mobilku dan menghantamnya terbang! Bahkan sang penyihir pun tidak punya pilihan selain mengakui kekuatanku!",
  ui_story_5080_50800601_19_dialog_content = "(Sepertinya dia sedikit berlebihan... Huh? Apakah itu... Rachel? Apakah Zeta mengganggunya saat dia sedang bertugas jaga?)",
  ui_story_5080_50800601_20_dialog_content = "Oh, dan aku yakin kamu tidak tahu ini! Ketika aku menyalakan mesinku, banyak sekali kadal mulai merayap keluar dari pasir!",
  ui_story_5080_50800601_21_dialog_content = "Kadal-kadal itu rasanya paling enak! Mereka bahkan lebih lembut daripada yang kita makan hari ini!",
  ui_story_5080_50800601_22_dialog_content = "Kami semua cukup pandai memasak di sini, jadi saya yakin kamu juga akan menyukainya!",
  ui_story_5080_50800601_23_dialog_content = "... Mau coba salah satu biskuit militer padat buatanku?",
  ui_story_5080_50800601_24_dialog_content = "Tidak, terima kasih, itu terlihat mengerikan.",
  ui_story_5080_50800601_25_dialog_content = "Yang mengingatkan saya! Pernahkah saya memberi tahu Anda bahwa saya mengadakan balapan sendiri?",
  ui_story_5080_50800601_26_dialog_content = "Tidak seperti gadis penyihir jahat itu, saya tidak bergantung pada Caelestite Terakhir untuk mencapai garis finis!",
  ui_story_5080_50800601_27_dialog_content = "Kemuliaan melintasi gurun yang tak kenal ampun ini hanya milikku sendiri!",
  ui_story_5080_50800601_28_dialog_content = "Itu mengesankan. Saya tidak akan pernah tahu itu hanya dengan melihat Anda.",
  ui_story_5080_50800601_29_dialog_content = "Heheh, keren kan? Kesatria legendaris Zeta dan prestasi-prestasinya yang gemilang cukup untuk meyakinkan penjahat mana pun untuk meninggalkan jalan jahat mereka! Itulah sebabnya kamu harus tetap bersamaku!",
  ui_story_5080_50800601_30_dialog_content = "Kemampuanmu untuk bertahan sendiri di padang pasir selama ini akan membuatmu menjadi navigator yang luar biasa di reli saya!",
  ui_story_5080_50800601_31_dialog_content = "Naiklah ke mobilku, dan kita bisa berbagi kejayaan memenangkan balapan berikutnya!",
  ui_story_5080_50800601_32_dialog_content = "Kemuliaan, huh... Saya hanya benar-benar mahir dengan mesin. Apakah saya benar-benar pilihan yang baik untuk tim Anda?",
  ui_story_5080_50800601_33_dialog_content = "Tentu saja! Serahkan saja pelatihan itu padaku, dan aku akan membentukmu menjadi anggota legendaris di kruku!",
  ui_story_5080_50800601_34_dialog_content = "Kamu bisa bertanggung jawab atas... Apa namanya lagi? Itu seperti peta, tapi dengan banyak informasi lainnya... Buku jalan! Aku akan mengajari kamu cara membuat buku jalan yang benar untuk reli kita!",
  ui_story_5080_50800601_35_dialog_content = "Tentu. Itu terdengar cukup menarik bagi saya.",
  ui_story_5080_50800601_36_dialog_content = "(Apakah ini nyata? Mereka berdua benar-benar sedang berbicara...)",
  ui_story_5080_50800601_37_dialog_content = "Ada banyak hal menarik lainnya di gurun ini juga! Mulai besok, saya akan mengajari kamu semua tentang mereka!",
  ui_story_5080_50800601_38_dialog_content = "Dan setelah kita melatihmu... Akhirnya saya akan bisa mengalahkan penyihir itu...",
  ui_story_5080_50800601_39_dialog_content = "Tapi sekarang, sudah waktunya bagi saya untuk tidur... Selamat malam...",
  ui_story_5080_50800601_40_dialog_content = "<color=#828282>Bum!</color>",
  ui_story_5080_50800601_41_dialog_content = "Jujur... Itu tidak sakit?",
  ui_story_5080_50800601_42_dialog_content = "Banyak istirahatlah... Selamat malam.",
  ui_story_5080_50800601_43_dialog_content = "(Satu menit dia dingin dan jauh, dan menit berikutnya dia hangat dan baik... Mana yang sebenarnya kamu, Rachel?)",
  ui_story_5080_50800601_44_dialog_content = "(Mungkin sekarang adalah waktu yang tepat untuk berbicara dengannya... Huh? Emosi kuat itu... Mereka kembali lagi...)",
  ui_story_5080_50800601_45_option_content = "Sense Rachel",
  ui_story_5080_50800601_46_dialog_content = "Target telah ditemukan, dan misi kita sekarang telah selesai. Kita berhasil, Kapten!",
  ui_story_5080_50800601_47_dialog_content = "Kerja yang bagus... Tapi jangan lengah dulu, selama reruntuhan ini masih dipenuhi oleh Eclipsite. Kita perlu keluar dari sini.",
  ui_story_5080_50800601_48_dialog_content = "Green Owl, Red Kestrel, ambil inti data dan mundur melalui rute infiltrasi kita.",
  ui_story_5080_50800601_49_dialog_content = "Ini cukup berat, Kapten. Biarkan aku yang membawanya.",
  ui_story_5080_50800601_50_dialog_content = "Tidak apa-apa, cukup berjaga-jaga. Kita perlu berkumpul kembali dengan yang lain di titik evakuasi.",
  ui_story_5080_50800601_51_dialog_content = "Kapten, tampaknya ada gangguan dalam barisan Eclipsite.",
  ui_story_5080_50800601_52_dialog_content = "Mereka bergerak ke arah yang berbeda... Mengapa mereka berkumpul seperti itu?",
  ui_story_5080_50800601_53_dialog_content = "Tidak... Mereka mulai menyerang ke arah kita!",
  ui_story_5080_50800601_54_dialog_content = "Lari!",
  ui_story_5080_50800601_55_dialog_content = "Burung Hantu Hijau, Kestrel Merah, masuk! Bagaimana situasi di titik evakuasi?",
  ui_story_5080_50800601_56_dialog_content = "Para Eclipsite tampaknya berkumpul di satu titik... Ini buruk, Kapten! Mereka mendekat ke posisi Anda!",
  ui_story_5080_50800601_57_dialog_content = "Tetap tenang dan ikuti rencana. Kita akan segera sampai, jadi pastikan rute pelarian kita tetap terbuka!",
  ui_story_5080_50800601_58_dialog_content = "Jangan repotkan dirimu dengan Eclipsites itu, White Goose! Ayo pergi!",
  ui_story_5080_50800601_59_dialog_content = "Antar Kapten keluar dari sini, Gray Wing! Saya akan mengalihkan perhatian mereka dari Anda!",
  ui_story_5080_50800601_60_dialog_content = "Apa yang kamu bicarakan? Kita akan keluar dari sini bersama! Kapten, kamu harus membuang inti data, atau kita tidak akan bisa melarikan diri dari Eclipsites!",
  ui_story_5080_50800601_61_dialog_content = "Bagaimana mereka bisa mengetahui posisi kita? Sepertinya mereka mencoba melindungi inti...",
  ui_story_5080_50800601_62_dialog_content = "Tetap ikuti, White Goose! Jangan keluyuran sendirian lagi!",
  ui_story_5080_50800601_63_dialog_content = "Tapi Kapten... Jika terus begini, kita tidak akan pernah berhasil...",
  ui_story_5080_50800601_64_dialog_content = "<color=#e8d9bb>Dor, dor, dor—</color>",
  ui_story_5080_50800601_65_dialog_content = "Ke sini, Kapten!",
  ui_story_5080_50800601_66_dialog_content = "Itu Burung Hantu Hijau dan Kestrel Merah!",
  ui_story_5080_50800601_67_dialog_content = "Bodoh! Aku sudah memberi perintah jelas untuk menjaga pintu keluar, jadi apa yang kalian lakukan di sini?!",
  ui_story_5080_50800601_68_dialog_content = "Kamu tidak akan berhasil jika kami tidak melanggar perintahmu, Kapten.",
  ui_story_5080_50800601_69_dialog_content = "Jika kamu akan mendisiplinkan kami, setidaknya tunda sampai kami mencapai tempat yang aman!",
  ui_story_5080_50800601_70_dialog_content = "Idiot...",
  ui_story_5080_50800601_71_dialog_content = "Aku penasaran kenapa lama sekali! Apakah kamu telah membawa barang berat ini sepanjang waktu, Kapten?",
  ui_story_5080_50800601_72_dialog_content = "Jadi ini adalah intinya, ya? Benda ini tidak benar-benar portabel, Kapten. Kita seharusnya...",
  ui_story_5080_50800601_73_dialog_content = "Tidak! Misi adalah yang utama! Data di inti ini memiliki kekuatan untuk mengubah seluruh Illumina... Skuad Eagleeye tidak boleh gagal, meskipun itu menempatkan nyawa kita dalam bahaya!",
  ui_story_5080_50800601_74_dialog_content = "Jika kita gagal, itu akan membuat kita semua menjadi pengkhianat... Aku tidak akan... Membiarkan kamu menimpakan rasa malu seperti itu pada keluargamu.",
  ui_story_5080_50800601_75_dialog_content = "Jalan keluar ada di depan, dan aku akan mengurus yang belakang. Sekarang pergi! Pastikan data core itu kembali ke Illumina!",
  ui_story_5080_50800601_76_dialog_content = "Tidak bisa, Kapten!",
  ui_story_5080_50800601_77_dialog_content = "Apakah kamu kembali menentang perintah, Gray Wing?!",
  ui_story_5080_50800601_78_dialog_content = "Menurut Bab 6, Subseksi 31 dari Dekret Penyelesaian Misi Illumina, seorang wakil kapten pasukan dapat menggantikan perintah kapten selama sisanya pasukan setuju!",
  ui_story_5080_50800601_79_dialog_content = "Tidak pernah ada pengintai yang lebih baik daripada kamu, Kapten. Meskipun kita bisa melewati pintu keluar, tidak ada jaminan bahwa kita akan kembali ke permukaan dengan selamat.",
  ui_story_5080_50800601_80_dialog_content = "Sebagai wakil kapten, saya mengajukan suatu pemungutan suara! Semua yang setuju untuk mendukung Kapten dan menutupi pelariannya, katakan \"aye\"!",
  ui_story_5080_50800601_81_dialog_content = "Iya!",
  ui_story_5080_50800601_82_dialog_content = "Iya.",
  ui_story_5080_50800601_83_dialog_content = "Kau...",
  ui_story_5080_50800601_84_dialog_content = "\"Misi didahulukan dari segalanya,\" ingat? Maaf, Kapten... Tapi misimu sekarang berbeda.",
  ui_story_5080_50800601_85_dialog_content = "Ambil inti dan kembali ke Illumina. Keluargamu masih menunggumu, bukan?",
  ui_story_5080_50800601_86_dialog_content = "Jangan khawatir, kami akan berada tepat di belakangmu.",
  ui_story_5080_50800601_87_dialog_content = "Sekarang berangkatlah, Kapten!",
  ui_story_5080_50800601_88_dialog_content = "Aku… aku…",
  ui_story_5080_50800601_89_dialog_content = "Bertahanlah, Eagle Hunters! Aku akan memanggil bala bantuan segera setelah aku mencapai permukaan!",
  ui_story_5080_50800601_90_dialog_content = "Eclipsites akan datang. Ada yang merasa takut?",
  ui_story_5080_50800601_91_dialog_content = "Kapten berhasil keluar dengan selamat. Apa lagi yang perlu ditakuti sekarang?",
  ui_story_5080_50800601_92_dialog_content = "Ledakkan pintu keluar. Kita tidak bisa membiarkan satu pun monster ini lolos dari kita.",
  ui_story_5080_50800601_93_dialog_content = "Apa?! Tidak, Gray Wing! Jangan lakukan itu—!",
  ui_story_5080_50800601_94_dialog_content = "Kamu selalu menanggung beban berat di pundakmu, Kapten... Aku benar-benar minta maaf... Karena membuatmu menanggung sedikit lebih banyak.",
  ui_story_5080_50800601_95_dialog_content = "Nyalakan itu!!!",
  ui_story_5080_50800602_1_dialog_content = "(Itu adalah Rachel... Apakah ini alasan dia selalu bersikeras bekerja sendiri? Jadi ketika kami ditugaskan untuk membantunya...)",
  ui_story_5080_50800602_2_dialog_content = "(Alasan dia terus menyembunyikan emosinya dan memperlakukan kami dengan dingin... Apakah karena dia takut kehilangan kita?)",
  ui_story_5080_50800602_3_dialog_content = "(Setelah melihat masa lalunya yang penuh penderitaan, apakah sebaiknya aku terus mencoba berbicara dengannya tentang itu?)",
  ui_story_5080_50800602_4_dialog_content = "Sayap Abu-abu, Angsa Putih, Burung Hantu Hijau, Kestrel Merah... Apakah kamu... Masih mengawasiku?",
  ui_story_5080_50800602_5_dialog_content = "<color=#828282>Bum!</color>",
  ui_story_5080_50800602_6_dialog_content = "Siapa itu? Berani-beraninya kamu menguping—",
  ui_story_5080_50800602_7_dialog_content = "Meong!",
  ui_story_5080_50800602_8_dialog_content = "Kucing?",
  ui_story_5080_50800602_9_dialog_content = "... Kemari, pus kecil.",
  ui_story_5080_50800602_10_dialog_content = "Mau ikan kering?",
  ui_story_5080_50800602_11_dialog_content = "Pus baik... Apakah kamu peliharaan Kurir?",
  ui_story_5080_50800602_12_dialog_content = "Bulumu sangat lembut dan halus. Sungguh kucing kecil yang cantik.",
  ui_story_5080_50800602_13_dialog_content = "Apakah kerincingan tanda nama anjing ini menarik perhatianmu? Kamu juga ingin berbicara dengan mereka, 'kan?",
  ui_story_5080_50800602_14_dialog_content = "Kucing itu diadopsi oleh Roy beberapa waktu lalu dan dibesarkan di markas Rediesel Wrench. Kadang-kadang ia bisa menjadi cukup manja.",
  ui_story_5080_50800602_15_dialog_content = "Gah!",
  ui_story_5080_50800602_16_dialog_content = "Meong—!",
  ui_story_5080_50800602_17_dialog_content = "K-Kapan kau... Kamu tidak melihat apa-apa, kan?!",
  ui_story_5080_50800602_18_dialog_content = "Jangan khawatir, aku telah bertemu dengan berbagai macam orang selama perjalanan ku. Aku tidak merasa satu cara atau lainnya tentang preferensi kamu.",
  ui_story_5080_50800602_19_dialog_content = "Lagipula, aku sudah tahu sejak lama bahwa kamu tidak sekeras batu seperti yang tampak.",
  ui_story_5080_50800602_20_dialog_content = "Tapi jika kamu tidak keberatan aku mengatakannya, menurutku penampilan dinginmu hanya semakin menyakiti sekutumu.",
  ui_story_5080_50800602_21_dialog_content = "... Apa yang membuatmu begitu berbeda? Kamu telah menolak Rediesel Wrench, bukan?",
  ui_story_5080_50800602_22_dialog_content = "Mendorong mereka pergi? Sama sekali tidak. Saya hanya bergerak sedikit lebih jauh dari semua kebisingan dan keributan.",
  ui_story_5080_50800602_23_dialog_content = "Seperti yang aku duga, kamu mirip dengan <color=#FFB400>orang itu</color>. Tidak heran kamu memberikan perasaan yang familiar.",
  ui_story_5080_50800602_24_dialog_content = "\"Orang itu\"?",
  ui_story_5080_50800602_25_dialog_content = "Ada banyak mantan prajurit dari Illumina di Rediesel Wrench, tetapi salah satunya sangat berbeda.",
  ui_story_5080_50800602_26_dialog_content = "Sama seperti kamu, dia adalah seorang prajurit elit yang berdedikasi dalam misi khusus, yang memimpin timnya ke gurun di usia yang sangat muda.",
  ui_story_5080_50800602_27_dialog_content = "Apakah dia... Selamat dari penjelajahannya di Wilayah Rahasia di sini?",
  ui_story_5080_50800602_28_dialog_content = "Apakah kamu ingat namanya, atau nama skuadnya? Mungkin saja aku tahu dia.",
  ui_story_5080_50800602_29_dialog_content = "Namanya...? Ketika aku pertama kali bertemu dengannya, dia sudah meninggalkan masa lalunya. Aku tidak yakin apakah nama yang dia gunakan sekarang adalah nama aslinya.",
  ui_story_5080_50800602_30_dialog_content = "Tapi saya ingat nama skuadnya: Skuad Freebird. Itu nama yang sama yang membuat saya sangat iri pada burung dan kemampuan mereka untuk terbang bebas di langit.",
  ui_story_5080_50800602_31_dialog_content = "\"Squad Freebird\"?!",
  ui_story_5080_50800602_32_dialog_content = "(Bukankah itu nama regu yang sedang dicari Rachel sekarang?)",
  ui_story_5080_50800602_33_dialog_content = "Orang itu... juga melarikan diri ke padang pasir? Jadi, dia tidak hanya menjadi pengkhianat, dia juga bergabung dengan Rediesel Wrench—",
  ui_story_5080_50800602_34_dialog_content = "Kamu salah, Jeriah: Saya tidak seperti orang itu. Dia mungkin seorang desertir yang tidak tahu malu, tapi saya tidak!",
  ui_story_5080_50800602_35_dialog_content = "Maaf, burung pemangsa kecilku, tapi aku khawatir kamu lah yang salah.",
  ui_story_5080_50800602_36_dialog_content = "Wanita itu bukanlah orang yang tidak tahu malu atau seorang desertir. Sampai akhirnya, dia adalah salah satu orang yang paling bangga yang pernah saya kenal.",
  ui_story_5080_50800602_37_dialog_content = "Semangatnya yang membara seolah-olah sebanding dengan warna merah tombak yang dipegangnya. Bahkan setelah ia menyerahkannya kepada Sinsa, warnanya tidak sedikit pun memudar.",
  ui_story_5080_50800602_38_dialog_content = "Jika itu yang kamu percaya... Maka saya punya kisah untuk dibagikan kepada kamu.",
  ui_story_5080_50800602_39_dialog_content = "Ini pertama kali diceritakan kepada saya oleh <color=#FFB400>bibi saya</color>, yang pernah menjadi anggota dari Skuad Freebird—",
  ui_story_5080_50800602_40_dialog_content = "Tiga puluh tahun yang lalu, Illumina membentuk tim pasukan khusus yang dikenal sebagai Skuad Freebird.",
  ui_story_5080_50800602_41_dialog_content = "Anggota elit yang dipilih secara khusus dalam tim ini ditugaskan untuk menjalankan misi yang mustahil dilakukan oleh skuad lain.",
  ui_story_5080_50800602_42_dialog_content = "Meskipun tantangan yang mereka hadapi di setiap operasi tak tertandingi, Skuad Freebird berhasil mempertahankan tingkat keberhasilan misi yang sempurna. Bergabung dengan skuad mereka adalah aspirasi terbesar setiap prajurit.",
  ui_story_5080_50800602_43_dialog_content = "Jika skuad itu masih ada, saya yakin kamu akan menjadi kandidat yang sempurna untuk itu.",
  ui_story_5080_50800602_44_dialog_content = "Namun kemudian mereka ditugaskan untuk misi rahasia tingkat tinggi, yang ternyata menjadi misi terakhir mereka. Bibi saya dan rekan-rekannya mempertaruhkan nyawa mereka untuk itu...",
  ui_story_5080_50800602_45_dialog_content = "Harga yang mereka bayar tidak terbayangkan tetapi pada akhirnya... Kapten mereka mengkhianati mereka. Dia meninggalkan misi tanpa izin dan membawa sisa dari para penyintas kembali ke Illumina sebagai seorang <color=#FFB400>pengkhianat</color>.",
  ui_story_5080_50800602_46_dialog_content = "Tidak lama setelah itu, dia benar-benar membelot dari Illumina, yang membuat bibiku jatuh ke dalam jurang putus asa!",
  ui_story_5080_50800602_47_dialog_content = "Mereka mencapnya sebagai pengkhianat, dan menuduhnya sebagai separatis. Dicopot dari kehormatannya dan diturunkan pangkatnya berkali-kali, dia dihina oleh semua orang di sekitarnya!",
  ui_story_5080_50800602_48_dialog_content = "Dia menolak untuk pulang karena takut membebani keluarga kami, dan hubungannya dengan ayah saya hancur—",
  ui_story_5080_50800602_49_dialog_content = "Tapi meskipun bibi saya telah berkorban banyak, kehormatan keluarga kami masih...",
  ui_story_5080_50800602_50_dialog_content = "(Rachel...)",
  ui_story_5080_50800602_51_option_content = "Merasakan Kenangan Rachel",
  ui_story_5080_50800602_52_dialog_content = "Hei lihat! Putri pengkhianat itu kembali lagi!",
  ui_story_5080_50800602_53_dialog_content = "Jangan bilang dia mencoba masuk ke Museum. Tempat itu adalah tempat kami menghormati pahlawan sejati kami! Pengkhianat tidak diizinkan masuk ke sana!",
  ui_story_5080_50800602_54_dialog_content = "Mengingat sejarah pengkhianatan keluarganya, sulit membayangkan bahwa dia dibesarkan dengan cara yang berbeda.",
  ui_story_5080_50800602_55_dialog_content = "Bisakah kita benar-benar mempercayai seseorang seperti dia untuk melindungi punggung kita, Kapten?",
  ui_story_5080_50800602_56_dialog_content = "Rachel? Gadis kecil yang tampak kurus itu? Saya rasa dia tidak memiliki tekad untuk ini...",
  ui_story_5080_50800602_57_dialog_content = "Tidak mungkin! Dia tidak baik! Buang dia—",
  ui_story_5080_50800602_58_dialog_content = "Aku bukan orang seperti itu! Aku akan membuktikannya... Aku akan membuktikan kepada semua orang!",
  ui_story_5080_50800602_59_dialog_content = "Aku tahu kamu bukan, Rachel. Kamu sudah menjadi wanita muda yang luar biasa dan seorang soldier yang istimewa. Kamu tidak perlu membuktikan apa pun kepada siapa pun.",
  ui_story_5080_50800602_60_dialog_content = "Tidak, Tante... Aku... Aku tidak bermaksud seperti itu...",
  ui_story_5080_50800602_61_dialog_content = "Tidak apa-apa, Rachel. Aku tidak peduli apa yang orang lain katakan, dan kamu juga seharusnya tidak.",
  ui_story_5080_50800602_62_dialog_content = "Pertahankan semangat itu di hatimu, dan tunjukkan pada mereka bahwa kamu lebih baik daripada bibi tak berguna itu.",
  ui_story_5080_50800602_63_dialog_content = "Bibi... maafkan aku...",
  ui_story_5080_50800602_64_dialog_content = "Berdiri dan lihatlah aku, Rachel. Semua ini bukan salahmu.",
  ui_story_5080_50800602_65_dialog_content = "Ini salahku karena telah membawa begitu banyak masalah ke dalam hidupmu. Kamu akan menghadapi lebih banyak kritik di masa depan.",
  ui_story_5080_50800602_66_dialog_content = "Tapi kamu tidak boleh membiarkan itu menjatuhkanmu. Jangan pernah menyerah pada apa yang mereka katakan tentangmu. Lawanlah dengan keras dan sepenuh hati, seperti saat ini.",
  ui_story_5080_50800602_67_dialog_content = "Aku tahu kau akan jauh lebih hebat daripada yang pernah bisa kuharapkan.",
  ui_story_5080_50800602_68_dialog_content = "Percayalah pada dirimu sendiri, Rachel. Tidak peduli keputusan apa yang kamu buat, tetaplah pada mereka sampai akhir yang pahit—Dan jangan dengarkan apa yang orang lain katakan tentangmu!",
  ui_story_5080_50800602_69_dialog_content = "Bibi saya terpaksa hidup sendirian di luar, tetapi dia selalu memperlakukan saya seperti anak kandungnya... Dan itulah sebabnya... Saya tidak akan pernah bisa memaafkan orang itu atas apa yang telah dia lakukan padanya.",
  ui_story_5080_50800602_70_dialog_content = "Jadi, aku memutuskan untuk menjadi lebih kuat, melampaui batasku dan mengatasi belenggu masa lalu keluargaku... Aku tidak ingin tragedi itu terulang lagi.",
  ui_story_5080_50800602_71_dialog_content = "Dia berasal dari keluarga para desertir, jadi dia pasti akan menyerah kadang-kadang, bukan?",
  ui_story_5080_50800602_72_dialog_content = "Tidak mungkin! Saya pikir dia sangat keren karena sangat gigih, jadi berhentilah membicarakannya di belakang.",
  ui_story_5080_50800602_73_dialog_content = "Jadi, apakah ada rekrutan baru yang menarik perhatianmu, Hiiro?",
  ui_story_5080_50800602_74_dialog_content = "Sama sekali tidak. Tidak satupun dari mereka yang mampu mengimbangi jadwal latihan saya.",
  ui_story_5080_50800602_75_dialog_content = "Aku rasa kamu terlalu keras pada mereka... Tunggu, bagaimana dengan <color=#FFB400>dia</color>? Jangan bilang <color=#FFB400>dia</color> juga tidak memenuhi standar?",
  ui_story_5080_50800602_76_dialog_content = "<color=#FFB400>Gadis itu</color>... Dia terlalu banyak mengharapkan dari dirinya sendiri, mengingat dia tidak sebugar teman-temannya. Memaksakan diri seperti ini tidak akan pernah berhasil untuknya.",
  ui_story_5080_50800602_77_dialog_content = "Saya telah mencoba untuk mendiskualifikasinya sebelum dia melakukan kerusakan permanen pada dirinya sendiri. Namun, tidak peduli seberapa sulit saya membuatnya untuk dia, dia dengan keras kepala menolak untuk menyerah.",
  ui_story_5080_50800602_78_dialog_content = "Dalam hal kebugaran, dia sama sekali tidak menonjol, tapi pada akhirnya... Dia adalah satu-satunya yang bisa mengimbangi saya.",
  ui_story_5080_50800602_79_dialog_content = "Akademi itu dipenuhi dengan rumor tentang dia dan keluarganya, tetapi sedikit demi sedikit, teman sekelasnya mulai menghargainya.",
  ui_story_5080_50800602_80_dialog_content = "Saya tidak yakin apakah saya harus memujinya atau tidak.",
  ui_story_5080_50800602_81_dialog_content = "Seorang prajurit yang tak pernah gagal bangkit setelah jatuh berkali-kali... Bagiku, dia memiliki potensi untuk menjadi pahlawan, Hiiro.",
  ui_story_5080_50800602_82_dialog_content = "Kamu tidak bisa terus menyangkalnya lagi, jadi akui saja tekadnya dan jaga dia dengan baik.",
  ui_story_5080_50800602_83_dialog_content = "Tidak mungkin dia akan membiarkan dirinya didiskualifikasi.",
  ui_story_5080_50800602_84_dialog_content = "Kadet Rachel! Sebagai penghargaan atas kinerja luar biasa dan semangat tak terkalahkanmu, kamu telah dipilih secara khusus oleh Commander Hiiro untuk bergabung dengan jajaran Legiun ke-3!",
  ui_story_5080_50800602_85_dialog_content = "(Jadi ini Rachel... Inilah cara dia berjuang naik pangkat... Dan menjadi kapten elit yang layak mendapat penghormatan dari setiap orang.)",
  ui_story_5080_50800602_86_dialog_content = "Saya mengerti... Kamu telah menderita banyak untuk menjadi burung pemangsa seperti sekarang ini.",
  ui_story_5080_50800602_87_dialog_content = "Heh, kalau begitu kamu bebas melihatnya sebagai pengkhianat jika kamu mau. Lagipula, kita hanya bertukar beberapa kata sebelum dia menghilang dari hidup kita selamanya.",
  ui_story_5080_50800602_88_dialog_content = "Dengan secerdik itu, aku benar-benar berharap dia berhasil melarikan diri saat itu... Mungkin dia bisa memberiku jawaban yang aku cari.",
  ui_story_5080_50800602_89_dialog_content = "Jawaban apa?",
  ui_story_5080_50800602_90_dialog_content = "Gurun ini luas, bukan? Kamu bisa berjaga sepanjang malam yang tak terbatas dan masih hanya melihat sebagian kecil dari tempat ini.",
  ui_story_5080_50800602_91_dialog_content = "Keluasannya juga yang membuatnya begitu kosong.",
  ui_story_5080_50800602_92_dialog_content = "Kehampaan ini... Apakah itu sebabnya kamu tidak pernah bisa cocok dengan orang-orang itu?",
  ui_story_5080_50800602_93_dialog_content = "Kamu bilang kamu telah bepergian ke banyak tempat, dan namun kamu tidak pernah menemukan tempat di mana kamu benar-benar merasa berpulang, bukan? Jadi kamu kembali ke tempat ini...",
  ui_story_5080_50800602_94_dialog_content = "Memang benar bahwa gurun selalu terasa asing bagi saya, dan saya tidak pernah sejalan dengan orang-orang berdarah panas dari Rediesel Wrench.",
  ui_story_5080_50800602_95_dialog_content = "Mereka sangat berisik dan liar setiap harinya, tapi apakah mereka benar-benar mencari arti dari hidup?",
  ui_story_5080_50800602_96_dialog_content = "Aku khawatir suatu hari nanti mereka akan sadar dan menyadari betapa banyak waktu hidup mereka yang terbuang. Memikirkannya saja sudah menakutkan.",
  ui_story_5080_50800602_97_dialog_content = "Orang-orang ditakdirkan untuk berpisah, dan pesta harus berakhir suatu hari nanti. Tidak peduli seberapa cerah kita bersinar dalam hidup, kita semua akan kembali menjadi ketiadaan. Menakutkan, bukan?",
  ui_story_5080_50800602_98_dialog_content = "Jadi, kau berlama-lama di gurun ini, tempat yang bukan rumahmu dan juga bukan tanah yang asing.",
  ui_story_5080_50800602_99_dialog_content = "Kamu hanyalah burung kesepian lainnya di Gurun Rediesel, sama seperti aku.",
  ui_story_5080_50800602_100_dialog_content = "Sebenarnya kamu sangat pandai memahami sudut pandang orang lain, tahu? Dan itu adalah tanda seorang kapten yang benar-benar hebat.",
  ui_story_5080_50800602_101_dialog_content = "(Andai saja Vice bangun untuk melihat ini! Saya harus mencari kesempatan untuk memberitahunya tentang ini besok.)",
  ui_story_5080_50800602_102_dialog_content = "Saya masih seorang anak ketika orang itu masih hidup. Dia mengajari saya banyak hal, dan membuka mata saya terhadap kebesaran dunia.",
  ui_story_5080_50800602_103_dialog_content = "Dia juga memotivasiku untuk mencari kehidupan yang bebas dengan sepenuh hati. Aku ingin menemukan makna hidupku dan berlari menuju masa depan yang penuh dengan kemungkinan-kemungkinan tak terbatas.",
  ui_story_5080_50800602_104_dialog_content = "Tapi kemudian dia meninggal tanpa kata lain. Sosoknya yang bangga dan kuat hanya menjadi gambar kabur lainnya dalam ingatan kami.",
  ui_story_5080_50800602_105_dialog_content = "Jadi apa yang bisa saya capai? Setelah memutuskan hubungan dengan orang tua saya dan Rediesel Wrench, tidak ada tempat lagi untuk saya di dunia ini.",
  ui_story_5080_50800602_106_dialog_content = "Dan sementara aku terjebak dalam kehampaan yang mendalam ini, orang-orang bodoh itu terus melanjutkan hidup tanpa kekhawatiran sedikit pun. Huh... Sungguh aku berharap aku tahu apa yang harus dilakukan.",
  ui_story_5080_50800602_107_dialog_content = "Kenapa kamu memberitahuku semua ini?",
  ui_story_5080_50800602_108_dialog_content = "Karena aku tidak yakin bisa membicarakan ini dengan orang lain.",
  ui_story_5080_50800602_109_dialog_content = "Kurasa pasti ada alasan yang lebih baik untuk berbagi pikiranku denganmu. Mungkin karena kamu sangat mengingatkanku padanya... Atau mungkin kamu mengingatkanku pada diriku sendiri?",
  ui_story_5080_50800602_110_dialog_content = "Apakah kamu yakin kamu bukan hanya... Sebuah burung kecil yang tersesat masuk ke gurun?",
  ui_story_5080_50800602_111_dialog_content = "Sebagian dari diriku berharap bahwa kamu di sini untuk mencari para desertir. Dengan begitu, kamu bisa menemukan orang itu dan memberinya pelajaran karena menghilang dari hidup kita seperti itu.",
  ui_story_5080_50800602_112_dialog_content = "Jika bukan karena dia, mungkin aku tidak akan begitu frustrasi dalam hidup. Bagaimanapun, dia telah mengubah Rediesel Wrench dari sekelompok idiot yang tidak terhormat menjadi sekelompok orang yang bebas dan ceria...",
  ui_story_5080_50800602_113_dialog_content = "Jadi, mengapa aku tidak bisa menjadi seperti mereka?",
  ui_story_5080_50800602_114_dialog_content = "Jeriah, kamu...",
  ui_story_5080_50800602_115_dialog_content = "Aku akan membawa Zeta ke tempat tidur. Kamu harus turun dan tidur juga.",
  ui_story_5080_50800602_116_dialog_content = "Kamu bilang bahwa segalanya harus kembali ke ketiadaan... Namun kamu masih bersedia memeluk dan menggendongnya.",
  ui_story_5080_50800602_117_dialog_content = "Tidak ada pilihan lain. Setelah mereka melumuri rumahku dengan \"karya seni\" mereka, mustahil untuk mengabaikan mereka.",
  ui_story_5080_50800602_118_dialog_content = "Gurun menjadi dingin di malam hari. Aku akan minta Speaker menggantikanmu, jadi istirahatlah.",
  ui_story_5080_50800602_119_dialog_content = "Juga... Teman Caelestite kita yang malang akan membeku sampai mati jika kita tetap di sini lebih lama.",
  ui_story_5080_50800602_120_dialog_content = "(Dia tahu saya ada di sini sepanjang waktu!)",
  ui_story_5080_50800602_121_dialog_content = "(Aku harus keluar dari sini... Aduh!)",
  ui_story_5080_50800602_122_dialog_content = "Si-Siapa yang meninggalkan ember ini penuh air di sini?!",
  ui_story_5080_50800701_1_dialog_content = "Bangun. Misi ini belum berakhir.",
  ui_story_5080_50800701_2_dialog_content = "Menguap... Selamat pagi, Kapten.",
  ui_story_5080_50800701_3_dialog_content = "... Selamat pagi, sekarang cuci muka dengan air dan bangunlah!",
  ui_story_5080_50800701_4_dialog_content = "Y-Ya, Bu!",
  ui_story_5080_50800701_5_dialog_content = "Kami akan melanjutkan pekerjaan pengintaian hari ini! Bangun dan bertemu dalam sepuluh menit!",
  ui_story_5080_50800701_6_dialog_content = "Izinkan aku bergabung denganmu.",
  ui_story_5080_50800701_7_dialog_content = "Jika kamu sedang mencari Eclipsite tertentu, mungkin saya memiliki beberapa informasi yang bisa berguna.",
  ui_story_5080_50800701_8_dialog_content = "Kenapa tiba-tiba kamu tertarik untuk ikut bersama kami? Ini pasti bukan hanya karena penasaran, kan?",
  ui_story_5080_50800701_9_dialog_content = "Meskipun semua hal pasti akan kembali ke ketiadaan, aku masih ingin melihat bagaimana ini berakhir.",
  ui_story_5080_50800701_10_dialog_content = "Kamu tidak akan menolakku, 'kan?",
  ui_story_5080_50800701_11_dialog_content = "Selain itu, jika kita berhasil menemukan tempat peristirahatan orang itu, saya ingin memberikan penghormatan saya.",
  ui_story_5080_50800701_12_dialog_content = "... Apakah semua orang sudah bangun? Ayo bersiap untuk berangkat!",
  ui_story_5080_50800701_13_dialog_content = "Zeta masih terlelap.",
  ui_story_5080_50800701_14_dialog_content = "Biarkan anak itu tidur. Kami akan pergi.",
  ui_story_5080_50800701_15_dialog_content = "Berikut adalah peta yang kita gunakan untuk investigasi kita, Jeriah.",
  ui_story_5080_50800701_16_dialog_content = "Dari yang saya temukan kemarin, sarang Eclipsite kemungkinan besar berada di sekitar sabuk gunung berapi.",
  ui_story_5080_50800701_17_dialog_content = "Saya telah menandai sejumlah lokasi di peta. Bisakah kamu membantu kami untuk mengecualikan beberapa tempat ini?",
  ui_story_5080_50800701_18_dialog_content = "Sayangnya, burung pemangsa kecilku, kamu tidak akan menemukan jawabanmu di lokasi mana pun di antara ini.",
  ui_story_5080_50800701_19_dialog_content = "Apa yang kamu dan kebanyakan orang luar tidak tahu adalah bahwa sebuah gunung berapi raksasa yang tidak aktif tersembunyi di bawah pasir Gurun Rediesel.",
  ui_story_5080_50800701_20_dialog_content = "Sebuah gunung berapi yang tidak aktif?",
  ui_story_5080_50800701_21_dialog_content = "Ya, meskipun saya rasa itu bukanlah kasusnya lagi. Baru kemarin, saya memastikan bahwa gunung berapi itu kembali aktif.",
  ui_story_5080_50800701_22_dialog_content = "Meski tipe Eclipsite itu telah terlihat berkeliaran di seluruh gurun, saya khawatir sarangnya hanya bisa berada di tempat itu.",
  ui_story_5080_50800701_23_dialog_content = "Lagi pula, itu adalah satu-satunya tempat yang biasanya dihindari oleh Rediesel Wrench.",
  ui_story_5080_50800701_24_dialog_content = "Kenapa begitu?",
  ui_story_5080_50800701_25_dialog_content = "Terakhir kali gunung berapi bawah tanah meletus adalah saat Darkover Crisis. Saat itu, tak terhitung jumlah Eclipsite yang muncul dari retakan di tanah dan menyerang Rediesel Wrench.",
  ui_story_5080_50800701_26_dialog_content = "Pemimpin mereka saat itu meninggal dalam pertempuran itu, bersama dengan orang tua Zeta dan banyak orang lainnya.",
  ui_story_5080_50800701_27_dialog_content = "Sejak saat itu, Rediesel Wrench telah menjadikan seluruh gurun sebagai rumah mereka, tetapi mereka selalu menghindari tempat itu.",
  ui_story_5080_50800701_28_dialog_content = "Tapi jika mereka tahu bahwa Eclipsite itu keluar dari gunung berapi, kenapa mereka tidak mencoba menyelidikinya setelah bertahun-tahun ini?",
  ui_story_5080_50800701_29_dialog_content = "Mereka memang melakukannya, tapi mereka tidak pernah menemukan apa-apa.",
  ui_story_5080_50800701_30_dialog_content = "Gunung berapi itu telah benar-benar tidak aktif sejak hari itu, dan hanya Eclipsite biasa yang menghuni tempat itu sekarang.",
  ui_story_5080_50800701_31_dialog_content = "Rediesel Wrench sudah beberapa kali mencoba membersihkannya, tetapi tidak ada tanda-tanda Eclipsite yang pernah ditemukan.",
  ui_story_5080_50800701_32_dialog_content = "Awalnya, semua orang berpikir mereka adalah satu-satunya dari jenis mereka dan telah binasa dalam pertempuran itu bersama dengan pemimpin Rediesel Wrench dan yang lainnya.",
  ui_story_5080_50800701_33_dialog_content = "Setelah begitu banyak kampanye pemusnahan, bahkan Eclipsite biasa di gunung berapi pun telah berkurang jumlahnya.",
  ui_story_5080_50800701_34_dialog_content = "Orang cenderung menghindari kenangan paling menyakitkan mereka. Seiring waktu, mereka berhenti sama sekali pergi ke tempat itu.",
  ui_story_5080_50800701_35_dialog_content = "Tapi itu dulu adalah rumah mereka... Bagaimana mereka bisa meninggalkannya begitu saja?",
  ui_story_5080_50800701_36_dialog_content = "Jangan tampak begitu sedih, PlayerName! Kita telah melakukan pekerjaan yang hebat dalam membangun kembali Eraveil, ingat? Yang perlu kita lakukan sekarang adalah menemukan lebih banyak orangmu!",
  ui_story_5080_50800701_37_dialog_content = "Heheh, mungkin Vice benar. Mungkin beberapa teman sebangsa Caelestite-mu memilih untuk menjelajahi dunia sebebas burung itu sendiri.",
  ui_story_5080_50800701_38_dialog_content = "Dan mungkin suatu hari... Burung-burung itu akan kembali pulang untuk bertengger sekali lagi.",
  ui_story_5080_50800701_39_dialog_content = "...",
  ui_story_5080_50800701_40_dialog_content = "Dalam hal apapun, saya adalah satu-satunya orang yang masih sering mengunjungi rumah lama mereka.",
  ui_story_5080_50800701_41_dialog_content = "Dan meskipun penyelidikan saya belum membuahkan hasil, saya masih tahu jalan ke sana.",
  ui_story_5080_50800701_42_dialog_content = "Maka kami akan menyerahkan navigasi kepada Anda, Jeriah. Ini adalah petanya.",
  ui_story_5080_50800701_43_dialog_content = "Paham, sekarang ayo pergi.",
  ui_story_5080_50800701_44_dialog_content = "Ta-tanahnya berguncang!",
  ui_story_5080_50800701_45_dialog_content = "Lihat! Gunung berapi itu sedang meletus!",
  ui_story_5080_50800701_46_dialog_content = "Jangan terlalu khawatir. Kita harus terus melanjutkan perjalanan kita.",
  ui_story_5080_50800701_47_dialog_content = "Aktivitas vulkanik bukanlah hal baru di Rediesel Desert, tetapi itu bukan tempat yang kita cari.",
  ui_story_5080_50800701_48_dialog_content = "Gunung berapi yang dimaksud telah tidak aktif selama bertahun-tahun. Bahkan di tepi kawahnya, saya tidak menemukan tanda-tanda aktivitas hingga baru-baru ini.",
  ui_story_5080_50800701_49_dialog_content = "Tapi sekarang... Raungan mulai terdengar dari dalam gunung berapi. Raungan dari Eclipsite.",
  ui_story_5080_50800701_50_dialog_content = "Dan jika jenis Eclipsite itu telah kembali ke gunung berapi, maka pasti ada sesuatu yang aneh yang sedang terjadi saat ini.",
  ui_story_5080_50800701_51_dialog_content = "Kita harus bergegas!",
  ui_story_5080_50800701_52_dialog_content = "Ke sini. Kita bisa mencapai kawah gunung berapi dengan turun dari sini.",
  ui_story_5080_50800701_53_dialog_content = "Wow... Tempat ini dipenuhi dengan bekas luka bakar dari lava!",
  ui_story_5080_50800701_54_dialog_content = "Mungkinkah ini ditinggalkan oleh Eclipsites? Atau mungkin ini hanya dari gunung berapi?",
  ui_story_5080_50800701_55_dialog_content = "Aku tidak yakin... Aku sangat sibuk dengan penyelidikanku kemarin sehingga aku tidak berani pergi jauh-jauh.",
  ui_story_5080_50800701_56_dialog_content = "Tapi satu hal yang pasti: gunung berapi ini sekarang aktif.",
  ui_story_5080_50800701_57_dialog_content = "Tunggu, bukankah itu berarti berbahaya untuk turun ke sana?",
  ui_story_5080_50800701_58_dialog_content = "Carleen, bisa tolong tinggal di sini dan menjaga pintu masuk serta mobil kita?",
  ui_story_5080_50800701_59_dialog_content = "Mengerti. Serahkan padaku.",
  ui_story_5080_50800701_60_dialog_content = "Sebuah kekuatan yang tak terbayangkan menyebabkan tanah sedikit berguncang.",
  ui_story_5080_50800701_61_dialog_content = "Gunung berapi ini sama sekali tidak punah.",
  ui_story_5080_50800701_62_dialog_content = "Jejak ini di tanah... Apakah mereka ditinggalkan oleh Eclipsite?",
  ui_story_5080_50800701_63_dialog_content = "Mereka tampaknya semakin masuk ke dalam gunung berapi. Ayo kita ikuti.",
  ui_story_5080_50800701_64_dialog_content = "Tunggu, Rachel!",
  ui_story_5080_50800701_65_dialog_content = "Lihat ini!",
  ui_story_5080_50800701_66_dialog_content = "Sepertinya lorong ini baru saja diekskavasi baru-baru ini.",
  ui_story_5080_50800701_67_dialog_content = "Lihat! Kawah itu tepat di depan sana!",
  ui_story_5080_50800701_68_dialog_content = "Kenapa ada terowongan besar dan baru-baru ini digali begitu dekat dengan kawah...?",
  ui_story_5080_50800701_69_dialog_content = "Lihatlah tembok itu, Caelestite muda.",
  ui_story_5080_50800701_70_dialog_content = "Bekas cakaran? Mereka sangat dalam, seolah-olah ditinggalkan oleh sesuatu yang sangat besar...",
  ui_story_5080_50800701_71_dialog_content = "Tidak ada salahnya. Bekas cakaran ini milik naga dari waktu itu.",
  ui_story_5080_50800701_72_dialog_content = "Sepertinya tempat ini adalah sarangnya, atau mungkin tempat berburunya.",
  ui_story_5080_50800701_73_dialog_content = "Tidak heran Azure belum bisa menemukannya selama ini.",
  ui_story_5080_50800701_74_dialog_content = "Ini karena naga memiliki beberapa sarang, dan salah satunya berada di tempat yang kebanyakan orang hindari di Gurun Rediesel...",
  ui_story_5080_50800701_75_dialog_content = "Tapi Jeriah... Bagaimana kamu tahu Azure sedang mencarinya?",
  ui_story_5080_50800701_76_dialog_content = "Heh, seperti yang sudah aku katakan, aku ditugaskan untuk mengurus seluruh gurun ini.",
  ui_story_5080_50800701_77_dialog_content = "(Tolong... Ini jelas sekali, Jeriah...Kamu sebenarnya peduli pada semua orang di Rediesel Wrench.)",
  ui_story_5080_50800701_78_dialog_content = "Sekarang aku memikirkannya, tampaknya penampakan naga tersebut berhubungan dengan letusan gunung berapi.",
  ui_story_5080_50800701_79_dialog_content = "Mungkin dia harus mengungsikan gunung berapi dan mencari sarang lain setiap kali gunung tersebut meletus?",
  ui_story_5080_50800701_80_dialog_content = "Tapi jika ia takut pada lava, mengapa ia memilih untuk tinggal di gunung berapi?",
  ui_story_5080_50800701_81_dialog_content = "Itu tidak masuk akal.",
  ui_story_5080_50800701_82_dialog_content = "Karena dia bersembunyi dari seseorang tertentu.",
  ui_story_5080_50800701_83_dialog_content = "Dulu, orang itu sedang menyisir gurun mencari mangsa berbahayanya. Untuk menghindarinya, naga tidak punya pilihan selain menyembunyikan diri jauh di bawah tanah...",
  ui_story_5080_50800701_84_dialog_content = "Tanahnya bergetar lagi!",
  ui_story_5080_50800701_85_dialog_content = "Ada yang tidak beres... Sumber gempa tampaknya tepat di bawah kita! Apakah mungkin gunung berapi akan meletus?!",
  ui_story_5080_50800701_86_dialog_content = "Misi ini telah menghadapi rintangan yang tidak mungkin, Kapten! Kita perlu mundur untuk saat ini!",
  ui_story_5080_50800701_87_dialog_content = "... Yang lainnya bisa lanjut tanpa aku. Aku akan melanjutkan misi.",
  ui_story_5080_50800701_88_dialog_content = "Tapi Kapten... Terlalu berbahaya untuk tetap di sini!",
  ui_story_5080_50800701_89_dialog_content = "Misi datang sebelum semua.",
  ui_story_5080_50800701_90_dialog_content = "Sangat alami bagi predator untuk mengejar mangsanya dengan tanpa henti seperti ini.",
  ui_story_5080_50800701_91_dialog_content = "Namun, kesediaanmu untuk mengorbankan hidupmu demi sesuatu yang begitu samar membuatku bingung. Katakan padaku, apakah kamu terlalu keras kepala tentang ini, atau sebenarnya kamu ragu-ragu?",
  ui_story_5080_50800701_92_dialog_content = "Tidak perlu kita pertaruhkan nyawa kita dalam situasi seperti ini, Kapten! Kita bisa kembali lagi nanti!",
  ui_story_5080_50800701_93_dialog_content = "Itu tidak akan cukup. Jika gunung berapi meletus, seluruh tempat ini akan dibanjiri magma, dan ketika mendingin...",
  ui_story_5080_50800701_94_dialog_content = "Pergi saja sana!",
  ui_story_5080_50800701_95_dialog_content = "Kita akan keluar dari sini bersama, Kapten!",
  ui_story_5080_50800701_96_dialog_content = "Anak burung kedua... Kenapa kamu harus mengatakannya seperti itu...?",
  ui_story_5080_50800701_97_dialog_content = "Ha?",
  ui_story_5080_50800701_98_dialog_content = "(Dia sedang berbicara tentang sebelumnya... Mantan rekan satu tim Rachel mengatakan hal yang sama persis...)",
  ui_story_5080_50800701_99_dialog_content = "Aku tidak bisa kabur... Aku tidak akan...",
  ui_story_5080_50800701_100_dialog_content = "Hati-hati! Aku merasakan Eclipsite mendekat ke arah kita!",
  ui_story_5080_50800701_101_dialog_content = "Kita bisa bicara tentang melarikan diri nanti! Bersiaplah untuk bertarung, teman-teman!",
  ui_story_5080_50800702_1_dialog_content = "A-Akhirnya selesai juga.",
  ui_story_5080_50800702_2_dialog_content = "Getaran juga berhenti... Apakah itu berarti gunung berapi sekarang stabil?",
  ui_story_5080_50800702_3_dialog_content = "Mengapa Eclipsites itu begitu kuat? Dalam semua penyelidikan saya, saya belum pernah melihat apa pun seperti mereka di sini.",
  ui_story_5080_50800702_4_dialog_content = "Tubuh mereka... Apakah ini mutasi?",
  ui_story_5080_50800702_5_dialog_content = "Ini terjadi lagi!",
  ui_story_5080_50800702_6_dialog_content = "Ini jauh terlalu berbahaya di sini, Kapten! Kita setidaknya harus mundur ke terowongan dari sebelumnya!",
  ui_story_5080_50800702_7_dialog_content = "Kita terlalu dekat dengan kawah gunung berapi di sini.",
  ui_story_5080_50800702_8_dialog_content = "Baiklah... Kita akan melakukan seperti yang Hatchling Dua sarankan dan mencari rute lain—",
  ui_story_5080_50800702_9_dialog_content = "Tunggu, getaran ini... Ini sama sekali bukan gunung berapi!",
  ui_story_5080_50800702_10_dialog_content = "Awas, semua orang! Terowongan itu akan runtuh—!!!",
  ui_story_5080_50800702_11_dialog_content = "Rediesel Wrench selalu menjadi kelompok orang yang tidak teratur.",
  ui_story_5080_50800702_12_dialog_content = "Hei Jeriah, ayo bangun mobil ini bersama kami! Saya yakin kita bisa menyelesaikannya hari ini jika kita bekerja keras!",
  ui_story_5080_50800702_13_dialog_content = "Ya, dan kemudian kita bisa menggunakannya untuk menangkap banyak kadal pasir!",
  ui_story_5080_50800702_14_dialog_content = "Tidak, terima kasih.",
  ui_story_5080_50800702_15_dialog_content = "Aww, tapi kenapa? Kamu tidak pernah mau bergaul, Jeriah!",
  ui_story_5080_50800702_16_dialog_content = "Tidak usah khawatir, kita akan coba lagi besok!",
  ui_story_5080_50800702_17_dialog_content = "Bahkan ketika saya memberi tahu mereka tidak, itu tidak membuat perbedaan. Namun, saya tidak pernah bisa cocok dengan yang lain.",
  ui_story_5080_50800702_18_dialog_content = "Aha! Sepertinya aku menemukanmu lagi!",
  ui_story_5080_50800702_19_dialog_content = "Aku tidak bermain petak umpet denganmu.",
  ui_story_5080_50800702_20_dialog_content = "Lalu itu berarti kamu menungguku, bukan?",
  ui_story_5080_50800702_21_dialog_content = "Lihat? Kamu hanya tersipu karena aku benar!",
  ui_story_5080_50800702_22_dialog_content = "T-Tidak mungkin.",
  ui_story_5080_50800702_23_dialog_content = "Berikut ini. Tidak mudah, tetapi saya berhasil menemukan beberapa materi pengajaran lagi dari Illumina.",
  ui_story_5080_50800702_24_dialog_content = "Kau pergi ke sana lagi?",
  ui_story_5080_50800702_25_dialog_content = "Yep! Saya memiliki urusan dengan beberapa pedagang pasar gelap di Umbraton.",
  ui_story_5080_50800702_26_dialog_content = "Ingin tahu sesuatu yang lain? Ada reruntuhan kuno yang luar biasa tepat di luar Umbraton, dan dibangun dari bahan-bahan yang bahkan kita tidak tahu.",
  ui_story_5080_50800702_27_dialog_content = "Tempat ini penuh dengan gangster dan orang-orang yang menjajakan barang di pasar gelap. Mereka telah mengubah seluruh tempat menjadi semacam labirin yang gila.",
  ui_story_5080_50800702_28_dialog_content = "Mereka semua mencari apapun yang bisa menghasilkan keuntungan. Mereka bahkan tidak menyadari bahwa reruntuhan itu sendiri adalah hal paling berharga di luar sana!",
  ui_story_5080_50800702_29_dialog_content = "Apa maksudmu? Apa nilai lain yang bisa dimiliki reruntuhan tua selain sebagai tempat wisata?",
  ui_story_5080_50800702_30_dialog_content = "Apakah kamu serius bertanya itu?!",
  ui_story_5080_50800702_31_dialog_content = "Menurutmu reruntuhan itu terbuat dari apa? Mengapa mereka dibangun? Dan siapa sebenarnya yang membangunnya?",
  ui_story_5080_50800702_32_dialog_content = "Jenis teknologi apa yang bisa kita temukan di sana? Dan apa yang bisa teknologi itu lakukan untuk kita?",
  ui_story_5080_50800702_33_dialog_content = "Seperti apakah peradaban kuno itu? Dunia seperti apa yang mereka ciptakan untuk diri mereka sendiri, dan mengapa itu bisa lenyap?",
  ui_story_5080_50800702_34_dialog_content = "Reruntuhan itu dapat menjawab semua pertanyaan tersebut dan lebih banyak lagi.",
  ui_story_5080_50800702_35_dialog_content = "Bisakah lorong-lorong tua benar-benar memberitahu kamu banyak hal?",
  ui_story_5080_50800702_36_dialog_content = "Dengan sedikit waktu dan bujukan, tentu saja!",
  ui_story_5080_50800702_37_dialog_content = "Maksudmu seperti... Waktu itu yang pernah kamu ceritakan sebelumnya?",
  ui_story_5080_50800702_38_dialog_content = "Jam berapa?",
  ui_story_5080_50800702_39_dialog_content = "Ketika kamu sedang menjelajahi Wilayah Rahasia di Northland.",
  ui_story_5080_50800702_40_dialog_content = "Oh, kamu maksud saat itu aku mengajarkanmu cara menerbangkan layang-layang!",
  ui_story_5080_50800702_41_dialog_content = "Benar, reruntuhan itu menggambarkan semacam mesin terbang. Ketika Illumina menemukan itu, mereka mulai mengalokasikan banyak sumber daya untuk menelitinya.",
  ui_story_5080_50800702_42_dialog_content = "Tapi untuk orang biasa seperti aku, yang bisa aku lakukan hanyalah membuatkanmu layang-layang.",
  ui_story_5080_50800702_43_dialog_content = "Jadi, apa yang kamu lihat di reruntuhan lain itu?",
  ui_story_5080_50800702_44_dialog_content = "Banyak sekali orang yang berkeliaran, jadi saya tidak mendapatkan kesempatan untuk melakukan penelitian.",
  ui_story_5080_50800702_45_dialog_content = "Tapi aku akan pastikan untuk melihat baik-baik di sekitar saat aku pergi berikutnya.",
  ui_story_5080_50800702_46_dialog_content = "Saya bahkan mungkin menemukan sesuatu yang bagus untuk dibawa pulang kepadamu, Jeriah!",
  ui_story_5080_50800702_47_dialog_content = "... Bolehkah aku bertanya sesuatu?",
  ui_story_5080_50800702_48_dialog_content = "Hah? Oke, silakan saja.",
  ui_story_5080_50800702_49_dialog_content = "Kamu sudah melihat hampir semua Astra, jadi mengapa kamu masih begitu bersemangat tentang segalanya?",
  ui_story_5080_50800702_50_dialog_content = "Tak ada hal di dunia ini yang seharusnya masih bisa membuatmu terkejut. Jika ada yang harus dirasakan, seharusnya kau sudah benar-benar bosan sekarang...",
  ui_story_5080_50800702_51_dialog_content = "Hei Jeriah, apakah kamu sudah membaca semua buku yang telah kubawa pulang untukmu?",
  ui_story_5080_50800702_52_dialog_content = "Ya. Semua lima ribu, enam ratus delapan puluh tiga dari mereka.",
  ui_story_5080_50800702_53_dialog_content = "Tapi bahkan banyak buku sekalipun tidak bisa mulai menceritakan seluruh kisah Astra.",
  ui_story_5080_50800702_54_dialog_content = "Apakah kamu juga tahu bahwa ada benua lain di dunia ini selain benua kita? Saya bertanya-tanya, seperti apa orang-orang dan tempat-tempat di sana?",
  ui_story_5080_50800702_55_dialog_content = "Saya tidak tahu, tetapi saya selalu penasaran untuk mengetahui.",
  ui_story_5080_50800702_56_dialog_content = "Saya telah pergi ke sebagian besar tempat di Astra, tetapi saya masih tidak bisa mengingat semua jalan yang telah saya tempuh.",
  ui_story_5080_50800702_57_dialog_content = "Anda mungkin tidak menyadarinya sekarang, Jeriah, tapi Anda juga memiliki keinginan yang kuat untuk menjelajahi dunia.",
  ui_story_5080_50800702_58_dialog_content = "Kamu tidak seperti saya, melaju melewati semua pemandangan dunia tanpa berhenti untuk menghargainya. Itulah mengapa saya pikir kamu akan belajar lebih banyak tentang dunia ini daripada yang pernah akan saya pelajari.",
  ui_story_5080_50800702_59_dialog_content = "Berhenti mengusap kepalaku...",
  ui_story_5080_50800702_60_dialog_content = "Baiklah! Kamu ingin jawaban, jadi ini dia! Meskipun aku telah ke banyak tempat berbeda, aku jarang membuat kenangan saat berada di sana.",
  ui_story_5080_50800702_61_dialog_content = "Dan ketika malam tiba di gurun, saya menyadari bahwa saya hampir tidak ingat apa-apa tentang hal-hal indah yang pernah saya lihat dalam hidup saya.",
  ui_story_5080_50800702_62_dialog_content = "Itu karena... Sebagai prajurit Illumina, kau selalu dikirim untuk menjalankan misi.",
  ui_story_5080_50800702_63_dialog_content = "Meski bisa jadi aku juga salah! Hahaha!",
  ui_story_5080_50800702_64_dialog_content = "Kamu anak yang cerdas, Jeriah. Aku tahu kamu memiliki banyak pertanyaan, dan aku tahu rasanya buruk saat kamu tidak menemukan jawaban yang kamu cari.",
  ui_story_5080_50800702_65_dialog_content = "Tapi apa boleh buat. Kamu masih anak-anak, toh!",
  ui_story_5080_50800702_66_dialog_content = "Jadi, dewasalah dan pelajarilah semua yang bisa kamu pelajari, Jeriah! Saya yakin kamu akan mampu menjawab setiap pertanyaan yang datang di masa depan!",
  ui_story_5080_50800702_67_dialog_content = "Dan jangan sia-siakan hidupmu berlarian seperti yang saya lakukan. Selalu ingat untuk berhenti dan mencium aroma mawar.",
  ui_story_5080_50800702_68_dialog_content = "Saya yakin kamu akan menemukan makna hidupmu, dan membuat banyak kenangan indah di sepanjang perjalanan.",
  ui_story_5080_50800702_69_dialog_content = "Sebarkan sayapmu dan hiduplah dengan bebas, Jeriah. Hanya dengan begitu Anda akan menemukan... Jawaban yang sangat Anda inginkan untuk diketahui.",
  ui_story_5080_50800702_70_dialog_content = "Aku tidak paham.",
  ui_story_5080_50800702_71_dialog_content = "<color=#FFB400>Dia</color> dan saya seharusnya sama. Kami berdua lahir di tempat-tempat di mana kami tidak seharusnya berada.",
  ui_story_5080_50800702_72_dialog_content = "Aku ingin meninggalkan gurun dan meninggalkan jejakku di mana pun aku pergi. Tapi setelah membebaskan diri dari Illumina, dia memilih untuk datang ke tempat ini dari semua tempat.",
  ui_story_5080_50800702_73_dialog_content = "Kenapa... Kenapa kau memilih untuk tetap tinggal?",
  ui_story_5080_50800702_74_dialog_content = "Apa kamu masih ingat <color=#FFB400>kisah</color> yang pernah aku ceritakan, Jeriah?",
  ui_story_5080_50800702_75_dialog_content = "Uh huh.",
  ui_story_5080_50800702_76_dialog_content = "Dan di akhir cerita itu, kamu menemukan <color=#FFB400>wrench ini</color> dan sekelompok orang yang bergantung padamu. Kamu tidak lagi sendirian.",
  ui_story_5080_50800702_77_dialog_content = "Jadi demi kebaikan semua orang, kamu telah menyatukan semua pengembara gurun dan membentuk Rediesel Wrench.",
  ui_story_5080_50800702_78_dialog_content = "Kamu tidak pernah bertanggung jawab atas mereka... Jadi, kenapa kamu memilih untuk tetap bersama mereka? Bukankah kamu ingin tetap...",
  ui_story_5080_50800702_79_dialog_content = "Apa salahnya ingin pulang? Saya lahir dan dibesarkan di gurun ini setelah semua. Selain itu, saya juga ingin mereka memiliki kebebasan mereka sendiri.",
  ui_story_5080_50800702_80_dialog_content = "Hidup tanpa kesadaran diri membuat kita tidak berbeda dengan Eclipsite, menurutmu? Aku ingin membebaskan jiwa mereka dan memberi mereka kekuatan untuk membuat keputusan mereka sendiri.",
  ui_story_5080_50800702_81_dialog_content = "Saya sudah membuang sebagian besar hidup saya sendiri.",
  ui_story_5080_50800702_82_dialog_content = "Jadi, saya berharap mereka memahami perjalanan mereka dan menjalani kehidupan yang bebas.",
  ui_story_5080_50800702_83_dialog_content = "Menjadi jiwa yang bebas yang hidup di saat ini, dengan ceria membuat kenakalan—apakah itu yang disebut kebebasan?",
  ui_story_5080_50800702_84_dialog_content = "Aku tidak paham...",
  ui_story_5080_50800702_85_dialog_content = "Karena cerita-ceritamu, saya mengetahui bahwa masih ada begitu banyak hal yang menunggu untuk saya temukan.",
  ui_story_5080_50800702_86_dialog_content = "Pada saat itu, saya benar-benar tenggelam dalam menjelajahi dunia ini.",
  ui_story_5080_50800702_87_dialog_content = "Oh? Itu cukup mengesankan, Jeriah.",
  ui_story_5080_50800702_88_dialog_content = "Tapi dunia ini tidak sehebat yang kamu deskripsikan. Kamu berbohong padaku.",
  ui_story_5080_50800702_89_dialog_content = "Para bangsawan Lumopolis sombong, Federasi Illumina sangat membosankan, dan orang-orang Northland tetap terperangkap dalam dongeng mereka sendiri.",
  ui_story_5080_50800702_90_dialog_content = "Whispering Corridor di Umbraton telah menjadi gudang harta karun Istvan. Reruntuhan legendaris yang disebut-sebut itu hanyalah dinding dalam yang acuh tak acuh dari peti hartanya.",
  ui_story_5080_50800702_91_dialog_content = "Semuanya tampak begitu kosong...",
  ui_story_5080_50800702_92_dialog_content = "Bahkan kaum Caelestite, yang menciptakan begitu banyak keajaiban ilmiah, pada akhirnya menjadi kenangan yang jarang orang bicarakan.",
  ui_story_5080_50800702_93_dialog_content = "Eclipsites menyerang, kita membalas... Semua kehidupan di dunia ini terjebak dalam siklus kejam yang putus asa untuk bertahan hidup.",
  ui_story_5080_50800702_94_dialog_content = "Semuanya akan kembali ke ketiadaan.",
  ui_story_5080_50800702_95_dialog_content = "Si kecil Jeriah akhirnya sudah tumbuh dewasa, tapi kamu terlalu banyak khawatir.",
  ui_story_5080_50800702_96_dialog_content = "Aku tidak mengerti... Haruskah aku berhenti bertanya?",
  ui_story_5080_50800702_97_dialog_content = "Jika kecerdasan hanya mengundang kehampaan kesendirian, haruskah saya memilih untuk bergabung dengan orang-orang bodoh yang bebas itu?",
  ui_story_5080_50800702_98_dialog_content = "Tapi Jeriah, Caelestite terakhir ada di sini.",
  ui_story_5080_50800702_99_dialog_content = "Kamu harus tahu bahwa sejak saat dia kembali, Eraveil tidak akan pernah menjadi kenangan yang terlupakan lagi. Cerita mereka akan dimulai lagi dengan seorang pewaris yang akan membawa kenangan-kenangan itu.",
  ui_story_5080_50800702_100_dialog_content = "Apakah pemandangan dunia ini selalu tetap sama?",
  ui_story_5080_50800702_101_dialog_content = "Ketidakpastian takdir tidak hanya membawa kebosanan atau rasa sakit.",
  ui_story_5080_50800702_102_dialog_content = "Koneksi-koneksi itu, seperti tali yang kuat, menahanmu, layang-layang yang tak terkendali...",
  ui_story_5080_50800702_103_dialog_content = "Tunggu! Kemana kamu pergi? Jangan pergi!",
  ui_story_5080_50800702_104_dialog_content = "Kamu pasti merasakannya—mereka sedang memanggilmu.",
  ui_story_5080_50800702_105_dialog_content = "Di mata kamu, saya pasti bukan guru yang sangat baik. Tapi di mata saya, Jeriah... Saya sangat senang telah bertemu dengan kamu.",
  ui_story_5080_50800702_106_dialog_content = "Tunggu! Kembali! Jangan pergi! Jangan pergi—<color=#FFB400>Attar</color>—!",
  ui_story_5080_50800702_107_dialog_content = "Jeriah!",
  ui_story_5080_50800702_108_dialog_content = "...?",
  ui_story_5080_50800702_109_dialog_content = "Bagus, kamu sudah bangun.",
  ui_story_5080_50800702_110_dialog_content = "Anak punk kecil ini panik... Dia telah duduk di sini mencoba mempraktekkan \"gerakan spesial\"nya pada kamu selama ini.",
  ui_story_5080_50800702_111_dialog_content = "Sinsa...?",
  ui_story_5080_50800702_112_dialog_content = "Dan kami juga.",
  ui_story_5080_50800702_113_dialog_content = "... Kenapa rasanya seperti setengah dari Rediesel Wrench ada di sini?",
  ui_story_5080_50800702_114_dialog_content = "Penyihir! Yay, akhirnya kamu bangun juga! Di mana rasa sakitnya?",
  ui_story_5080_50800702_115_dialog_content = "Mengapa kamu meninggalkan pahlawan legendaris favoritmu?! Aku terbangun segera setelah aku mendengar kamu datang!",
  ui_story_5080_50800702_116_dialog_content = "Saya sedang melawan Eclipsites ketika dia mengejarku dalam keadaan histeris, tepat waktu untuk memecahkan pengepungan.",
  ui_story_5080_50800702_117_dialog_content = "Tapi dia terlalu bersemangat, dia tidak mendengarkan saya sama sekali. Pilihan satu-satunya adalah membawanya ke sini untuk menemukanmu...",
  ui_story_5080_50800702_118_dialog_content = "Dan kemudian gua itu tiba-tiba runtuh! Tidak terasa seperti di dalam cerita petualangan?",
  ui_story_5080_50800702_119_dialog_content = "Mengenai runtuhnya gua, saat itu saya merasa ada yang berbeda dari getaran sebuah gunung berapi...",
  ui_story_5080_50800702_120_dialog_content = "Ini semua salah Sinsa, mengayunkan kunci pas itu seperti orang kasar... Aku sudah bilang gua ini tidak stabil.",
  ui_story_5080_50800702_121_dialog_content = "Aku tidak meminta kamu untuk mengikutiku.",
  ui_story_5080_50800702_122_dialog_content = "Itu hal lainnya—kenapa kau memanggil begitu banyak orang tapi bukan aku? Kau pasti benar-benar dendam padaku, huh...",
  ui_story_5080_50800702_123_dialog_content = "Hei, jangan salahkan Sinsa. Kami hanya mencari bantuan yang tepat, itu saja.",
  ui_story_5080_50800702_124_dialog_content = "Hah? Maksudmu Jona lebih berguna daripada saya?",
  ui_story_5080_50800702_125_dialog_content = "Di alam liar juga berbahaya. Jona perlu tinggal di rumah dan menjaga benteng.",
  ui_story_5080_50800702_126_dialog_content = "Jangan khawatir, begitu Azure kembali, Jona akan segera menyusul.",
  ui_story_5080_50800702_127_dialog_content = "Benar sekali, Dawn. Jona bisa melacak Eclipsite. Dan kamu... jangan meremehkan dirimu sendiri, kawan. Kamu tahu aku percaya padamu.",
  ui_story_5080_50800702_128_dialog_content = "Tidak, ini semua salah! Peran setiap orang cukup jelas—siapa di antara kalian yang tidak bisa menutup mulut?! Kenapa kalian berdua dan Eve muncul?!",
  ui_story_5080_50800702_129_dialog_content = "Maaf... Karena aku menyadari kamu dan Dawn hilang, jadi aku bertanya-tanya...",
  ui_story_5080_50800702_130_dialog_content = "Aaaaah!!! Orang-orang itu bahkan tidak bisa menyimpan rahasia dari Eve yang kecil ini?!",
  ui_story_5080_50800702_131_dialog_content = "Kamu berencana meninggalkan aku dan Eve, ya? Tidak bisa diterima! Kamu dengar?! Aku sudah berusaha sekuat tenaga hanya untuk mengejar kalian!",
  ui_story_5080_50800702_132_dialog_content = "Brock, kamu harus membawa Eve kembali, di sini terlalu berbahaya.",
  ui_story_5080_50800702_133_dialog_content = "Jalan sudah runtuh—akan terlalu berbahaya mencoba mencari jalan kembali sekarang. Saya sarankan kita biarkan mereka tinggal.",
  ui_story_5080_50800702_134_dialog_content = "Cukup bertengkar! Astaga... Bagaimana bisa jadi seperti ini...?",
  ui_story_5080_50800702_135_dialog_content = "Yah, karena kita sebenarnya tidak punya pilihan lagi... Eve, Brock—kalian berdua bisa tinggal. Tapi Eve, pastikan kamu tetap dekat!",
  ui_story_5080_50800702_136_dialog_content = "Baiklah!",
  ui_story_5080_50800702_137_dialog_content = "Mari kita bersatu dan berani menghadapi hal-hal yang tidak diketahui!",
  ui_story_5080_50800702_138_dialog_content = "Aku telah menyiapkan perayaan kemenangan kecil milikku sendiri. Tidak ada yang boleh melewatkannya—mengerti, kan, semua orang?",
  ui_story_5080_50800702_139_dialog_content = "Ingat ini—jangan coba jadi pahlawan! Jika ada masalah, bersembunyilah di belakangku—itu juga berlaku untuk kalian, PlayerName.",
  ui_story_5080_50800702_140_dialog_content = "Rediesel Wrench... Jadi akhirnya sampai juga di sini. Ya sudahlah...",
  ui_story_5080_50800702_141_dialog_content = "Kamu, Gadis Lolipop—kamu bisa mengikutiku dari belakang, aku...",
  ui_story_5080_50800702_142_dialog_content = "Aku akan melindungimu.",
  ui_story_5080_50800802_1_dialog_content = "Karena kita sudah sampai sejauh ini bersama, kurasa ada beberapa hal yang tidak perlu lagi aku sembunyikan darimu.",
  ui_story_5080_50800802_2_dialog_content = "Roy, saya hanya akan memberi tahu mereka. Medan di sini semakin rendah dan rendah... Kita mungkin saja menemukan jackpot setiap saat sekarang.",
  ui_story_5080_50800802_3_dialog_content = "Tidak ada keberatan di sini. Jika ada yang Anda lewatkan, saya akan menjelaskannya.",
  ui_story_5080_50800802_4_dialog_content = "Kenapa tiba-tiba ini semua terasa sangat formal...?",
  ui_story_5080_50800802_5_dialog_content = "Izinkan saya membawa Anda kembali lima belas tahun yang lalu. Krisis Darkover sudah meletus di seluruh Astra—kami telah berusaha keras menahan wabah ini untuk sementara waktu.",
  ui_story_5080_50800802_6_dialog_content = "Tak ada yang menduga ada gunung berapi tersembunyi di bawah kamp. Itu meletus tanpa peringatan, dan banjir Eclipsite mengalir keluar dari retakan besar yang diciptakannya.",
  ui_story_5080_50800802_7_dialog_content = "Kami terkejut dan harus bertempur sambil mundur dari kamp.",
  ui_story_5080_50800802_8_dialog_content = "Saya baru berusia enam belas tahun, diperintahkan untuk dievakuasi oleh para bos besar. Saya tidak cukup kuat... Saya hanya bisa melindungi Eve dan yang lainnya saat kami melarikan diri.",
  ui_story_5080_50800802_9_dialog_content = "Saya juga mengikuti para pemimpin pada saat itu. Kami sama-sama menjaga belakang... tapi pada akhirnya, mereka menyuruh saya untuk berlari di depan.",
  ui_story_5080_50800802_10_dialog_content = "Pemimpin kami... Mereka mengorbankan diri mereka dalam pertempuran terakhir itu.",
  ui_story_5080_50800802_11_dialog_content = "Naga jahat itu juga ada di sana. Awalnya, kepala suku tampaknya bisa menanganinya, tapi—",
  ui_story_5080_50800802_12_dialog_content = "Letusan semakin intens, dan seorang Eclipsite yang dilumuri magma merangkak keluar dari bawah bumi.",
  ui_story_5080_50800802_13_dialog_content = "Eclipsite yang dilumuri magma itu, tidak ada keraguan lagi—itu adalah target kita.",
  ui_story_5080_50800802_14_dialog_content = "Bos tampaknya memiliki semacam koneksi dengan itu. Dia terkejut dan... takut ketika melihatnya.",
  ui_story_5080_50800802_15_dialog_content = "Dia bilang dia tahu betapa kuatnya benda itu. Itulah sebabnya dia menyuruh kita semua untuk keluar dari sana.",
  ui_story_5080_50800802_16_dialog_content = "Cara dia memberikan perintah terakhir itu... yang bisa aku lakukan hanyalah lari. Pada akhirnya, dia maju dengan beberapa anggota senior lainnya dari geng itu.",
  ui_story_5080_50800802_17_dialog_content = "… Hmm…",
  ui_story_5080_50800802_18_dialog_content = "(Aku merasakan gelombang emosi yang kuat... Apakah itu... Rachel?)",
  ui_story_5080_50800802_19_option_content = "(Apakah dia kehilangan kendalinya?)",
  ui_story_5080_50800802_20_dialog_content = "(Benar. Pemimpin itu adalah pengkhianat yang sama yang merusak reputasi bibinya.)",
  ui_story_5080_50800802_21_option_content = "(Apakah dia menolak untuk mempercayai semua ini?)",
  ui_story_5080_50800802_22_dialog_content = "(Pasti sulit baginya untuk percaya bahwa pemimpin saat itu adalah tipe yang rela berkorban dengan begitu mulia...)",
  ui_story_5080_50800802_23_dialog_content = "(Di hatinya, pemimpin itu selalu menjadi seorang desertir, takut akan kematian, tetapi bagi Rediesel Wrench, dia jelas seorang pahlawan!)",
  ui_story_5080_50800802_24_dialog_content = "Tidak banyak yang bisa dikatakan tentang apa yang terjadi setelah itu.",
  ui_story_5080_50800802_25_dialog_content = "Terima kasih kepada Sinsa, meskipun dia masih muda, perintahnya jelas sekali. Yang lebih penting, dia memiliki keberanian seperti bos sejati.",
  ui_story_5080_50800802_26_dialog_content = "Di bawah kepemimpinannya, kami mulai melancarkan operasi gerilya, dan akhirnya menemukan Lepidoz.",
  ui_story_5080_50800802_27_dialog_content = "Tidak hanya kami berhasil bangkit, kami bahkan menyelamatkan sekelompok nomaden gurun yang tersesat dalam prosesnya, dan jumlah kami mulai bertambah.",
  ui_story_5080_50800802_28_dialog_content = "Pemimpin lama kami telah meninggal, tetapi krisis belum berakhir. Setiap orang lainnya sibuk menangisi kehilangan kami, jadi apa lagi yang bisa saya lakukan selain memikirkan cara untuk menghibur mereka?",
  ui_story_5080_50800802_29_dialog_content = "Eve dan aku adalah orang luar. Bos telah berusaha sebaik mungkin untuk merawat kami, dan setiap orang telah banyak membantu kami.",
  ui_story_5080_50800802_30_dialog_content = "Tidak ada yang ingin menjadi orang jahat! Tidak ada yang ingin harus mengucapkan kebenaran keras yang perlu didengar orang, jadi saya melakukannya semua! Bos sudah pergi—kami tidak bisa kehilangan orang lain.",
  ui_story_5080_50800802_31_dialog_content = "Aku tidak peduli siapa yang menyebutku kasar atau tidak masuk akal, selama semua orang selamat, aku merasa aku telah melakukan yang terbaik untuk kepala suku.",
  ui_story_5080_50800802_32_dialog_content = "Waktu itu, aku tidak terlalu memikirkan hal lain.",
  ui_story_5080_50800802_33_dialog_content = "Jangan merendah—itu tidak cocok untukmu, orang besar.",
  ui_story_5080_50800802_34_dialog_content = "Cukup dengan hal-hal yang menyedihkan! Ini semua bukan intinya!",
  ui_story_5080_50800802_35_dialog_content = "Setelah gunung berapi mereda, kami secara bertahap membasmi semua Eclipsites.",
  ui_story_5080_50800802_36_dialog_content = "Dan setelah magma mendingin, yang kami temukan kembali di sisa-sisa kamp adalah kunci pas itu.",
  ui_story_5080_50800802_37_dialog_content = "Naga jahat itu, bos, Eclipsite itu... kami tidak bisa menemukan jejak sedikit pun dari mereka.",
  ui_story_5080_50800802_38_dialog_content = "Meskipun tidak ada yang mengatakannya secara langsung, kami semua mengira bahwa bos pasti telah turun bersama monster-monster itu, dan mereka semua mati dalam lava.",
  ui_story_5080_50800802_39_dialog_content = "Sampai naga jahat itu muncul kembali dengan kekejamannya...",
  ui_story_5080_50800802_40_dialog_content = "Sekarang Eclipsite itu kembali juga... Mungkin bos lama itu hanya dimakan oleh makhluk-makhluk itu waktu itu.",
  ui_story_5080_50800802_41_dialog_content = "Tidak mungkin! Dia terlalu baik untuk itu!",
  ui_story_5080_50800802_42_dialog_content = "Yah, setidaknya kita akhirnya bisa membalas dendam. Tempat ini yang tidak pernah kita temukan sebelumnya—ternyata ada rute tersembunyi di sini sepanjang waktu...",
  ui_story_5080_50800802_43_dialog_content = "Di masa lalu, gunung berapi itu akan bergemuruh dan mengaum dari waktu ke waktu.",
  ui_story_5080_50800802_44_dialog_content = "Meskipun semua orang tahu bahwa Eclipsite-lah yang membuat semua kebisingan itu, tidak peduli berapa banyak dari mereka yang kita bunuh, kita tidak bisa membasmi mereka semua. Selalu terasa seperti pasti ada beberapa lorong yang belum ditemukan yang mereka gunakan untuk masuk.",
  ui_story_5080_50800802_45_dialog_content = "Hah, yah, kami akhirnya menemukannya. Tapi kami masih harus kembali ke tempat sialan ini untuk melakukannya.",
  ui_story_5080_50800802_46_dialog_content = "Aku... cukup suka mengikutinya ke mana-mana ketika aku masih kecil.",
  ui_story_5080_50800802_47_dialog_content = "Aku melihat kekuatannya. Tidak kalah dari cerita berlebihan Sinsa. Dia seharusnya tidak kalah dari naga itu.",
  ui_story_5080_50800802_48_dialog_content = "Dan... Aku bisa merasakan bahwa dia sedang bertahan terhadap sesuatu yang belum bisa aku mengerti.",
  ui_story_5080_50800802_49_dialog_content = "Dia dengan putus asa menyembunyikan suatu rahasia, menekan sebagian dari dirinya sendiri.",
  ui_story_5080_50800802_50_dialog_content = "Sekarang kamu sebutkan, ya... bos dan aku berasal dari Illumina. Aku sudah mendengar namanya lebih banyak kali daripada yang bisa aku ingat.",
  ui_story_5080_50800802_51_dialog_content = "Tapi ketika aku benar-benar bertemu dengannya, dia berbeda dari yang kubayangkan.",
  ui_story_5080_50800802_52_dialog_content = "Tapi aku selalu merasa seolah-olah dia menyembunyikan jati dirinya. Tidak peduli musuh apa yang kita hadapi, aku merasa dia selalu menahan diri.",
  ui_story_5080_50800802_53_dialog_content = "Dia tampaknya hanya membiarkan apa pun yang ada di dalam dirinya keluar pada akhirnya. Itulah saat pertama kali saya melihat sisi liar pemimpin kami dilepaskan.",
  ui_story_5080_50800802_54_dialog_content = "Dia lebih liar daripada Sinsa di hari yang buruk.",
  ui_story_5080_50800802_55_dialog_content = "Itu perbandingan yang cukup aneh untuk dibuat.",
  ui_story_5080_50800802_56_dialog_content = "Jika bahkan seorang wanita seperti dia bisa kalah oleh <color=#FFB400>Eclipsite itu</color>, apa peluang yang kita miliki?",
  ui_story_5080_50800802_57_dialog_content = "Sepertinya Gunung Berapi yang Mengaum akan segera meletus, dan Darkover mungkin akan menyerang lagi. Bisakah Rediesel Wrench benar-benar menghadapi ancaman seperti itu?",
  ui_story_5080_50800802_58_dialog_content = "Apakah Anda benar-benar harus bertanya?",
  ui_story_5080_50800802_59_dialog_content = "Cukup majulah!",
  ui_story_5080_50800802_60_dialog_content = "Tidak peduli jenis Eclipsite apa yang kita hadapi. Aku akan membanting mereka tinggi-tinggi dengan kunci pas andalanku ini!",
  ui_story_5080_50800802_61_dialog_content = "Jika Eclipsite itu punya nyali untuk menghadapiku lagi, wah, aku tak akan membiarkannya kabur kali ini! Tidak mungkin!",
  ui_story_5080_50800802_62_dialog_content = "Caelestite Satu, Anak Hiu Dua—dengarkan baik-baik.",
  ui_story_5080_50800802_63_dialog_content = "Ada apa? Kenapa tiba-tiba berkelakuan seperti mata-mata?",
  ui_story_5080_50800802_64_dialog_content = "Misi kita adalah... jika memungkinkan, menangkap Eclipsite itu dalam keadaan hidup.",
  ui_story_5080_50800802_65_dialog_content = "Saat waktunya tiba, cegah Sinsa untuk membunuhnya.",
  ui_story_5080_50800901_1_dialog_content = "Jalan baru lagi, ya? Apa sebenarnya yang terjadi di sini?",
  ui_story_5080_50800901_2_dialog_content = "Ini membuka. Sepertinya kita telah mencapai jalan yang sebenarnya.",
  ui_story_5080_50800901_3_dialog_content = "Dunia di bawah gurun adalah tempat yang rumit untuk dinavigasi, tetapi melihat struktur ini... apakah ini bisa jadi bagian dari dinding Koridor Leyline?",
  ui_story_5080_50800901_4_dialog_content = "Ketika gunung berapi meletus, lava membakar segalanya, dan para Eclipsite menggali melalui lubang-lubang ini untuk membuat jalan.",
  ui_story_5080_50800901_5_dialog_content = "Dari penampilan dinding ini, mereka pasti digali, tetapi dengan alat, bukan cakar.",
  ui_story_5080_50800901_6_dialog_content = "Jadi, ini bukan hasil kerja Eclipsite?",
  ui_story_5080_50800901_7_dialog_content = "Orang-orang telah tinggal di gurun selama waktu yang sangat lama. Mungkin ini adalah hasil kerja dari peradaban kuno yang mengembangkan Koridor Leyline.",
  ui_story_5080_50800901_8_dialog_content = "Lihat di sini... Getaran yang kuat telah meretakkan lapisan tanah.",
  ui_story_5080_50800901_9_dialog_content = "Ada batu yang dipotong di sini. Ini adalah lantai, yang berarti tempat ini dibangun oleh seseorang.",
  ui_story_5080_50800901_10_dialog_content = "Apa? Tepat di sebelah lubang ventilasi gunung berapi bawah tanah?!",
  ui_story_5080_50800901_11_dialog_content = "Itu menjelaskan tanda-tanda alat di dinding — mereka tidak hanya mengembangkan garis ley tanpa alasan, mereka sedang membangun sesuatu.",
  ui_story_5080_50800901_12_dialog_content = "Hei, apa yang sedang dilakukan prajurit Illumina ini menggali tanah di saat seperti ini?",
  ui_story_5080_50800901_13_dialog_content = "Tunggu sebentar—dia sedang menggali sisa-sisa terdalam di celah-celah material bangunan ini, mencari cerita apa pun yang mungkin bisa mereka ceritakan.",
  ui_story_5080_50800901_14_dialog_content = "Batu ini memiliki tiga titik cekungan yang jelas, dan ada abu hangus di celah-celahnya.",
  ui_story_5080_50800901_15_dialog_content = "Tidak ada keraguan. Seseorang menyiapkan panci dan memasak sesuatu di sini sudah lama.",
  ui_story_5080_50800901_16_dialog_content = "Dari sini ke tempat kita masuk, kira-kira seukuran sebuah ruangan—ini adalah tempat perlindungan bawah tanah.",
  ui_story_5080_50800901_17_dialog_content = "Dahulu kala, mungkin tidak ada Eclipsite di sini, tetapi kemungkinan besar tempat ini adalah tempat perlindungan bagi sekelompok orang.",
  ui_story_5080_50800901_18_dialog_content = "Mereka bersembunyi di sini sampai letusan gunung berapi mengubur segalanya.",
  ui_story_5080_50800901_19_dialog_content = "Sangat mengesankan. Hanya dengan beberapa kata, Anda telah menggali cerita-cerita kuno yang terpendam di sini.",
  ui_story_5080_50800901_20_dialog_content = "Aku belum pernah melihat hal seperti ini sebelumnya... Pantas saja kau menjadi kapten pengintai di usia yang sangat muda.",
  ui_story_5080_50800901_21_dialog_content = "Sinsa, pernahkah kamu mendengar tentang orang-orang yang tinggal di bawah tanah di sini?",
  ui_story_5080_50800901_22_dialog_content = "Eve dan aku pada dasarnya juga orang luar. Kami tidak tahu semua cerita lama itu.",
  ui_story_5080_50800901_23_dialog_content = "Roy dan saya berasal dari Illumina, dan meskipun dia pasti sudah berkeliling, dia mungkin juga tidak tahu tentang hal-hal seperti ini.",
  ui_story_5080_50800901_24_dialog_content = "Kenapa kau menatapku? Aku terlalu muda untuk tahu tentang hal ini. Lagipula, jika Sinsa tidak tahu tentang itu, kenapa aku harus tahu?",
  ui_story_5080_50800901_25_dialog_content = "Jika dulu ada orang di sini, kenapa kamu tidak pernah mendengar apa-apa tentang itu?",
  ui_story_5080_50800901_26_dialog_content = "Bahkan saya sendiri belum pernah mendengar tentang ini! Mungkinkah ini adalah peninggalan kuno yang sangat tua? Mungkin ada kekuatan epik yang terpendam di sini, seperti raksasa Lumina yang sangat kuat!?",
  ui_story_5080_50800901_27_dialog_content = "Salahku... Seharusnya aku memastikan anak-anak belajar sejarah mereka, tapi tampaknya tidak ada yang peduli tentang masa lalu.",
  ui_story_5080_50800901_28_dialog_content = "Kamu menyuruh saya mengatur dan mengirimkan buku setiap bulan, dan mereka hanya menumpuk debu.",
  ui_story_5080_50800901_29_dialog_content = "Maaf, Jeriah.",
  ui_story_5080_50800901_30_dialog_content = "Kita punya masalah yang lebih besar untuk dihadapi sekarang!",
  ui_story_5080_50800901_31_dialog_content = "Benar! Seorang kesatria legendaris seperti aku tidak punya waktu untuk kisah-kisah lama!",
  ui_story_5080_50800901_32_dialog_content = "Ah... Aku memang sudah menduga, tapi mendengar kalian semua benar-benar mengatakannya... Memang tidak ada harapan untuk dunia ini.",
  ui_story_5080_50800901_33_dialog_content = "Setiap orang sebenarnya hanya peduli tentang masa kini daripada mengeksplorasi apa arti sebenarnya dari tanah di bawah kaki mereka dan warisan dari pendahulu mereka.",
  ui_story_5080_50800901_34_dialog_content = "Nona Jeriah, kamu pasti tahu sesuatu, kan? Tolong beri tahu kami!",
  ui_story_5080_50800901_35_dialog_content = "Penelitianku tentang gurun tidaklah begitu luas, tetapi ketika berbicara tentang tempat perlindungan, sebuah legenda tertentu langsung terlintas di pikiranku.",
  ui_story_5080_50800901_36_dialog_content = "Ini juga merupakan cerita asal-usul dari Rediesel Wrench.",
  ui_story_5080_50800901_37_dialog_content = "Bukankah karena bos lama kita yang menaklukkan bandit-bandit itulah Rediesel Wrench terbentuk?",
  ui_story_5080_50800901_38_dialog_content = "Dahulu kala, gurun adalah rumah bagi nomaden dan penjahat, hidup tanpa adanya tatanan yang sebenarnya.",
  ui_story_5080_50800901_39_dialog_content = "Mungkin mereka takut akan dunia luar, atau lelah dengan itu, lebih memilih untuk hidup di lingkungan gurun yang keras.",
  ui_story_5080_50800901_40_dialog_content = "Mereka percaya tempat ini adalah kebebasan mereka.",
  ui_story_5080_50800901_41_dialog_content = "Kebebasan...",
  ui_story_5080_50800901_42_dialog_content = "Suatu hari, seorang wanita bangsawan muda dari Lumopolis, yang dianiaya oleh keluarganya, dibawa ke gurun oleh pelayannya.",
  ui_story_5080_50800901_43_dialog_content = "Pembantu itu ingin membawanya ke kampung halamannya, jauh dari segala pertikaian.",
  ui_story_5080_50800901_44_dialog_content = "Pertikaian di Lumopolis... Saya melihatnya.",
  ui_story_5080_50800901_45_dialog_content = "Seorang penjaga dari kota itu dikirim untuk mengejar mereka. Dia percaya pada kehormatan seorang ksatria di atas segalanya.",
  ui_story_5080_50800901_46_dialog_content = "Menariknya, seorang prajurit Illumina juga telah berani masuk ke gurun pada saat itu, mencari desa-desa untuk para desertir Illumina.",
  ui_story_5080_50800901_47_dialog_content = "Dia mengejar seorang insinyur Illumina yang kecewa dan telah kehilangan keinginannya untuk melayani.",
  ui_story_5080_50800901_48_dialog_content = "Seorang prajurit Illumina yang kecewa...",
  ui_story_5080_50800901_49_dialog_content = "Selama pengejaran, agen Illumina, karena kesalahpahaman, keliru berpikir bahwa Lumo Guard juga mengejar orang yang sama dengannya.",
  ui_story_5080_50800901_50_dialog_content = "Wanita muda dan pembantunya, bertemu dengan insinyur, mengira dia adalah pemburu hadiah.",
  ui_story_5080_50800901_51_dialog_content = "Mereka saling takut dan mulai mengejar satu sama lain, namun tetap erat terhubung oleh ketidakpastian nasib.",
  ui_story_5080_50800901_52_dialog_content = "Dengan intervensi insinyur, wanita muda dan pembantunya berhasil melarikan diri dari ksatria.",
  ui_story_5080_50800901_53_dialog_content = "Dan berkat kesalahan sang ksatria, agen itu kehilangan pelarianya, dan akhirnya hanya bisa melacaknya sampai ke Desa Saltstone.",
  ui_story_5080_50800901_54_dialog_content = "Sepertinya legenda ini semua tentang orang-orang bodoh.",
  ui_story_5080_50800901_55_dialog_content = "Memang, tapi karena mereka adalah orang bodoh, mereka tidak pernah benar-benar saling menyakiti.",
  ui_story_5080_50800901_56_dialog_content = "Mereka semua berpegang teguh pada keyakinan mereka, jelas memiliki kesempatan untuk menyerang, namun tidak ingin saling menyakiti.",
  ui_story_5080_50800901_57_dialog_content = "Saya rasa saya suka cerita seperti ini.",
  ui_story_5080_50800901_58_dialog_content = "Pada tahap terakhir perjalanan mereka, mereka menemui badai pasir yang jarang terjadi. Segala sesuatu di jalur mereka dilahap oleh pasir yang mengamuk.",
  ui_story_5080_50800901_59_dialog_content = "Tepat pada waktunya, yang diburu membantu para pemburu, dan para pemburu pun menyerah dalam pengejarannya.",
  ui_story_5080_50800901_60_dialog_content = "Setelah semua yang terjadi, misi para pemburu sudah lama lewat batas waktu, dan mereka sendiri akan dianggap sebagai desertir.",
  ui_story_5080_50800901_61_dialog_content = "Terjebak dalam situasi yang sama, dukungan mutual akhirnya membawa mereka untuk saling mengerti dan mempercayai satu sama lain.",
  ui_story_5080_50800901_62_dialog_content = "Mereka membuat perjanjian untuk mencapai Desa Saltstone bersama, untuk menetap dan hidup dalam damai di sana.",
  ui_story_5080_50800901_63_dialog_content = "Apakah mereka mendapatkan akhir cerita seperti dalam dongeng?",
  ui_story_5080_50800901_64_dialog_content = "Tidak. Ketika mereka tiba di kampung halaman pembantu itu, yang seharusnya menjadi oasis Desa Saltstone, mereka menemukan desa itu telah dihancurkan oleh letusan gunung berapi.",
  ui_story_5080_50800901_65_dialog_content = "Para penyintas juga menjadi sasaran perampok dan terjebak dalam neraka kehidupan.",
  ui_story_5080_50800901_66_dialog_content = "Oase itu tidak ada. Mereka ditakdirkan untuk tidak pernah menemukan kedamaian.",
  ui_story_5080_50800901_67_dialog_content = "Orang luar kehilangan harapan, menyadari bahwa tempat ini tidak berbeda dengan dunia yang telah mereka tinggalkan...",
  ui_story_5080_50800901_68_dialog_content = "...",
  ui_story_5080_50800901_69_dialog_content = "Para penyintas, dipimpin oleh orakel desa, melarikan diri menuju gerbang desa, tepat pada waktunya untuk bertemu dengan orang-orang asing ini.",
  ui_story_5080_50800901_70_dialog_content = "Mereka yang mencari suaka tiba-tiba menjadi tempat perlindungan bagi orang lain.",
  ui_story_5080_50800901_71_dialog_content = "Bingung, baik ksatria yang tegas maupun prajurit yang tak kenal kompromi tidak bisa memahami apa yang diminta dari mereka pada saat itu.",
  ui_story_5080_50800901_72_dialog_content = "Menghadapi situasi hidup dan mati, tidak ada yang menyangka insinyur itu akan mengangkat kunci pas di tangannya dan menyerang para bandit.",
  ui_story_5080_50800901_73_dialog_content = "Tindakan beraninya menginspirasi yang lain, dan para bandit akhirnya berhasil diusir.",
  ui_story_5080_50800901_74_dialog_content = "Cerita yang heroik! Biar aku tebak—kunci itu adalah Rediesel Wrench legendaris, benar kan?",
  ui_story_5080_50800901_75_dialog_content = "Jangan terburu-buru, cerita ini belum berakhir.",
  ui_story_5080_50800901_76_dialog_content = "Karena insinyur itu, orang-orang menemukan harapan sekali lagi. Dan dengan demikian, mereka berangkat sekali lagi, mencari oasis baru di padang pasir.",
  ui_story_5080_50800901_77_dialog_content = "Sepanjang perjalanan, mereka secara bertahap menyerap lebih banyak nomaden ke dalam kelompok mereka, menjadi kekuatan yang formidabel tanpa mereka sadari.",
  ui_story_5080_50800901_78_dialog_content = "Akhirnya, mereka menemukan sebuah oasis kecil yang kaya akan rediesel dan menetap di sana.",
  ui_story_5080_50800901_79_dialog_content = "Itulah legenda Attar... tidak, pemimpin sebelumnya yang memberitahuku.",
  ui_story_5080_50800901_80_dialog_content = "Ini membuktikan bahwa dahulu kala, gurun ini dihuni oleh Aurorian.",
  ui_story_5080_50800901_81_dialog_content = "Orang-orang itu, sama seperti kita, semua berusaha menemukan cara hidup mereka sendiri.",
  ui_story_5080_50800901_82_dialog_content = "Tempat perlindungan bawah tanah ini mungkin adalah tempat untuk melarikan diri dari pengejar atau bandit, benar?",
  ui_story_5080_50800901_83_dialog_content = "Tapi apakah orang-orang ini ditelan oleh gunung berapi yang meletus atau ditinggalkan setelah menemukan gunung berapi di dalam terowongan... Aku tidak tahu.",
  ui_story_5080_50800901_84_dialog_content = "Tsk, aku mulai merasa agak iri di sini... Ini tidak adil! Kenapa bos lama menceritakan semua itu kepada kamu dan bukan kepada kami?",
  ui_story_5080_50800901_85_dialog_content = "Nah, itu hanya karena kamu tidak menunjukkan sedikit pun minat.",
  ui_story_5080_50800901_86_dialog_content = "Aku penuh rasa penasaran dan sangat tertarik dengan ceritanya, selalu merengek agar dia menceritakan lebih banyak.",
  ui_story_5080_50800901_87_dialog_content = "Tapi setelah dipikirkan, rasanya semakin banyak yang kamu ketahui, semakin kamu terbungkus dalam rasa kehampaan—rasa bahwa masa lalu akan perlahan memudar...",
  ui_story_5080_50800901_88_dialog_content = "Tahu tidak, Sinsa, dulu kamu hanya seorang pemula yang selalu sibuk menjaga adikmu.",
  ui_story_5080_50800901_89_dialog_content = "Hidup bukan hanya tentang kebahagiaan dan pelangi saat itu—kami mencari-cari makanan dari pagi hingga malam.",
  ui_story_5080_50800901_90_dialog_content = "Kamu juga punya banyak tugas, mengajar Azure untuk mengemudi, ingat?",
  ui_story_5080_50800901_91_dialog_content = "Hanya dengan hidup saja sudah cukup luar biasa... Saya selalu berpikir bahwa hidup di masa sekarang adalah yang paling penting.",
  ui_story_5080_50800901_92_dialog_content = "Saat itu, kita tidak memiliki cara untuk menggali masa lalu.",
  ui_story_5080_50800901_93_dialog_content = "Tapi hei, waktu telah berubah!",
  ui_story_5080_50800901_94_dialog_content = "Sekarang, kehidupan di Rediesel Wrench penuh dengan kebahagiaan dan warna-warni... dan aku siap menjadi kunci pas yang paling tajam di kotak perkakas!",
  ui_story_5080_50800901_95_dialog_content = "Tunggu saja, Sinsa. Aku akan belajar keras saat kita kembali dan menjadi pemimpin yang lebih baik daripada kamu suatu hari nanti!",
  ui_story_5080_50800901_96_dialog_content = "Kamu bocah punk... Bukankah kehidupan nyaman kita semua berkat darah, keringat, dan air mataku?",
  ui_story_5080_50800901_97_dialog_content = "Maksudmu, dalam cerita itu, orang yang mengangkat kunci inggrisnya menjadi semacam simbol spiritual.",
  ui_story_5080_50800901_98_dialog_content = "Tapi kunci pas insinyur Illumina bukanlah senjata, dan tidak pernah memiliki dimensi yang berlebihan seperti itu.",
  ui_story_5080_50800901_99_dialog_content = "Kunci pas di tangan Sinsa mungkin beratnya satu ton sekarang, bukan?",
  ui_story_5080_50800901_100_dialog_content = "Benar. Selain aku, kamu tidak akan menemukan banyak orang yang bisa memutarnya begitu saja seperti tidak ada apa-apanya.",
  ui_story_5080_50800901_101_dialog_content = "Apa jenis insinyur yang akan membawa kunci seperti itu?",
  ui_story_5080_50800901_102_dialog_content = "Burung pemangsa kecil, apakah kamu mengatakan kisah ini tidak benar?",
  ui_story_5080_50800901_103_dialog_content = "Mungkin legenda ini dibuat oleh pemimpinmu untuk mempercantik masa lalu Rediesel Wrench.",
  ui_story_5080_50800901_104_dialog_content = "Menurut catatan Illumina, gurun ini selalu dikuasai oleh bandit, menciptakan masalah dan mendorong banyak orang untuk menjadi desertir.",
  ui_story_5080_50800901_105_dialog_content = "Orang-orang ini menyebut diri mereka Geng Rediesel, dan terus-menerus mengancam Aurorian lainnya.",
  ui_story_5080_50800901_106_dialog_content = "Orang itu... pertama-tama membuat bibi saya menjadi seorang pelarian, kemudian bergabung dengan Geng Rediesel setelah melarikan diri ke sini. Dia kemudian menjadi pemimpin mereka.",
  ui_story_5080_50800901_107_dialog_content = "Dia memaksa para nomaden untuk bergabung dengannya untuk meningkatkan kekuatannya, perlahan-lahan memperluas kekuasaannya di gurun dan mengubahnya menjadi Rediesel Wrench.",
  ui_story_5080_50800901_108_dialog_content = "Cerita-cerita ini hanyalah rekayasa yang dia buat untuk menampilkan sejarah Rediesel Wrench dalam cahaya yang positif.",
  ui_story_5080_50800901_109_dialog_content = "Hei, kau bocah kecil Illumina! Tidak ada yang pernah mengajari kau untuk tidak mengoceh sembarangan tentang seseorang yang dihormati orang lain?",
  ui_story_5080_50800901_110_dialog_content = "Hanya karena kita teman sekarang, bukan berarti kamu bisa bicara seenaknya!",
  ui_story_5080_50800901_111_dialog_content = "Tunggu, kenapa kamu malah mengatakan itu, Kapten? Jika, seperti yang kamu katakan, dia memerintah gurun, kenapa dia perlu repot-repot mempercantik masa lalu?",
  ui_story_5080_50800901_112_dialog_content = "Saya tidak bisa membayangkan pemimpin Sinsa dan yang lainnya percaya menjadi orang seperti itu.",
  ui_story_5080_50800901_113_dialog_content = "Apakah dia... benar-benar ingin melindungi setiap orang?",
  ui_story_5080_50800901_114_dialog_content = "Dan jadi, dia ingin melindungimu dari kebenaran.",
  ui_story_5080_50800901_115_dialog_content = "...",
  ui_story_5080_50800901_116_dialog_content = "Ck, jadi kamu bisa memahami orang, ya?",
  ui_story_5080_50800901_117_dialog_content = "Tunggu... Apakah itu gempa lagi?",
  ui_story_5080_50800901_118_dialog_content = "Tidak, itu suara dari gerombolan Eclipsite.",
  ui_story_5080_50800901_119_dialog_content = "Lihatlah, Nona Soldier Ant dari Illumina. Inilah cara kami di Rediesel Wrench, ini adalah janji yang kami buat untuk menjaga keamanan keluarga kami!",
  ui_story_5080_50800901_120_dialog_content = "Sekarang, perhatikan—kami akan menunjukkan kepada Anda bagaimana tampang keberanian kami!",
  ui_story_5080_50801000_1_dialog_content = "Lihat semua luka bakar ini... Kamu terlalu bersemangat.",
  ui_story_5080_50801000_2_dialog_content = "Heh, sedikit lecet di sana-sini... Aku pernah lihat yang lebih parah!",
  ui_story_5080_50801000_3_dialog_content = "Hei, Roy, sudah waktunya makan belum? Pasti geng ini sudah lapar!",
  ui_story_5080_50801000_4_dialog_content = "Apa yang ada di menu?",
  ui_story_5080_50801000_5_dialog_content = "Benar—waktunya makan malam, waktunya makan malam! Anak-anak, siapkan pancinya!",
  ui_story_5080_50801000_6_dialog_content = "Ayo beraksi, Dawn! Saatnya kita mendapatkan beberapa makanan lezat dari gunung berapi!",
  ui_story_5080_50801000_7_dialog_content = "Apa yang kamu lakukan?",
  ui_story_5080_50801000_8_dialog_content = "Bekerja keras, bermain keras, nona kecil Illumina.",
  ui_story_5080_50801000_9_dialog_content = "Jangan terlihat begitu terkejut. Mereka selalu seperti ini. Mereka tidak pernah malas kalau soal makanan.",
  ui_story_5080_50801000_10_dialog_content = "Jika kamu tidak suka dengan masakan eksotis mereka, kami juga membawa beberapa makanan.",
  ui_story_5080_50801000_11_dialog_content = "Tapi, kami sedang menjalankan misi sekarang!",
  ui_story_5080_50801000_12_dialog_content = "Bagaimana kamu bisa makan seperti ini...? Bagaimana jika kita diserang tiba-tiba?",
  ui_story_5080_50801000_13_dialog_content = "Hatchling Dua, Caelestite Satu, White Lancer—lanjutkan misimu.",
  ui_story_5080_50801000_14_dialog_content = "Siap, Kapten!",
  ui_story_5080_50801000_15_dialog_content = "<color=#e8d9bb>Gruk...</color>",
  ui_story_5080_50801000_16_dialog_content = "Ups... Maaf... Aku melewatkan sarapan tadi pagi...",
  ui_story_5080_50801000_17_dialog_content = "...",
  ui_story_5080_50801000_18_dialog_content = "Kapten, seorang prajurit Illumina yang berpengalaman biasa mengatakan kepada kami, \"Makanlah! Perut yang kenyang memberimu kekuatan untuk bertarung hingga makanan berikutnya!\"",
  ui_story_5080_50801000_19_dialog_content = "Dia bersumpah dengan aturan ini, dan semua orang setuju.",
  ui_story_5080_50801000_20_dialog_content = "Zeta dan Vice telah sibuk bertarung dan bepergian sejak mereka bangun...",
  ui_story_5080_50801000_21_dialog_content = "Para prajurit Illumina yang tua itu tahu semua tentang bertempur dengan perut kosong.",
  ui_story_5080_50801000_22_dialog_content = "Namun, mereka tetap bertahan.",
  ui_story_5080_50801000_23_dialog_content = "Itulah sebabnya mereka berharap generasi muda bisa makan lebih baik daripada mereka.",
  ui_story_5080_50801000_24_dialog_content = "Saya rasa kita tidak bisa melanjutkan tanpa mengisi ulang energi kita. Untuk memastikan misi selesai, saya akan memberi Anda waktu untuk makan.",
  ui_story_5080_50801000_25_dialog_content = "Aku akan berjaga. Tidak semua orang bisa santai...",
  ui_story_5080_50801000_26_dialog_content = "Kapten, setidaknya makanlah beberapa dari ransum ini! Kapten...!",
  ui_story_5080_50801000_27_dialog_content = "Biarkan dia, dia hanya ingin memastikan misi ini dijalankan dengan sempurna.",
  ui_story_5080_50801000_28_dialog_content = "Kami kembali—Hei, kau mulai tanpa kami!",
  ui_story_5080_50801000_29_dialog_content = "Para pahlawan itu semua tentang efisiensi! Aku pergi untuk berdiri jaga!",
  ui_story_5080_50801000_30_dialog_content = "... Kecepatan Anda makan sangat terpuji. Dengan latihan, Anda bisa menjadi tentara yang hebat.",
  ui_story_5080_50801000_31_dialog_content = "Aku tidak ingin menjadi prajurit Illumina. Aku ditakdirkan untuk menyelamatkan dunia!",
  ui_story_5080_50801000_32_dialog_content = "Cicipi ini! Dendeng serangga panggang ini enak lho! Saya bawa khusus untukmu.",
  ui_story_5080_50801000_33_dialog_content = "Terima kasih... Gadis Lolipop.",
  ui_story_5080_50801000_34_dialog_content = "Aku adalah Penyelamat Dunia, bukan karakter sampingan!",
  ui_story_5080_50801000_35_dialog_content = "Kamu keren dan semua, tapi selera kamu perlu diperbaiki! Pasti karena kamu dibesarkan oleh Raja Iblis, ya?",
  ui_story_5080_50801000_36_dialog_content = "Nasib buruk, Penyelamat Dunia dari Musuh Bebuyutan yang Hilang, Kakak Perempuan!",
  ui_story_5080_50801000_37_dialog_content = "Saudarimu?",
  ui_story_5080_50801000_38_dialog_content = "Yeah! Kita sekarang adalah Saudari Prajurit! Jangan khawatir, aku akan menemukan cara untuk membebaskanmu dari belenggu pikiranmu itu!",
  ui_story_5080_50801000_39_dialog_content = "Hah? Kamu tersenyum? Itu pertama kalinya aku melihatmu tersenyum... Pasti ini karena kekuatan keluarga, kan?!",
  ui_story_5080_50801000_40_dialog_content = "Jangan pedulikan dia; dia hanya suka bermain peran, mengarang cerita, dan sebagainya.",
  ui_story_5080_50801000_41_dialog_content = "Saudari-saudari... Hmm...",
  ui_story_5080_50801000_42_dialog_content = "Sepertinya kamu teringat sesuatu. Apakah kamu punya saudari, mungkin?",
  ui_story_5080_50801000_43_dialog_content = "Ya... dia sangat pintar, lebih kuat dari saya, dan... sangat menggemaskan.",
  ui_story_5080_50801000_44_dialog_content = "Setelah dia menyelesaikan studinya, dia akan menjadi tentara yang teladan.",
  ui_story_5080_50801000_45_dialog_content = "Aku bangga padanya.",
  ui_story_5080_50801000_46_dialog_content = "Apa...? Ugh...",
  ui_story_5080_50801000_47_dialog_content = "Zeta, kelihatannya kamu tidak percaya.",
  ui_story_5080_50801000_48_dialog_content = "Dia membuatku cemburu... Maksudku! Bukan cemburu! Hanya...",
  ui_story_5080_50801000_49_dialog_content = "Memiliki kakak seperti kamu, adik perempuanmu pasti sangat bahagia.",
  ui_story_5080_50801000_50_dialog_content = "'Karena Eagleshot jauh lebih baik daripada penyihir itu.",
  ui_story_5080_50801000_51_dialog_content = "Tidak, saya masih jauh dari cukup baik.",
  ui_story_5080_50801000_52_dialog_content = "Aku akan terus berusaha... berusaha... untuk tidak menambah masalah bagi keluargaku.",
  ui_story_5080_50801000_53_dialog_content = "Oh, la, la, la!",
  ui_story_5080_50801000_54_dialog_content = "Apa ini tiba-tiba serenade? Aku bahkan tidak bisa mendengar pikiranku sendiri!",
  ui_story_5080_50801000_55_dialog_content = "Kamu belum dengar? Barbara bilang dia punya potensi lebih besar darimu, jadi dia latihan seperti orang gila akhir-akhir ini.",
  ui_story_5080_50801000_56_dialog_content = "Eh?",
  ui_story_5080_50801000_57_dialog_content = "\"Tenor Pertama Rediesel, lebih menggugah daripada Sinsa\"—kata-kata Barbara.",
  ui_story_5080_50801000_58_dialog_content = "Jadi dia berlatih seperti gila, bersiap untuk memikat semua orang dengan gaya vokalnya.",
  ui_story_5080_50801000_59_dialog_content = "Wow, kalau begitu sepertinya aku juga harus berlatih. Aku sudah berjanji pada mereka untuk bergabung dengan band.",
  ui_story_5080_50801000_60_dialog_content = "Di mana stik drum itu... Bukan ini... bukan itu juga... Bingo!",
  ui_story_5080_50801000_61_dialog_content = "Baiklah, aku di sini untuk menjaga irama. Ayo kita mulai!",
  ui_story_5080_50801000_62_dialog_content = "Orang-orang ini...",
  ui_story_5080_50801000_63_dialog_content = "Kencangkan, Fleur! Curahkan hati dan jiwa Anda ke dalam stik drum itu!",
  ui_story_5080_50801000_64_dialog_content = "Apakah kamu selaras denganku? Sudah mengikuti suaraku belum?",
  ui_story_5080_50801000_65_dialog_content = "Kecuali jika kamu meredakan suaramu, bahkan para Eclipsite akan mengejar suaramu.",
  ui_story_5080_50801000_66_dialog_content = "Jangan berisik di dinding, Fleur! Hati-hati jangan sampai menarik perhatian Eclipsites!",
  ui_story_5080_50801000_67_dialog_content = "Baguslah Sinsa punya akal sehat, Rediesel Wrench...",
  ui_story_5080_50801000_68_dialog_content = "Ambil kunci pas itu. Jika kamu ingin berlatih, mulailah memukul dengan ini! Silakan, hancurkan dirimu sendiri!",
  ui_story_5080_50801000_69_dialog_content = "Kau tidak takut menarik perhatian Eclipsites?",
  ui_story_5080_50801000_70_dialog_content = "Itu bukan masalah besar, bukan? Kami sudah tidak sabar untuk menemukannya. Naikkan nada, lebih tinggi! Lebih tinggi!",
  ui_story_5080_50801000_71_dialog_content = "Ah... Benar-benar tidak bisa diperbaiki.",
  ui_story_5080_50801000_72_dialog_content = "Tinggal di gurun pasir yang luas ini, mereka tidak pernah mengembangkan semangat penasaran. Mereka hanya bermain-main setiap hari...",
  ui_story_5080_50801000_73_dialog_content = "Tapi Jeriah, apa sebenarnya spirit of inquiry itu?",
  ui_story_5080_50801000_74_dialog_content = "Caelestite kecil, apakah kamu juga mulai meragukan?",
  ui_story_5080_50801000_75_dialog_content = "Tidak, saya hanya berpikir bahwa... meskipun mereka tinggal di lingkungan yang keras, kamu tidak pernah mendengar Sinsa dan yang lainnya mengeluh.",
  ui_story_5080_50801000_76_dialog_content = "Mereka selalu berusaha menemukan kebahagiaan dalam hidup, dan mereka tampak cukup baik dalam hal itu.",
  ui_story_5080_50801000_77_dialog_content = "Saya selalu merasa bahwa mereka sudah penuh dengan semangat penasaran, ketika datang untuk menjelajahi kehidupan mereka sendiri.",
  ui_story_5080_50801000_78_dialog_content = "Ya, Nona Jeriah. Kamu tahu banyak, tapi sepertinya kamu sedikit terlalu negatif tentang kehidupan pada umumnya...",
  ui_story_5080_50801000_79_dialog_content = "Tentu saja, tanpa bermaksud menyinggung, tapi... apakah itu benar-benar cara kamu ingin bersikap?",
  ui_story_5080_50801000_80_dialog_content = "Datang dari seorang prajurit Illumina seperti Vice, aku tidak benar-benar yakin bagaimana harus merespon.",
  ui_story_5080_50801000_81_dialog_content = "Mungkin kamu percaya bahwa orang-orang dari Illumina tidak memiliki hak untuk memberi ceramah tentang kehidupan dan kebebasan kepada orang lain.",
  ui_story_5080_50801000_82_dialog_content = "Tapi saya tumbuh besar di sana, dan saya tahu betul—tujuan dari Illumina adalah untuk berfungsi sebagai perisai, melindungi semua orang yang berada di belakang kita.",
  ui_story_5080_50801000_83_dialog_content = "Kita mungkin harus membuat pengorbanan, tapi saya tahu bahwa orang-orang di balik perisai itu bisa hidup dengan bahagia.",
  ui_story_5080_50801000_84_dialog_content = "Senyum di wajah mereka adalah yang saya usahakan untuk lindungi.",
  ui_story_5080_50801000_85_dialog_content = "Saya senang melihat mereka berusaha sebaik mungkin menjalani hidup mereka. Melihat mereka begitu bebas sudah cukup bagiku.",
  ui_story_5080_50801000_86_dialog_content = "Arti dari... perlindungan...?!",
  ui_story_5080_50801000_87_dialog_content = "Jadi, kalian semua memiliki pandangan yang berbeda tentang kehidupan.",
  ui_story_5080_50801000_88_dialog_content = "Hidup untuk orang lain? Menurut pandangan saya, itu bukanlah yang saya sebut sebagai hidup sepenuhnya bebas, tetapi itu tetap patut dihargai.",
  ui_story_5080_50801000_89_dialog_content = "Hmm, bagaimana aku harus memahami ini? Kamu seharusnya menjelajahi hidup dengan cara kamu sendiri, namun kamu sangat erat terhubung dengan orang lain...",
  ui_story_5080_50801000_90_dialog_content = "Saya masih percaya bahwa ikatan yang ada antara orang-orang tidak bisa diputuskan.",
  ui_story_5080_50801000_91_dialog_content = "Bahkan kamu, Jeriah, tidak bisa menghapus ikatan yang telah terbentuk dengan kami... meskipun kamu tidak ingin menjadi orang yang ceria dan ceroboh.",
  ui_story_5080_50801000_92_dialog_content = "...Benar, rumah itu kini menjadi kanvas dari coretan-coretan, gunungan hadiah dan buku untuk anak-anak.",
  ui_story_5080_50801000_93_dialog_content = "Tidak peduli seberapa licik saya mencoba, anak-anak itu masih bisa menangkap saya, dan mereka bahkan telah membawa mobil saya untuk joyride.",
  ui_story_5080_50801000_94_dialog_content = "Mereka cukup merusaknya, tapi aku berhasil menambalnya dengan baik!",
  ui_story_5080_50801000_95_dialog_content = "Beberapa patch yang cukup unik juga.",
  ui_story_5080_50801000_96_dialog_content = "Setelah semua ini, Jeriah, apakah kamu masih merasa sendirian?",
  ui_story_5080_50801000_97_dialog_content = "Apa ini, Caelestite kecil? Apakah kamu benar-benar begitu khawatir tentang hubungan sosialku? Apakah kamu begitu khawatir tentangku?",
  ui_story_5080_50801000_98_dialog_content = "Meskipun aku mencoba untuk berbaur dengan orang-orang ini, itu tidak akan mengurangi keinginan berkelanaku.",
  ui_story_5080_50801000_99_dialog_content = "Oke, itu iramanya!",
  ui_story_5080_50801000_100_dialog_content = "Aku bisa merasakan api dalam dirimu, aku merasakan getaranmu—sekarang mari kita benar-benar melantunkannya!",
  ui_story_5080_50801000_101_dialog_content = "<color=#e8d9bb>Di bawah komando Sinsa, Rediesel Wrench menyanyikan lagu mereka dengan gila.</color>",
  ui_story_5080_50801000_102_dialog_content = "<color=#e8d9bb>Ini adalah paduan suara yang sangat tidak harmonis, tetapi setiap orang memberikan yang terbaik, tidak pernah berpikir untuk berhenti—ini adalah harmoni khusus mereka sendiri.</color>",
  ui_story_5080_50801000_103_dialog_content = "Kepribadian mereka terlalu berbeda dan menonjol, bukan tipe yang bisa menyatu.",
  ui_story_5080_50801000_104_dialog_content = "Namun, kru yang beragam ini dari karakter-karakter unik telah menjadi seperti keluarga.",
  ui_story_5080_50801000_105_dialog_content = "Terus bernyanyi, lihat saja panci sup.",
  ui_story_5080_50801000_106_dialog_content = "Oh, Jeriah, saya melihat sesuatu yang menakjubkan yang mereka sebut hot pot saat saya berada di Longzhou.",
  ui_story_5080_50801000_107_dialog_content = "Anda memasak kaldu pedas, memasukkan makanan apa pun yang Anda inginkan, dan hanya mengambilnya saat Anda ingin memakannya.",
  ui_story_5080_50801000_108_dialog_content = "Tidak peduli apa yang kamu masukkan ke dalam hot pot pedas itu, rasanya tidak akan tercampur.",
  ui_story_5080_50801000_109_dialog_content = "Setiap orang yang tinggal di gurun saat ini agak seperti panci panas.",
  ui_story_5080_50801000_110_dialog_content = "Rediesel itu luar biasa. Gurunnya begitu luas, dengan cukup ruang untuk semua orang untuk meregangkan diri dan menjelajahi perjalanan hidup mereka...",
  ui_story_5080_50801000_111_dialog_content = "Hot pot... kamu bilang?",
  ui_story_5080_50801000_112_dialog_content = "Jeriah, dengarkan—apakah kamu mendengar itu? Itu elang yang sedang bernyanyi.",
  ui_story_5080_50801000_113_dialog_content = "Ini hanya tangisan burung, tidak lebih.",
  ui_story_5080_50801000_114_dialog_content = "Hahaha... Jeriah, bagaimana kamu tahu itu tidak sedang menyanyikan lagu untuk perjalanannya sendiri?",
  ui_story_5080_50801000_115_dialog_content = "... Kenapa kamu menceritakan legenda itu padaku?",
  ui_story_5080_50801000_116_dialog_content = "Bukankah itu menakjubkan? Orang asing yang lahir di Rediesel, Lumopolis, dan Illumina akhirnya menjadi satu keluarga besar meskipun perbedaan setiap orang.",
  ui_story_5080_50801000_117_dialog_content = "Meski hidup di dunia yang penuh bencana tanpa henti, jiwa-jiwa yang kesepian masih mau berbagi emosi mereka.",
  ui_story_5080_50801000_118_dialog_content = "Beberapa orang bersedia mengangkat kunci pas untuk melindungi orang lain dan menjadi pemimpin. Sementara yang lain bersedia mengikuti orang-orang seperti itu dan bekerja sama.",
  ui_story_5080_50801000_119_dialog_content = "Gurun telah menjadi rumah kami.",
  ui_story_5080_50801000_120_dialog_content = "Hanya melewati langit dalam perjalanan mereka, mereka berkumpul menjadi kawanan, menemukan oasis mereka sendiri.",
  ui_story_5080_50801000_121_dialog_content = "Jeriah, berusahalah untuk menjelajahi kehidupanmu sendiri, terbang tinggi, dan nyanyikan isi hatimu!",
  ui_story_5080_50801000_122_dialog_content = "Bagaimana kamu bisa terus berkelana selamanya? Sudah ada tempat untukmu di sini—",
  ui_story_5080_50801101_1_dialog_content = "<color=#e8d9bb>Suara gitar, membakar seperti matahari, menembus panas gurun, menenangkan tanah yang gemetar.</color>",
  ui_story_5080_50801101_2_dialog_content = "Maju, maju! Semangatku tidak akan pernah mati!",
  ui_story_5080_50801101_3_dialog_content = "Ini sangat panas di sini, dan dia masih berlatih lagu baru. Bagus untuknya.",
  ui_story_5080_50801101_4_dialog_content = "Aku tidak akan kalah! Tiny One, giliran kita!",
  ui_story_5080_50801101_5_dialog_content = "Panggung sudah siap. Aku punya hal yang harus dikerjakan, kamu lanjutkan.",
  ui_story_5080_50801101_6_dialog_content = "Halo? Ini Rediesel Wrench...",
  ui_story_5080_50801101_7_dialog_content = "Bopper, Jona mendesakku untuk kembali. Ada apa?",
  ui_story_5080_50801101_8_dialog_content = "Awas! Idola yang selalu bersinar ada di sini! Diesel Sweety, Barbara!",
  ui_story_5080_50801101_9_dialog_content = "Halo? Ini Rediesel Wrench... Azure, apakah itu kamu?",
  ui_story_5080_50801101_10_dialog_content = "Wah, ramai sekali di sana.",
  ui_story_5080_50801101_11_dialog_content = "Matahari yang ganas sedang menyala! Matahari yang ganas terus mengamuk!!!",
  ui_story_5080_50801101_12_dialog_content = "Halo? Ini Rediesel Wrench...",
  ui_story_5080_50801101_13_dialog_content = "Halo? Aku tidak bisa mendengar apa-apa. Lupakan, aku akan menunggu adik perempuan kembali saja.",
  ui_story_5080_50801101_14_dialog_content = "Hei, Maggie, apakah kamu sudah memasang ranjau darat dengan benar?",
  ui_story_5080_50801101_15_dialog_content = "Panas sekali sih... Aku paham, aku paham, aku akan melakukannya sekarang!",
  ui_story_5080_50801101_16_dialog_content = "Ayo tutupi seluruh perimeter kamp sebelum matahari terbenam!",
  ui_story_5080_50801101_17_dialog_content = "Apakah kita benar-benar memerlukan semua jebakan ini?",
  ui_story_5080_50801101_18_dialog_content = "<color=#e8d9bb>Getaran gurun terus berlanjut. Gunung berapi di kejauhan mengaum, meluapkan kemarahannya.</color>",
  ui_story_5080_50801101_19_dialog_content = "Para pemimpin telah pergi sejak lama...",
  ui_story_5080_50801101_20_dialog_content = "Tidak ada respons terhadap komunikasi.",
  ui_story_5080_50801101_21_dialog_content = "Tiny One, Fleur sedang keluar sekarang, tolong bantu aku memperbaiki truk.",
  ui_story_5080_50801101_22_dialog_content = "Hmph, apakah itu tantangan? Kamu masih tidak mau mengakui bahwa aku lebih baik?",
  ui_story_5080_50801101_23_dialog_content = "Apa yang sedang kamu bicarakan!?",
  ui_story_5080_50801101_24_dialog_content = "Haruskah kita berangkat naik Lepidoz?",
  ui_story_5080_50801101_25_dialog_content = "Hei, Bopper, apakah itu Azure di telepon?",
  ui_story_5080_50801101_26_dialog_content = "Entahlah...",
  ui_story_5080_50801101_27_dialog_content = "Bagaimana bisa kamu tidak tahu jika kamu yang mengangkat teleponnya?",
  ui_story_5080_50801101_28_dialog_content = "Kembali berpatroli, dan nanti...",
  ui_story_5080_50801101_29_dialog_content = "Lupakan saja, pasti itu Azure. Siapa lagi yang bisa itu?",
  ui_story_5080_50801101_30_dialog_content = "Saya tidak bisa melewatkan kesempatan langka ini. Akhirnya, saya harus mengajaknya minum.",
  ui_story_5080_50801101_31_dialog_content = "... Dengarkan aku.",
  ui_story_5080_50801101_32_dialog_content = "Kita di sini, tepat di mulut gunung berapi.",
  ui_story_5080_50801101_33_dialog_content = "Yang perlu kita lakukan hanyalah melompat ke sini, dan kita berada di dalam gunung api—",
  ui_story_5080_50801101_34_dialog_content = "Tingkat aktivitas gunung berapi ini... Eagle Hunter One, aktifkan mode deteksi!",
  ui_story_5080_50801101_35_dialog_content = "... Seperti yang diharapkan, gunung berapi ini sangat aktif.",
  ui_story_5080_50801101_36_dialog_content = "Mengapa belum mencapai letusan?",
  ui_story_5080_50801101_37_dialog_content = "Ini bukan gunung berapi yang tidur lalu bangun. Ia selalu seaktif ini.",
  ui_story_5080_50801101_38_dialog_content = "Belum pernah meletus selama bertahun-tahun ini.",
  ui_story_5080_50801101_39_dialog_content = "Aneh…",
  ui_story_5080_50801101_40_dialog_content = "Wah, ini beneran? Eclipsites merayap keluar dari mulut gunung berapi!",
  ui_story_5080_50801101_41_dialog_content = "Para Eclipsite itu... energi lava mereka pasti berasal dari sini.",
  ui_story_5080_50801101_42_dialog_content = "Waktunya pergi! Lompat!",
  ui_story_5080_50801101_43_dialog_content = "Vice... Carleen... Tunggu aku! Ini sangat tinggi!",
  ui_story_5080_50801102_1_dialog_content = "Eclipsite dihitung sebagai makhluk hidup, 'kan?",
  ui_story_5080_50801102_2_dialog_content = "Bagaimana bisa mereka mampu hidup di mulut gunung berapi ini, tidak hanya memanfaatkan energi lava tetapi juga sama sekali tidak takut padanya?",
  ui_story_5080_50801102_3_dialog_content = "Fleur, bisakah kamu hitung untuk kita? Bagaimana caranya kita meledakkan mulut gunung berapi ini sampai ke langit?",
  ui_story_5080_50801102_4_dialog_content = "Jika Eclipsites tidak takut dengan lava, ini mungkin satu-satunya cara untuk mencegah mereka kembali.",
  ui_story_5080_50801102_5_dialog_content = "Itu tidak bisa. Wanita itu benar, ini adalah gunung berapi yang aktif. Setiap ledakan yang sembrono bisa memicu letusan.",
  ui_story_5080_50801102_6_dialog_content = "Gempa itu tak berhenti. Eclipsite akan terus muncul dari kedalaman gunung berapi...",
  ui_story_5080_50801102_7_dialog_content = "Kita tidak tahu apa yang terjadi di luar, jadi kita harus cepat-cepat.",
  ui_story_5080_50801102_8_dialog_content = "Mengapa gunung berapi ini begitu aktif namun tampaknya tidak aktif selama ini?",
  ui_story_5080_50801102_9_dialog_content = "Apa kira-kira alasannya?",
  ui_story_5080_50801102_10_dialog_content = "Kemarahan gunung berapi ini kemungkinan besar disebabkan oleh energi leyline yang tidak stabil.",
  ui_story_5080_50801102_11_dialog_content = "Jika kita bisa menemukan penyebabnya, mungkin kita bisa menyelesaikan krisis ini.",
  ui_story_5080_50801102_12_dialog_content = "Tidak peduli apa, kita harus bergerak cepat.",
  ui_story_5080_50801102_13_dialog_content = "Jika guncangan ini terus berlanjut, bahkan Eclipsites akan terkejut hingga ke permukaan.",
  ui_story_5080_50801102_14_dialog_content = "Rediesel mungkin keras kepala, tapi bagaimana dengan penduduk desa?",
  ui_story_5080_50801102_15_dialog_content = "Sangat benar. Ada pendapat, Sinsa?",
  ui_story_5080_50801102_16_dialog_content = "Tidak ada pilihan lain. Jika orang-orang ini datang dari dalam, saya harus masuk.",
  ui_story_5080_50801102_17_dialog_content = "<size=45>Apa?!</size>",
  ui_story_5080_50801102_18_dialog_content = "Kamu merasa baik-baik saja? Ini adalah gunung berapi yang kita bicarakan, Sinsa.",
  ui_story_5080_50801102_19_dialog_content = "Aku merasa segar seperti hujan, terima kasih banyak. Itulah mengapa aku tidak bisa mengabaikan hal ini.",
  ui_story_5080_50801102_20_dialog_content = "Aku muak dengan gemuruhnya. Baik itu dendam lama atau dendam baru, aku akan menyelesaikan semuanya sekali dan untuk selamanya.",
  ui_story_5080_50801102_21_dialog_content = "Kenapa... kau begitu keras pada dirimu sendiri?",
  ui_story_5080_50801102_22_dialog_content = "Hah! Lucu mendengar itu darimu.",
  ui_story_5080_50801102_23_dialog_content = "Setelah semua, Rediesel Wrench dikenal sebagai orang-orang yang melarikan diri, dan kamu berasal dari latar belakang yang serupa.",
  ui_story_5080_50801102_24_dialog_content = "Kalian semua bertahan hidup selama ini dengan merampok orang lain, bukan? Hanya mengikuti arus, hidup dari hari ke hari.",
  ui_story_5080_50801102_25_dialog_content = "Mengapa kau mau mempertaruhkan hidupmu sekarang?",
  ui_story_5080_50801102_26_dialog_content = "Baiklah, sekarang giliran saya yang menanyai kamu. Apa yang kamu lakukan di Illumina? Kenapa kamu berjalan jauh-jauh ke gunung berapi ini?",
  ui_story_5080_50801102_27_dialog_content = "Aku adalah kapten dari Eagleeye Squad! Aku telah memimpin timku melalui lebih dari empat puluh operasi khusus berisiko tinggi.",
  ui_story_5080_50801102_28_dialog_content = "Tanpa saya, yang lain mungkin akan menghadapi bahaya yang lebih besar.",
  ui_story_5080_50801102_29_dialog_content = "Aku datang demi kejayaan. Aku tidak seperti kalian.",
  ui_story_5080_50801102_30_dialog_content = "Tahu kan, Fleur dan orang tua itu keduanya lahir di Kota Gannon.",
  ui_story_5080_50801102_31_dialog_content = "Mereka tidak mendapatkan kemuliaan di sana—sebaliknya, mereka harus melarikan diri ke gurun karena merasa tercekik.",
  ui_story_5080_50801102_32_dialog_content = "Apa sebenarnya kejayaan itu?",
  ui_story_5080_50801102_33_dialog_content = "Kemuliaan adalah—",
  ui_story_5080_50801102_34_dialog_content = "Nona Illumina, beri aku pencerahan—apakah kau benar-benar memahami arti dari \"pengorbanan\"?",
  ui_story_5080_50801102_35_dialog_content = "Untuk Illumina, untuk pembebasan semua Aurorian, tidak peduli berapa harganya!",
  ui_story_5080_50801102_36_dialog_content = "Saya siap mengorbankan segalanya demi tujuan agung itu!",
  ui_story_5080_50801102_37_dialog_content = "...",
  ui_story_5080_50801102_38_dialog_content = "Kenapa kau menatapku seperti itu?",
  ui_story_5080_50801102_39_dialog_content = "Apakah begitu cara Anda meyakinkan diri sendiri?",
  ui_story_5080_50801102_40_dialog_content = "Sudahlah. Tidak ada gunanya berbicara dengan kamu tentang ini sekarang.",
  ui_story_5080_50801102_41_dialog_content = "Roy, dia masih hidup dalam dunia mimpi.",
  ui_story_5080_50801102_42_dialog_content = "Kamu...!",
  ui_story_5080_50801102_43_dialog_content = "Maaf, aku harus membersihkan banyak serangga yang menginfestasi rumahku. Jangan menghalangi jalanku.",
  ui_story_5080_50801102_44_dialog_content = "Hei, Sinsa, siapa bilang kamu bisa membersihkan sendiri? Jangan lupa tentang kami!",
  ui_story_5080_50801102_45_dialog_content = "Kalian semua, jangan berkerumun. Itu berbahaya.",
  ui_story_5080_50801102_46_dialog_content = "Kau salah bicara, bodoh!",
  ui_story_5080_50801102_47_dialog_content = "Melompat ke dalam gunung berapi bersama? Ini tampak seperti pilihan yang kurang bijaksana.",
  ui_story_5080_50801102_48_dialog_content = "Siap, semuanya... Woah!",
  ui_story_5080_50801102_49_dialog_content = "Ini gempa bumi! Hati-hati!",
  ui_story_5080_50801102_50_dialog_content = "<color=#e8d9bb>Tiba-tiba, gempa bumi terjadi, dan kami yang berdiri di tepi gunung berapi terjatuh ke dalamnya.</color>",
  ui_story_5080_50801102_51_dialog_content = "Sinsa!",
  ui_story_5080_50801102_52_dialog_content = "Eve! Setiap orang! Aku datang!",
  ui_story_5080_50801102_53_dialog_content = "Jangan berpikir untuk mengambil orang lain dariku!",
  ui_story_5080_50801102_54_dialog_content = "<color=#e8d9bb>Sinsa turun seperti bola meriam, menggunakan kekuatan raksasanya untuk melemparkan semua orang ke tempat yang aman.</color>",
  ui_story_5080_50801102_55_dialog_content = "<color=#e8d9bb>Saat aku melihat dia mendekat, semakin dekat dan dekat—aku tidak tahu mengapa, tapi aku tiba-tiba merasa tenang.</color>",
  ui_story_5080_50801102_56_dialog_content = "Pegang tanganku, PlayerName!",
  ui_story_5080_50801102_57_dialog_content = "Tunggu, Sinsa, itu adalah lava leleh di bawah kita! Apa yang sedang kamu lakukan!?",
  ui_story_5080_50801102_58_dialog_content = "Siapa peduli! Cukup bantu aku naik ke sana!",
  ui_story_5080_50801102_59_dialog_content = "Jangan berani-berani berpikir untuk mati padaku, anak!",
  ui_story_5080_50801102_60_dialog_content = "<size=50>Sinsa!!!</size>",
  ui_story_5080_50801201_1_dialog_content = "Misi tercapai! Kontribusi Eagleeye sangat signifikan!",
  ui_story_5080_50801201_2_dialog_content = "Terima kasih atas kerja kerasmu, Rachel. Illumina akan mengenang pengorbananmu.",
  ui_story_5080_50801201_3_dialog_content = "Maju ke depan, soldier. Grand Marshal akan memberikan Medali Kehormatan secara langsung kepada kamu!",
  ui_story_5080_50801201_4_dialog_content = "Mengenai operasi penyelamatan, kami telah melakukan yang terbaik... Maaf, Rachel, ini semua yang bisa saya berikan untukmu. Terima kasih atas usahamu.",
  ui_story_5080_50801201_5_dialog_content = "Aghhh...!",
  ui_story_5080_50801201_6_dialog_content = "Berat sekali…",
  ui_story_5080_50801201_7_dialog_content = "Ha?",
  ui_story_5080_50801201_8_dialog_content = "Mereka ada di sini... di tangan ku... sangat berat...",
  ui_story_5080_50801201_9_dialog_content = "Demi diriku... semua teman satu timku... semua mengorbankan diri...",
  ui_story_5080_50801201_10_dialog_content = "Ada yang ke sini! Dia akan pingsan!",
  ui_story_5080_50801201_11_dialog_content = "Dadaku sakit... Aku tidak terluka, tapi rasa sakitnya tidak berhenti... Tante...",
  ui_story_5080_50801201_12_dialog_content = "Terima kasih, Kapten... Terima kasih telah memberikan segalanya untuk menyelesaikan misi.",
  ui_story_5080_50801201_13_dialog_content = "Sekarang, anak-anak kita tidak akan lagi diingat sebagai \"kegagalan.\"",
  ui_story_5080_50801201_14_dialog_content = "Mereka akhirnya bisa beristirahat sebagai pahlawan.",
  ui_story_5080_50801201_15_dialog_content = "Bukan...",
  ui_story_5080_50801201_16_dialog_content = "Aku sangat sedih, Bibi... Aku menyelesaikan misi, tapi... rasanya sangat sakit...",
  ui_story_5080_50801201_17_dialog_content = "Rachel, anakku, jangan menangis... jangan menangis...",
  ui_story_5080_50801201_18_dialog_content = "Ini semua salahku. Kenapa orang dewasa semua berterima kasih padaku padahal ini semua karena kesalahanku...?",
  ui_story_5080_50801201_19_dialog_content = "Kamu menyelamatkan sisa-sisa harga diri mereka.",
  ui_story_5080_50801201_20_dialog_content = "Tapi, mereka seharusnya sudah pulang dengan selamat dan bersama orang tua mereka.",
  ui_story_5080_50801201_21_dialog_content = "Rachel, lihatlah aku. Apakah kamu benar-benar bisa menanggung tanggung jawab itu? Mengubah setiap orang menjadi pelarian hanya untuk membawa mereka pulang dengan selamat?",
  ui_story_5080_50801201_22_dialog_content = "Aku... aku tidak tahu... aku tidak tahu...",
  ui_story_5080_50801201_23_dialog_content = "Apa yang terjadi, Rachel? Ini adalah misi gagal keenam Anda.",
  ui_story_5080_50801201_24_dialog_content = "Kamu sudah beristirahat cukup lama, jadi mengapa ini terjadi lagi?",
  ui_story_5080_50801201_25_dialog_content = "Maaf, ini semua salahku. Tolong jangan salahkan orang lain.",
  ui_story_5080_50801201_26_dialog_content = "Yang lainnya semua sudah mengeluh tentangmu. Kamu bahkan tidak bisa mengingat nama atau wajah mereka... Apa yang terjadi?",
  ui_story_5080_50801201_27_dialog_content = "Maaf... maafkan aku... maafkan aku...",
  ui_story_5080_50801201_28_dialog_content = "Kamu harus beristirahat dari misi untuk saat ini. Aku akan mengatur waktu istirahat untukmu.",
  ui_story_5080_50801201_29_dialog_content = "Saya benar-benar minta maaf... Komandan...",
  ui_story_5080_50801201_30_dialog_content = "Gray Wing... Namanya adalah Louis. Dia lahir di Utara dan selalu bermimpi untuk menjelajahi gurun.",
  ui_story_5080_50801201_31_dialog_content = "Dia pernah berkata bahwa dia ingin mengukir seruling dari cabang pohon putih di Northland untuk diberikan sebagai hadiah kepada White Goose.",
  ui_story_5080_50801201_32_dialog_content = "Angsa Putih... Namanya adalah Merry. Dia selalu berbicara tentang belajar memainkan instrumen, tetapi tidak pernah benar-benar melakukannya.",
  ui_story_5080_50801201_33_dialog_content = "Dia berjanji akan bermain untukku di hari ulang tahunku, tapi terus menundanya, tahun demi tahun.",
  ui_story_5080_50801201_34_dialog_content = "Dan kemudian ada Red Kestrel dan Green Owl...",
  ui_story_5080_50801201_35_dialog_content = "Mereka kini telah menjadi kalung ini, menggantung di leherku selamanya.",
  ui_story_5080_50801201_36_dialog_content = "\"Apakah kamu benar-benar bisa menanggung tanggung jawab itu? Mengubah setiap orang menjadi pelarian hanya untuk membawa mereka pulang dengan selamat?\"",
  ui_story_5080_50801201_37_dialog_content = "PlayerName!",
  ui_story_5080_50801201_38_dialog_content = "...!",
  ui_story_5080_50801201_39_dialog_content = "Vice, aku di sini! Kapten, Fleur, Zeta, apakah kalian semua baik-baik saja?",
  ui_story_5080_50801201_40_dialog_content = "Aku baik-baik saja.",
  ui_story_5080_50801201_41_dialog_content = "Bagus, PlayerName juga aman.",
  ui_story_5080_50801201_42_dialog_content = "Sepertinya mulut gunung berapi runtuh. Di mana yang lainnya?",
  ui_story_5080_50801201_43_dialog_content = "Sepertinya kita tidak berada di level yang sama... Heh, ini seperti setup klasik sebelum bos akhir di kastil Raja Iblis!",
  ui_story_5080_50801201_44_dialog_content = "Pemimpin Rediesel... Siapa sangka dia benar-benar melompat ke dalam lava demi kita...",
  ui_story_5080_50801201_45_dialog_content = "Mari bergerak ke bawah. Kita perlu menemukan Sinsa.",
  ui_story_5080_50801201_46_dialog_content = "Ini semua adalah lava... Pilihan satu-satunya adalah mengelilingi area-area ini.",
  ui_story_5080_50801201_47_dialog_content = "Misi adalah yang utama. Kita harus menghindari zona bahaya yang tidak perlu.",
  ui_story_5080_50801201_48_dialog_content = "Sinsa menyelamatkan kita... jadi saya harus menemukan mereka. Ikuti saya, saya seharusnya bisa merasakan keberadaan mereka.",
  ui_story_5080_50801201_49_dialog_content = "Caelestite terakhir, kalimatmu selalu begitu keren! Berhenti mencuri perhatianku! Aku juga akan pergi!",
  ui_story_5080_50801201_50_dialog_content = "Kapten, saya juga ingin membantu dalam penyelamatan.",
  ui_story_5080_50801201_51_dialog_content = "... Lenganmu terluka. Apakah itu terjadi ketika kita jatuh?",
  ui_story_5080_50801201_52_dialog_content = "Hah? Oh... itu berdarah.",
  ui_story_5080_50801201_53_dialog_content = "Ambil ini dan balut lukamu. Kamu tidak lagi layak untuk tugas garis depan. Tetap di belakangku saat kita pergi.",
  ui_story_5080_50801201_54_dialog_content = "Pergi?",
  ui_story_5080_50801201_55_dialog_content = "Di bawah sana. Target mungkin berada di bawah kita.",
  ui_story_5080_50801201_56_dialog_content = "Siap, Captain!",
  ui_story_5080_50801201_57_dialog_content = "Tempat ini dipenuhi oleh Eclipsites... Bagaimana mereka bisa hidup di gunung berapi yang aktif?",
  ui_story_5080_50801201_58_dialog_content = "Eclipsites juga adalah makhluk hidup. Tentunya mereka harus menghindari area yang berbahaya seperti itu.",
  ui_story_5080_50801201_59_dialog_content = "Ini tidak seperti apa yang saya pelajari di akademi.",
  ui_story_5080_50801201_60_dialog_content = "... Eclipsites ini ditemukan oleh Illumina sudah lama.",
  ui_story_5080_50801201_61_dialog_content = "Apa? Kenapa aku belum pernah mendengar tentang ini?",
  ui_story_5080_50801201_62_dialog_content = "Saat itu, Komite menugaskan tim bibiku untuk misi yang sama seperti kita.",
  ui_story_5080_50801201_63_dialog_content = "Kaptennya adalah orang yang resmi mendirikan Rediesel Wrench.",
  ui_story_5080_50801201_64_dialog_content = "Tahu tidak, bibi kamu pernah bertugas di Skuad Freebird.",
  ui_story_5080_50801201_65_dialog_content = "Misi terakhirnya adalah tugas penting yang langsung ditugaskan oleh Komite, tetapi bukan hanya dia yang gagal, kaptennya juga membelot dari Illumina setelahnya.",
  ui_story_5080_50801201_66_dialog_content = "Banyak orang mengatakan bahwa Skuad Freebird meninggalkan misi mereka tanpa izin untuk menyelamatkan diri mereka sendiri. Apa pendapatmu tentang ini?",
  ui_story_5080_50801201_67_dialog_content = "Saya malu! Grand Marshal. Saya merasa sangat... bersalah tentang kegagalan bibi saya.",
  ui_story_5080_50801201_68_dialog_content = "Tapi dia sendiri selalu setia. Dia hanya ditarik ke bawah oleh kapten itu!",
  ui_story_5080_50801201_69_dialog_content = "Tolong beri saya kesempatan untuk mengembalikan kehormatan keluarga saya.",
  ui_story_5080_50801201_70_dialog_content = "Tapi jika aib itu tidak terjadi, Bibi Anda mungkin telah mati sebagai pahlawan.",
  ui_story_5080_50801201_71_dialog_content = "Apakah itu akan lebih mudah bagi kamu untuk diterima?",
  ui_story_5080_50801201_72_dialog_content = "Um... aku... aku...",
  ui_story_5080_50801201_73_dialog_content = "Hahaha... Aku hanya bertanya.",
  ui_story_5080_50801201_74_dialog_content = "Sekarang, biarkan aku memberitahumu mengapa aku memanggilmu ke sini—aku punya misi untukmu.",
  ui_story_5080_50801201_75_dialog_content = "Misi terakhir bibimu adalah yang ingin saya tugaskan kepadamu.",
  ui_story_5080_50801201_76_dialog_content = "Grand Marshal?",
  ui_story_5080_50801201_77_dialog_content = "Dulu, Komite memerintahkan Skuad Freebird untuk membawa pulang Eclipsite yang diamati itu dalam keadaan hidup.",
  ui_story_5080_50801201_78_dialog_content = "Mereka menginginkan spesimen hidup untuk tujuan eksperimen.",
  ui_story_5080_50801201_79_dialog_content = "Saya masih skeptis apakah penelitian semacam itu memiliki implikasi positif untuk Illumina, jadi saya tidak akan memaksa Anda untuk melakukan apa pun.",
  ui_story_5080_50801201_80_dialog_content = "Aku...",
  ui_story_5080_50801201_81_dialog_content = "Tentu saja, menangkap Eclipsite itu hidup-hidup mungkin bisa mengobati penyesalanmu atas bibimu.",
  ui_story_5080_50801201_82_dialog_content = "Namun, Rachel, Anda bisa memutuskan sendiri apa yang harus dilakukan.",
  ui_story_5080_50801201_83_dialog_content = "Aku telah memilih seorang rekan tim spesial untuk misi kamu. Kamu pernah mendengar nama \"Vice\", 'kan, aku asumsikan?",
  ui_story_5080_50801201_84_dialog_content = "Kapten muda yang dikabarkan bekerja sama erat dengan seorang Caelestite? Tapi dia sudah bekerja sama dengan Caelestite itu untuk waktu yang cukup lama...",
  ui_story_5080_50801201_85_dialog_content = "Benar. Jika dia pergi bersamamu, bagaimana mungkin pasangannya tidak mengikuti?",
  ui_story_5080_50801201_86_dialog_content = "Mereka adalah individu yang luar biasa. Saya yakin kau akan menemukan beberapa jawaban dalam misi ini.",
  ui_story_5080_50801201_87_dialog_content = "Ini juga permintaan yang dikeluarkan dengan hati-hati oleh Hiiro. Kamu memiliki atasan yang baik, Rachel.",
  ui_story_5080_50801201_88_dialog_content = "Terima kasih banyak, dan terima kasih, Komandan Hiiro. Terima kasih karena masih percaya padaku dan memberiku kesempatan ini!",
  ui_story_5080_50801201_89_dialog_content = "Aku akan segera bersiap untuk berangkat!",
  ui_story_5080_50801201_90_dialog_content = "Tunggu sebentar, Rachel.",
  ui_story_5080_50801201_91_dialog_content = "Tenang saja, saya akan menyelesaikan misi ini!",
  ui_story_5080_50801201_92_dialog_content = "Aku hanya ingin menanyakan satu hal padamu—",
  ui_story_5080_50801201_93_dialog_content = "Bisakah kamu masih menemukan Illumina di dalam hatimu?",
  ui_story_5080_50801201_94_dialog_content = "Aku... Aku tahu apa yang kaucemaskan, Grand Marshal.",
  ui_story_5080_50801201_95_dialog_content = "Memang, saya membuat kesalahan dalam memimpin, kesalahan yang menyebabkan kejatuhan tim saya. Dan saya tampaknya tidak bisa bergaul dengan anggota tim saya dalam keadaan saya saat ini...",
  ui_story_5080_50801201_96_dialog_content = "Tapi tenang saja, saya tidak akan membuat kesalahan yang sama lagi.",
  ui_story_5080_50801201_97_dialog_content = "Itu bukan maksudku, tapi sudahlah. Lanjutkan.",
  ui_story_5080_50801201_98_dialog_content = "Mempunyai mereka di sekitar Anda mungkin dapat mengubah cara berpikir Anda.",
  ui_story_5080_50801201_99_dialog_content = "Mereka adalah pasangan legendaris, orang-orang yang luar biasa. Kata-kata mereka memiliki kekuatan besar.",
  ui_story_5080_50801201_100_dialog_content = "Aku akan lebih memperhatikan dan terus menjaga... Aku tidak akan terlibat dengan rekan tim mana pun, dan aku tidak akan membuat orang lain dalam masalah...",
  ui_story_5080_50801201_101_dialog_content = "Bibi, aku punya kabar baik.",
  ui_story_5080_50801201_102_dialog_content = "Saya punya misi baru.",
  ui_story_5080_50801201_103_dialog_content = "Betulkah? Itu luar biasa. Tapi, apakah kamu baik-baik saja? Jangan memaksakan diri.",
  ui_story_5080_50801201_104_dialog_content = "Saya baik-baik saja, Bibi. Dan kali ini, saya mungkin memiliki kesempatan untuk menyelidiki apa yang terjadi waktu itu.",
  ui_story_5080_50801201_105_dialog_content = "Saya akan membersihkan nama Anda.",
  ui_story_5080_50801201_106_dialog_content = "Jangan berpikir begitu, Rachel.",
  ui_story_5080_50801201_107_dialog_content = "Saya tidak pernah menyesal atas apa yang terjadi waktu itu. Saya sangat berterima kasih kepada kapten yang telah memungkinkan saya untuk bertahan hidup.",
  ui_story_5080_50801201_108_dialog_content = "Kalau bukan karena dia, aku pasti akan kehilangan kesenangan bersamamu.",
  ui_story_5080_50801201_109_dialog_content = "Mengapa kamu masih membela dia... Dia telah meninggalkan Illumina.",
  ui_story_5080_50801201_110_dialog_content = "Kapten itu bukanlah seorang desertir, dan dia bukan pengkhianat!",
  ui_story_5080_50801201_111_dialog_content = "Pasti ada alasan tertentu untuk tindakannya yang tidak kita ketahui, tetapi aku benar-benar percaya padanya dengan sepenuh hati!",
  ui_story_5080_50801201_112_dialog_content = "Dia telah mengubah kalian semua menjadi pengkhianat dan tidak pernah berpikir untuk kembali dalam bertahun-tahun ini! Mengapa kalian masih percaya padanya?!",
  ui_story_5080_50801201_113_dialog_content = "Dia adalah orang yang membawa kita semua kembali dari neraka peleburan itu sendirian!",
  ui_story_5080_50801201_114_dialog_content = "Dia adalah pahlawan sejati!",
  ui_story_5080_50801201_115_dialog_content = "Saya hanya ingin membersihkan nama Anda...",
  ui_story_5080_50801201_116_dialog_content = "Keluarga kita tidak melakukan kesalahan apapun...",
  ui_story_5080_50801201_117_dialog_content = "Kau mau ke mana, Rachel?",
  ui_story_5080_50801201_118_dialog_content = "Kembali, Rachel! Aku melarangmu pergi kesana!",
  ui_story_5080_50801201_119_dialog_content = "Rachel...",
  ui_story_5080_50801201_120_dialog_content = "Meskipun misi Freebird gagal, mereka masih berhasil mengumpulkan banyak intelijen.",
  ui_story_5080_50801201_121_dialog_content = "Informasi yang mereka tinggalkan menyebutkan bagaimana Eclipsite yang mereka amati saat itu adalah spesies bermutasi yang bisa menyerap energi panas bumi untuk bertahan hidup.",
  ui_story_5080_50801201_122_dialog_content = "Dan gunung berapi ini, selalu aktif tetapi tidak pernah mencapai titik kritis erupsi, dipenuhi oleh Eclipsite seperti itu.",
  ui_story_5080_50801201_123_dialog_content = "Ini mungkin karena para Eclipsite ini menyerap energi dari gunung berapi.",
  ui_story_5080_50801201_124_dialog_content = "Ketidakstabilan gunung berapi di Gurun Rediesel disebabkan oleh energi panas bumi yang tidak stabil.",
  ui_story_5080_50801201_125_dialog_content = "Aktivitas Eclipsite ini menyebabkan ketidakseimbangan energi geotermal, namun makanan mereka dari gunung berapi menekan erupsi.",
  ui_story_5080_50801201_126_dialog_content = "Dari perspektif ini, kemungkinan besar para Eclipsite telah berkembang biak di bawah tanah selama ini.",
  ui_story_5080_50801201_127_dialog_content = "Meski hanya satu yang diamati saat itu, mereka sekarang telah menjadi sebuah koloni.",
  ui_story_5080_50801201_128_dialog_content = "Dan mereka bahkan telah mewariskan sifat menakutkan ini secara genetik.",
  ui_story_5080_50801201_129_dialog_content = "Tunggu, apakah itu berarti kita harus berterima kasih kepada makhluk-makhluk ini?",
  ui_story_5080_50801201_130_dialog_content = "Ini berkat mereka gunung berapi itu tidak meletus? Yah, itu benar-benar menyebalkan.",
  ui_story_5080_50801201_131_dialog_content = "Tapi jika bukan karena Eclipsite ini, energi panas bumi tidak akan begitu tidak stabil, dan lingkungan tidak akan sekeras ini.",
  ui_story_5080_50801201_132_dialog_content = "Kita tidak perlu repot-repot dengan semua gempa yang mengganggu saat kita mengemudi!",
  ui_story_5080_50801201_133_dialog_content = "Bahkan lebih dari itu—apakah kegersangan gurun ada hubungannya dengan makhluk-makhluk ini?",
  ui_story_5080_50801201_134_dialog_content = "Bagaimanapun, fakta bahwa Eclipsites ini bisa <color=#FFB400>menyerap</color> kekuatan gunung berapi sudah satu langkah terlalu jauh bagi saya.",
  ui_story_5080_50801201_135_dialog_content = "Jika <color=#FFB400>Eclipsite itu</color> dari masa lalu berhasil bertahan hidup selama ini, seberapa kuatkah makhluk itu?",
  ui_story_5080_50801201_136_dialog_content = "Kita tidak bisa membiarkan ini berlangsung lebih lama...",
  ui_story_5080_50801201_137_dialog_content = "Kita benar-benar tidak bisa membiarkannya terus berlangsung...",
  ui_story_5080_50801201_138_dialog_content = "Jadi, mari kita terus maju, lebih dalam ke gunung berapi! Menuju Sinsa!",
  ui_story_5080_50801202_1_dialog_content = "Wah... Ini benar-benar sempit sekali.",
  ui_story_5080_50801202_2_dialog_content = "Dan ada lava di mana-mana... Hati-hati!",
  ui_story_5080_50801202_3_dialog_content = "Anak burung kedua, Gadis Lolipop, tetap di belakangku!",
  ui_story_5080_50801202_4_dialog_content = "Eagle Hunter Satu, Dua, Tiga—buka tembakan!",
  ui_story_5080_50801202_5_dialog_content = "Kapten, jangan memaksakan diri! Eclipsites ini memiliki pertahanan yang sangat kuat!",
  ui_story_5080_50801202_6_dialog_content = "Cukup bicara! Serangan Fokus!",
  ui_story_5080_50801202_7_dialog_content = "Jangan takut! Bom manisku akan segera menyelesaikan ini!",
  ui_story_5080_50801202_8_dialog_content = "Mengaum-!",
  ui_story_5080_50801202_9_dialog_content = "Kapten!",
  ui_story_5080_50801202_10_dialog_content = "Ini hanya goresan—tetap di tempat.",
  ui_story_5080_50801202_11_dialog_content = "Ini dia putaran kedua!",
  ui_story_5080_50801202_12_dialog_content = "Elang Pemburu Satu, mundur dan bertahan!",
  ui_story_5080_50801202_13_dialog_content = "Tidak! Sudah terlambat...",
  ui_story_5080_50801202_14_dialog_content = "Serangan Hero!",
  ui_story_5080_50801202_15_dialog_content = "Mengaum-!",
  ui_story_5080_50801202_16_dialog_content = "Zeta?!",
  ui_story_5080_50801202_17_dialog_content = "Gadis Lolipop!!!",
  ui_story_5080_50801202_18_dialog_content = "Fleur, saya telah mengendalikannya dengan Force Boost saya! Serang sekarang!",
  ui_story_5080_50801202_19_dialog_content = "Sampai jumpa di neraka!",
  ui_story_5080_50801202_20_dialog_content = "Apakah itu jatuh ke dalam lava?",
  ui_story_5080_50801202_21_dialog_content = "Groooar!!!",
  ui_story_5080_50801202_22_dialog_content = "Ini ditelan oleh lava... Bukankah Eclipsites ini seharusnya mampu bertahan dari lava?",
  ui_story_5080_50801202_23_dialog_content = "Gadis Lollipop, apakah kamu baik-baik saja?!",
  ui_story_5080_50801202_24_dialog_content = "Heh, bagaimana menurutmu, Eagleshot? Rediesel Wrench tidak setengah-setengah.",
  ui_story_5080_50801202_25_dialog_content = "Kenapa kamu melakukan itu... untukku...?",
  ui_story_5080_50801202_26_dialog_content = "'Karena kau adalah saudara perempuan yang telah lama hilang dari sang pahlawan yang tersesat...",
  ui_story_5080_50801202_27_dialog_content = "Gadis Lolipop? Gadis Lolipop!",
  ui_story_5080_50801202_28_dialog_content = "(Sial, tidak ada kotak P3K dan Zeta dalam kondisi buruk... Tunggu... Hah?)",
  ui_story_5080_50801202_29_dialog_content = "Apakah aku gagal dalam perintahku lagi? Apakah aku, sekali lagi, membiarkan orang lain...",
  ui_story_5080_50801202_30_dialog_content = "Seharusnya aku yang menjadi pelindung...",
  ui_story_5080_50801202_31_dialog_content = "Mengapa saya terus membuat kesalahan? Apakah saya terlalu congkak?",
  ui_story_5080_50801202_32_dialog_content = "Jangan terlalu keras pada dirimu sendiri, Zeta masih punya kesempatan untuk bertarung! Cepat, bawa dia ke punggungku, kita perlu bergerak.",
  ui_story_5080_50801202_33_dialog_content = "Tetap bertahan, Zeta! Aku akan membawamu keluar dari sini, aku janji!",
  ui_story_5080_50801202_34_dialog_content = "Si mekanik iblis yang telah berubah, sepertinya perjalanan saya mungkin sudah berada di ujungnya. Lupakan saja tentang saya...",
  ui_story_5080_50801202_35_dialog_content = "Berhenti main-main!",
  ui_story_5080_50801202_36_dialog_content = "Sadarkan dirimu! Ingat katup baru yang kamu pesan dariku?",
  ui_story_5080_50801202_37_dialog_content = "Berikan aku sedikit lebih banyak waktu, dan aku akan mencari mesin twin-V8 yang lebih canggih! Kamu tidak ingin mencobanya?",
  ui_story_5080_50801202_38_dialog_content = "Apa?!",
  ui_story_5080_50801202_39_dialog_content = "Jika kamu bertahan sampai kita keluar dari sini, aku akan memodifikasi mobilmu secara eksklusif—tidak ada lagi bantuan untuk Azure! Bagaimana?",
  ui_story_5080_50801202_40_dialog_content = "Lagipula, bukankah kamu selalu ingin tahu apa yang ada di bawah kap mobil Azure? Aku akan mencarinya untukmu!",
  ui_story_5080_50801202_41_dialog_content = "Mari kita cari Roy dan ajak dia bersama kita... Zeta, bangunlah!",
  ui_story_5080_50801202_42_dialog_content = "Aku sedang merencanakan sebuah lelucon pada Azure dengan orang itu! Kamu tunggu saja!",
  ui_story_5080_50801202_43_dialog_content = "Benar, benar. Gadis Lollipop, aku juga bisa membantu. Aku mengambil jurusan teknik mesin di akademi!",
  ui_story_5080_50801202_44_dialog_content = "Tapi kamu bahkan tidak memanggilku dengan namaku...",
  ui_story_5080_50801202_45_dialog_content = "Aku bisa memodifikasi kendaraanmu juga. Teknologi Illumina itu kelas atas, tahu.",
  ui_story_5080_50801202_46_dialog_content = "Pernah bermimpi mengendarai kereta putri ala Illumina?",
  ui_story_5080_50801202_47_dialog_content = "Apa?! Tidak mungkin! Aku ingin melihatnya sekarang! Ada cetak biru?",
  ui_story_5080_50801202_48_dialog_content = "Zeta? Kamu... kamu baik-baik saja?",
  ui_story_5080_50801202_49_dialog_content = "Uh... Heh, sepertinya Pemburu Manis di punggungku telah menerima pukulan untukku... Kurasa aku memang pahlawan wanita pilihan setelah semua ini.",
  ui_story_5080_50801202_50_dialog_content = "Lady Zeta kembali beraksi!",
  ui_story_5080_50801202_51_dialog_content = "Kau...",
  ui_story_5080_50801202_52_dialog_content = "Ini adalah kisah tentang Anak Liar, Prajurit Zeta! Dia tidak akan menyerah tanpa perlawanan... Erm...",
  ui_story_5080_50801202_53_dialog_content = "Aku tidak mencoba menipu kalian, aku hanya ingin Fleur membawaku sebentar.",
  ui_story_5080_50801202_54_dialog_content = "Kau membuatku kaget... Kenapa kau berkelakar di saat seperti ini... Sungguh... Tapi, aku lega kau baik-baik saja.",
  ui_story_5080_50801202_55_dialog_content = "(Ketika aku pertama kali menyadarinya, aku tidak tahu bagaimana memberi tahu mereka... Aku senang lelucon itu tidak berlangsung lama.)",
  ui_story_5080_50801202_56_dialog_content = "Punggungku sangat sakit!",
  ui_story_5080_50801202_57_dialog_content = "Eagleshot, kamu tampak murung. Kamu tidak marah padaku, kan...?",
  ui_story_5080_50801202_58_dialog_content = "Hah? Wajahmu tampak sangat jahat sekarang... Kamu terlihat seperti akan berubah menjadi penjahat! Apakah kamu berencana membuat ini menjadi cerita horor?!",
  ui_story_5080_50801202_59_dialog_content = "Jangan—",
  ui_story_5080_50801202_60_dialog_content = "Apa?!",
  ui_story_5080_50801202_61_dialog_content = "Zeta... Aku sangat senang kau baik-baik saja.",
  ui_story_5080_50801202_62_dialog_content = "Kamu tidak bisa seenaknya menepuk kepala seorang pahlawan! Tapi karena kamu bertingkah lucu, aku tidak bisa menolakmu... Huh?",
  ui_story_5080_50801202_63_dialog_content = "K-Kamu menyebut namaku!",
  ui_story_5080_50801202_64_dialog_content = "Kamu tidak seharusnya menakuti orang dengan lelucon seperti itu...",
  ui_story_5080_50801202_65_dialog_content = "Kapten...",
  ui_story_5080_50801202_66_dialog_content = "Jangan khawatir, seorang pahlawan tidak pernah menggunakan trik yang sama dua kali, hehe.",
  ui_story_5080_50801202_67_dialog_content = "Baiklah, karena semuanya baik-baik saja, setelah semua itu... mari kita keluar dari perangkap lava ini! Terus bergerak!",
  ui_story_5080_50801202_68_dialog_content = "Caelestite Satu, Anak Burung Dua—jangan tertinggal!",
  ui_story_5080_50801202_69_dialog_content = "Kenapa dia masih memanggilku dengan nama kodeku...",
  ui_story_5080_50801202_70_dialog_content = "Mari kita tidak memikirkan hal-hal kecil untuk saat ini. Saatnya bergerak.",
  ui_story_5080_50801202_71_dialog_content = "Misi harus dilanjutkan. Cepatlah!",
  ui_story_5080_50801202_72_dialog_content = "(Dia dengan cepat memasang topeng dingin ketidakpeduliannya, tapi sekarang tampak begitu tidak pada tempatnya, Rachel...)",
  ui_story_5080_50801202_73_dialog_content = "Ayo pergi, Vice. Aku merasa ini hampir selesai.",
  ui_story_5080_50801202_74_dialog_content = "Bergeraklah cepat! Menjauhlah dari zona bahaya. Uh...",
  ui_story_5080_50801202_75_dialog_content = "Ada apa?",
  ui_story_5080_50801202_76_dialog_content = "Tak ada apa-apa, ayo pergi!",
  ui_story_5080_50801202_77_dialog_content = "Eagle Hunter One, bergerak maju sebagai pengintai. Setiap orang lainnya, ikuti Eagle Hunter One!",
  ui_story_5080_50801202_78_dialog_content = "Hidup mereka masih di tangan saya... Aku tidak bisa... jatuh sekarang...",
  ui_story_5080_50801301_1_dialog_content = "Graaaaah—!",
  ui_story_5080_50801301_2_dialog_content = "Mereka sedang berkerumun.",
  ui_story_5080_50801301_3_dialog_content = "Penuh dengan kejahatan, meluap dengan kebencian.",
  ui_story_5080_50801301_4_dialog_content = "Jeriah, mulailah bergerak, saya bisa menangani ini.",
  ui_story_5080_50801301_5_dialog_content = "Apa yang kamu bicarakan? Penglihatanmu terganggu. Aku tidak bisa meninggalkanmu.",
  ui_story_5080_50801301_6_dialog_content = "Kemampuanmu... tidak cocok untuk pertempuran ini.",
  ui_story_5080_50801301_7_dialog_content = "Bagaimanapun, aku masih anggota senior.",
  ui_story_5080_50801301_8_dialog_content = "Tanah... tenggelam... Aku akan jatuh ke dalam lava!",
  ui_story_5080_50801301_9_dialog_content = "Dawn! Sedikit ke kiri—pegang tanganku!",
  ui_story_5080_50801301_10_dialog_content = "Kamu duluan, Jeriah.",
  ui_story_5080_50801301_11_dialog_content = "Aku sudah memegang tanganmu. Jangan lepas, Dawn.",
  ui_story_5080_50801301_12_dialog_content = "Eclipsites, mereka datang.",
  ui_story_5080_50801301_13_dialog_content = "Saya tidak punya waktu untuk memikirkan itu sekarang.",
  ui_story_5080_50801301_14_dialog_content = "Mengapa? Jeriah, kamu perlu hidup!",
  ui_story_5080_50801301_15_dialog_content = "Jika kamu mati, semua orang akan sangat sedih.",
  ui_story_5080_50801301_16_dialog_content = "Bisakah kamu bayangkan wajah Eve basah oleh air mata?",
  ui_story_5080_50801301_17_dialog_content = "Dia akan memelukmu dan menangis!",
  ui_story_5080_50801301_18_dialog_content = "...",
  ui_story_5080_50801301_19_dialog_content = "Benang layang-layang itu benar-benar memiliki pegangan yang kuat pada kamu.",
  ui_story_5080_50801301_20_dialog_content = "Sekarang hubungan antara kita telah terjalin, aku tidak akan membiarkannya terputus dengan mudah!",
  ui_story_5080_50801301_21_dialog_content = "Jeriah... Hati-hati!",
  ui_story_5080_50801301_22_dialog_content = "Attar, aku sudah berusaha semampuku...",
  ui_story_5080_50801301_23_dialog_content = "<color=#FFB400>Rapid Torrent!</color>",
  ui_story_5080_50801301_24_dialog_content = "Tepat waktu! Zeta, halangi mereka dengan bommu!",
  ui_story_5080_50801301_25_dialog_content = "Hei-hei, bom gula paling dahsyat sedang menuju ke arahmu!",
  ui_story_5080_50801301_26_dialog_content = "Jeriah, saya di sini untuk membantu! Fleur, tolong bantu tarik Dawn...",
  ui_story_5080_50801301_27_dialog_content = "<color=#FFB400>Bunga Es!</color>",
  ui_story_5080_50801301_28_dialog_content = "Jembatan sudah siap, ayo naik!",
  ui_story_5080_50801301_29_dialog_content = "Carleen? Dan Eve?",
  ui_story_5080_50801301_30_dialog_content = "Dawn, saya di sini untuk membantu kamu!",
  ui_story_5080_50801301_31_dialog_content = "Kamu telah sangat membantu, Tuan Putri kecil dari Lumopolis.",
  ui_story_5080_50801301_32_dialog_content = "Tidak perlu berterima kasih padaku. Kamu juga berjuang keras untuk melindungi orang-orang yang kamu pedulikan, bukan?",
  ui_story_5080_50801301_33_dialog_content = "Ikutlah bersamaku, Dawn. Jangan lepaskan tanganku!",
  ui_story_5080_50801301_34_dialog_content = "Jeriah... tangan saya...",
  ui_story_5080_50801301_35_dialog_content = "Kami akhirnya berkumpul kembali. Carleen, kalian semua baik-baik saja?",
  ui_story_5080_50801301_36_dialog_content = "Kita baik-baik saja, tetapi lava di sini terlalu berbahaya. Kita tidak akan bisa bertarung di sini dalam waktu lama.",
  ui_story_5080_50801301_37_dialog_content = "Burung pemangsa kecil, Tuan Putri, cepat bawa Zeta pergi dari sini.",
  ui_story_5080_50801301_38_dialog_content = "Caelestite, aku minta tolong kamu untuk menggunakan kemampuan psikismu dan membimbing kami ke Sinsa.",
  ui_story_5080_50801301_39_dialog_content = "Kamu tidak pergi?",
  ui_story_5080_50801301_40_dialog_content = "Hah... Bagaimana mungkin aku bisa meninggalkannya pada saat seperti ini?",
  ui_story_5080_50801301_41_dialog_content = "Aku tidak akan pergi! Aku juga ingin menyelamatkan Berserker!",
  ui_story_5080_50801301_42_dialog_content = "Aku juga tidak bisa pergi begitu saja.",
  ui_story_5080_50801301_43_dialog_content = "Mengapa kalian semua memilih waktu seperti ini untuk menjadi begitu keras kepala?",
  ui_story_5080_50801301_44_dialog_content = "Mari masuk lebih dalam, lalu.",
  ui_story_5080_50801301_45_dialog_content = "Captain?",
  ui_story_5080_50801301_46_dialog_content = "Misi harus dilanjutkan. Kita perlu mengumpulkan lebih banyak informasi... dan menyelamatkan pemimpin Rediesel juga menjadi pilihan.",
  ui_story_5080_50801301_47_dialog_content = "Teknisi Rediesel, pinjamkan alatmu padaku. Anak Burung Dua, berikan senjatamu padaku.",
  ui_story_5080_50801301_48_dialog_content = "Eh? Aku?",
  ui_story_5080_50801301_49_dialog_content = "Baiklah, aku telah memperbaiki senjatamu. Mungkin butuh waktu untuk membiasakan diri, tapi seharusnya lebih mudah digunakan sekarang setelah kamu terluka.",
  ui_story_5080_50801301_50_dialog_content = "Elang Pemburu Satu, Dua, Tiga—kembali!",
  ui_story_5080_50801301_51_dialog_content = "Eagle Hunter Satu dan Tiga, giliran Eagle Hunter Dua untuk memimpin.",
  ui_story_5080_50801301_52_dialog_content = "Bersiaplah—lanjutkan misi.",
  ui_story_5080_50801301_53_dialog_content = "Busurku terasa lebih ringan. Tali busur terasa lebih responsif...",
  ui_story_5080_50801301_54_dialog_content = "Kapten ingat persis apa yang saya sukai. Dia sangat perhatian, jadi mengapa dia selalu menjaga jarak dari kami?",
  ui_story_5080_50801301_55_dialog_content = "Sebagai kapten, dia harus menyelesaikan misi dan menjaga agar rekan satu timnya tetap hidup.",
  ui_story_5080_50801301_56_dialog_content = "Meminimalisir kasih sayang timnya terhadap dirinya mungkin menjadi pilihan terakhirnya untuk mencegah orang lain terluka karena dirinya.",
  ui_story_5080_50801301_57_dialog_content = "Aku mengerti beban yang dia pikul.",
  ui_story_5080_50801301_58_dialog_content = "Sinsa!",
  ui_story_5080_50801301_59_dialog_content = "Kamu bodoh... Bisakah kau mendengarku?",
  ui_story_5080_50801301_60_dialog_content = "Sinsa?! Jawab kami!",
  ui_story_5080_50801301_61_dialog_content = "Roy, lihat ke bawah sana! Tempat di sebelah lava—apakah itu rambut merah Sinsa?",
  ui_story_5080_50801301_62_dialog_content = "Apakah itu benar atau tidak, saya akan turun untuk memeriksa!",
  ui_story_5080_50801301_63_dialog_content = "Hei! Itu adalah lava! Bagaimana kamu bisa melompat ke sana begitu saja?! Hei!",
  ui_story_5080_50801301_64_dialog_content = "Lupakan saja, aku adalah orang yang akan melampaui Sinsa suatu hari nanti, jadi bagaimana mungkin aku mundur di saat seperti ini?",
  ui_story_5080_50801301_65_dialog_content = "Aku melompat!",
  ui_story_5080_50801301_66_dialog_content = "Waaaahhhh—!",
  ui_story_5080_50801301_67_dialog_content = "Ada lava di mana-mana!",
  ui_story_5080_50801301_68_dialog_content = "Minggir!",
  ui_story_5080_50801301_69_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5080_50801301_70_dialog_content = "Kau meremukkanku, orang tua...",
  ui_story_5080_50801301_71_dialog_content = "Lihat, itu Sinsa! Itu benar-benar Sinsa! Dia masih hidup!",
  ui_story_5080_50801301_72_dialog_content = "Sinsa, kamu—",
  ui_story_5080_50801301_73_dialog_content = "Wow... Lihat semua Eclipsite ini yang sudah mati... Apakah dia membunuh mereka semua sendirian?",
  ui_story_5080_50801301_74_dialog_content = "Bahkan dengan luka utama setelah jatuh sejauh ini, dia masih berhasil membunuh begitu banyak dari mereka.",
  ui_story_5080_50801301_75_dialog_content = "Hei, kalian datang... Aku baru saja mencekik pria besar ini di sini...",
  ui_story_5080_50801301_76_dialog_content = "Sinsa?!",
  ui_story_5080_50801301_77_dialog_content = "Sinsa, sudahlah. Itu sudah mati, lepaskan dan ikutlah dengan kami!",
  ui_story_5080_50801301_78_dialog_content = "Hah? Sinsa?!",
  ui_story_5080_50801301_79_dialog_content = "Tadi aku tidak makan dengan baik... Sekarang aku lapar lagi...",
  ui_story_5080_50801301_80_dialog_content = "Aku benar-benar ingin kembali dan makan bersama semua orang. Makanan selalu terasa lebih enak seperti itu...",
  ui_story_5080_50801301_81_dialog_content = "Roy, aku sangat mengantuk. Mungkin aku terlalu banyak khawatir beberapa hari ini.",
  ui_story_5080_50801301_82_dialog_content = "Mari kembali untuk pesta kemenangan kita. Kita tidak boleh membuat yang lain menunggu terlalu lama...",
  ui_story_5080_50801301_83_dialog_content = "Apa yang salah dengannya? Periksa apakah dia baik-baik saja—jangan biarkan dia pingsan seperti ini!",
  ui_story_5080_50801301_84_dialog_content = "... Dia baik-baik saja. Dia hanya kelelahan dan tertidur.",
  ui_story_5080_50801301_85_dialog_content = "Dia keluar mencari orang semalam dan tidak makan banyak saat kembali, kasihan.",
  ui_story_5080_50801301_86_dialog_content = "Hmph, aku tahu pria ini tidak sebegitu rapuhnya.",
  ui_story_5080_50801301_87_dialog_content = "Lagipula, hanya aku yang diperbolehkan untuk mengalahkannya!",
  ui_story_5080_50801301_88_dialog_content = "Ayo, letakkan dia di punggungku.",
  ui_story_5080_50801301_89_dialog_content = "Ketika dia bangun dan mengetahui bahwa dia harus bergantung pada saya, dia akan sangat malu!",
  ui_story_5080_50801301_90_dialog_content = "Kalau begitu, aku serahkan dia padamu dan aku yang akan memimpin jalan. Ayo cepat kembali—",
  ui_story_5080_50801301_91_dialog_content = "Di mana kunci pas-nya?",
  ui_story_5080_50801301_92_dialog_content = "Mungkin dia kehilangan saat terjatuh... Aku harus mencarinya...",
  ui_story_5080_50801301_93_dialog_content = "<color=#828282>Bum!</color>",
  ui_story_5080_50801301_94_dialog_content = "Apakah Anda mendengar itu?",
  ui_story_5080_50801301_95_dialog_content = "Itu suara lava?",
  ui_story_5080_50801301_96_dialog_content = "<color=#e8d9bb>Duk, duk!</color>",
  ui_story_5080_50801301_97_dialog_content = "Itu dia lagi!",
  ui_story_5080_50801301_98_dialog_content = "... Suara langkah kaki! Brock, lari!",
  ui_story_5080_50801301_99_dialog_content = "<color=#e8d9bb>Buk, Buk, Buk!</color>",
  ui_story_5080_50801301_100_dialog_content = "Lari!!!",
  ui_story_5080_50801302_1_dialog_content = "Tolooooong!!!",
  ui_story_5080_50801302_2_dialog_content = "Siapa itu?",
  ui_story_5080_50801302_3_dialog_content = "Siapa itu?",
  ui_story_5080_50801302_4_dialog_content = "Wow! Itu kapten Illumina! Roy, kesini!",
  ui_story_5080_50801302_5_dialog_content = "Ada apa?",
  ui_story_5080_50801302_6_dialog_content = "<size=45><color=#e8d9bb>Duk, duk, duk, duk, duk, duk, duk, duk, duk, duk!</color></size>",
  ui_story_5080_50801302_7_dialog_content = "<color=#e8d9bb>Mengaum—!</color>",
  ui_story_5080_50801302_8_dialog_content = "Sebuah Eclipsite?! Tidak... itu <color=#FFB400>target</color>!",
  ui_story_5080_50801302_9_dialog_content = "Terima kasih atas bantuanmu, nona kecil Illumina.",
  ui_story_5080_50801302_10_dialog_content = "Aku akan memberikan tembakan penekan. Kalian semua pergi, yang lainnya tepat di belakang!",
  ui_story_5080_50801302_11_dialog_content = "Cepat, Roy, kita—",
  ui_story_5080_50801302_12_dialog_content = "Awas!",
  ui_story_5080_50801302_13_dialog_content = "Mengaum-!",
  ui_story_5080_50801302_14_dialog_content = "Licik banget... Lebih memilih dipukuli daripada membiarkan kita lewat.",
  ui_story_5080_50801302_15_dialog_content = "Apa itu? Eclipsite itu menghalangi jalan?",
  ui_story_5080_50801302_16_dialog_content = "Benda itu... Apakah dia yang membunuh Attar...?",
  ui_story_5080_50801302_17_dialog_content = "Biar aku yang urus ini!",
  ui_story_5080_50801302_18_dialog_content = "<color=#FFB400>Tornado!</color>",
  ui_story_5080_50801302_19_dialog_content = "<color=#e8d9bb>Langit-langit diledakkan oleh petir, menjatuhkan Eclipsite, tetapi ledakan kekuatan yang ganas ini juga menyebabkan gunung berapi mengaum, dan bumi mulai berguncang lagi.</color>",
  ui_story_5080_50801302_20_dialog_content = "Kekuatan ini... Kabar buruk, orang-orang—gunung berapi akan meletus!",
  ui_story_5080_50801302_21_dialog_content = "Gadis Rediesel, terus menyerang!",
  ui_story_5080_50801302_22_dialog_content = "Tapi itu bisa memicu letusan.",
  ui_story_5080_50801302_23_dialog_content = "Ini sudah terbangun. Jika keluar dari sini, yang lain akan berada dalam bahaya!",
  ui_story_5080_50801302_24_dialog_content = "Aku memukulnya tepat sasaran, tapi rasanya tidak ada kerusakan yang aku lakukan... Di mana titik lemahnya?",
  ui_story_5080_50801302_25_dialog_content = "Para Pemburu Elang sudah memeriksanya. Cangkangnya belum mencapai suhu sebenarnya dari lava.",
  ui_story_5080_50801302_26_dialog_content = "Dan, setiap bentuk kehidupan paling rentan saat sedang makan.",
  ui_story_5080_50801302_27_dialog_content = "Jika kita bisa memadamkan cangkangnya, mungkin ia akan mencoba menyerap kekuatan. Lalu, ia akan menunjukkan titik lemahnya!",
  ui_story_5080_50801302_28_dialog_content = "Jelas lebih besar saat itu... Bagaimana bisa menyusut dan bersembunyi di sini dengan nyaman selama lebih dari satu dekade...?",
  ui_story_5080_50801302_29_dialog_content = "<color=#FFB400>Death Recon!</color>",
  ui_story_5080_50801302_30_dialog_content = "<color=#FFB400>Tornado!</color>",
  ui_story_5080_50801302_31_dialog_content = "<color=#FFB400>Rapid Torrent!</color>",
  ui_story_5080_50801302_32_dialog_content = "<color=#FFB400>Bunga Es!</color>",
  ui_story_5080_50801302_33_dialog_content = "Grooooaaaar!",
  ui_story_5080_50801302_34_dialog_content = "Dia terluka! Serangan kita berhasil!",
  ui_story_5080_50801302_35_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_5080_50801302_36_dialog_content = "Sial, temboknya rusak! Lava mulai mengalir masuk!",
  ui_story_5080_50801302_37_dialog_content = "Hati-hati, itu mungkin menyerap energi lava!",
  ui_story_5080_50801302_38_dialog_content = "Brock, tarik Sinsa ke atas. Eve, hati-hati!",
  ui_story_5080_50801302_39_dialog_content = "Wahhhhhh!!! Botku terbakar!",
  ui_story_5080_50801302_40_dialog_content = "Zeta, kita hanya akan memperlambat mereka. Ayo mundur bersamaku untuk sekarang!",
  ui_story_5080_50801302_41_dialog_content = "Tapi, pahlawan wanita tidak bisa begitu saja meninggalkan panggung di saat seperti ini!",
  ui_story_5080_50801302_42_dialog_content = "Dengar, Zeta, kamu tidak ingin aku khawatir, bukan?",
  ui_story_5080_50801302_43_dialog_content = "Graaaaah—!",
  ui_story_5080_50801302_44_dialog_content = "Eclipsites meninggalkan sarang mereka!",
  ui_story_5080_50801302_45_dialog_content = "Karena om tua itu bilang begitu... Dawn, aku akan melindungimu—ayo kumpulkan beberapa teman baru!",
  ui_story_5080_50801302_46_dialog_content = "Jangan berani-berani menyakiti kakakku!",
  ui_story_5080_50801302_47_dialog_content = "Eve, mundur—Jeriah, kamu juga...",
  ui_story_5080_50801302_48_dialog_content = "Aku akan membuatnya sibuk. Kalian semua keluar dari Sinsa sini!",
  ui_story_5080_50801302_49_dialog_content = "Jeriah?",
  ui_story_5080_50801302_50_dialog_content = "Jika memang itu yang sama yang membunuh Attar... bagaimana mungkin aku bisa membiarkannya?!",
  ui_story_5080_50801302_51_dialog_content = "Meskipun lava mengalir masuk, tapi tidak menyerapnya... Kenapa ya?",
  ui_story_5080_50801302_52_dialog_content = "Sepertinya dia... bahkan menghindari lava?",
  ui_story_5080_50801302_53_dialog_content = "Tunggu, Vice, kamu berada di tempat yang berbahaya—mendekatlah kepadaku!",
  ui_story_5080_50801302_54_dialog_content = "Carleen, gunakan kekuatanmu untuk menciptakan pijakan di kepala mereka!",
  ui_story_5080_50801302_55_dialog_content = "Aku akan melindungimu! Maju saja!",
  ui_story_5080_50801302_56_dialog_content = "<color=#FFB400>Pembicara!</color>",
  ui_story_5080_50801302_57_dialog_content = "Grooooaaaar!",
  ui_story_5080_50801302_58_dialog_content = "Apakah itu melambat? Biarkan saya membantu juga!",
  ui_story_5080_50801302_59_option_content = "Force Boost!",
  ui_story_5080_50801302_60_dialog_content = "Orang-orang yang cukup tercela untuk mematahkan sayap burung harus membayar harganya!",
  ui_story_5080_50801302_61_dialog_content = "Sekarang saatnya! Apakah kamu siap, Putri Kecil?!",
  ui_story_5080_50801302_62_dialog_content = "<color=#FFB400>Bunga Es!</color>",
  ui_story_5080_50801302_63_dialog_content = "Cangkang magma-nya terlalu panas, dan kita tidak menimbulkan cukup kerusakan.",
  ui_story_5080_50801302_64_dialog_content = "Ini berhasil, kita perlu terus menyerang...",
  ui_story_5080_50801302_65_dialog_content = "Eagle Hunter Satu, Eagle Hunter Dua—maafkan saya.",
  ui_story_5080_50801302_66_dialog_content = "<color=#FFB400>Serangan Menghancurkan Diri!</color>",
  ui_story_5080_50801302_67_dialog_content = "Grooooaaaar!",
  ui_story_5080_50801302_68_dialog_content = "(Oh tidak, energi magma-nya terlalu kuat sekarang. Tidak peduli serangan apa yang kita gunakan, itu hanya akan memantul.)",
  ui_story_5080_50801302_69_dialog_content = "Ini lepas dari kendaliku... hati-hati, semuanya!",
  ui_story_5080_50801302_70_dialog_content = "(Kepalaku... sangat sakit...)",
  ui_story_5080_50801302_71_dialog_content = "Hei, gua ini runtuh! Kalian harus segera naik ke sini!",
  ui_story_5080_50801302_72_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_5080_50801302_73_dialog_content = "Makin panas saja. Dengan keadaan seperti ini...",
  ui_story_5080_50801302_74_dialog_content = "Aku sudah mendapatkan tuan putri kecil. Bawa dia dan lari!",
  ui_story_5080_50801302_75_dialog_content = "Oh tidak, Carleen dan Jeriah terjebak!",
  ui_story_5080_50801302_76_dialog_content = "Mungkin agak lambat, tapi aku akan membuat jalur. Kalian hati-hati!",
  ui_story_5080_50801302_77_dialog_content = "Mengapa ini terjadi? Kita sudah memindainya... Kenapa energinya masih begitu luar biasa?",
  ui_story_5080_50801302_78_dialog_content = "Apakah aku salah perhitungan?",
  ui_story_5080_50801302_79_dialog_content = "Bisakah ia terus mengisi kembali kekuatannya di tengah pertempuran?",
  ui_story_5080_50801302_80_dialog_content = "Lava itu datang, Kapten! Lari!",
  ui_story_5080_50801302_81_dialog_content = "Pergilah tanpa aku! Aku harus menanggung tanggung jawab ini... Aku akan menutupi retretmu!",
  ui_story_5080_50801302_82_dialog_content = "Ayo, sini!",
  ui_story_5080_50801302_83_dialog_content = "<color=#FFB400>Rapid Torrent!</color>",
  ui_story_5080_50801302_84_dialog_content = "Ke sini, itu benar!",
  ui_story_5080_50801302_85_dialog_content = "Grooooaaaar!",
  ui_story_5080_50801302_86_dialog_content = "Penetasan Dua!",
  ui_story_5080_50801302_87_dialog_content = "Jangan berani-berani menyentuh Vice lagi!!!",
  ui_story_5080_50801302_88_option_content = "Force Boost!",
  ui_story_5080_50801302_89_dialog_content = "Anak burung kedua, apakah kamu baik-baik saja? Bangun!",
  ui_story_5080_50801302_90_dialog_content = "(Penggemar efisiensi melepaskan kesempatan untuk menyerang demi Vice...)",
  ui_story_5080_50801302_91_dialog_content = "Kenapa aku merasa sangat senang sekarang... meskipun kepala ini terasa sangat sakit...?",
  ui_story_5080_50801302_92_dialog_content = "Tidak ada waktu untuk khawatirkan itu sekarang! Eve, kalian pergi!",
  ui_story_5080_50801302_93_dialog_content = "Saya datang!",
  ui_story_5080_50801302_94_dialog_content = "<color=#FFB400>Tinju Besi!</color>",
  ui_story_5080_50801302_95_dialog_content = "Tuan Putri kecil, aku akan meninggalkanmu untuk menstabilkan jembatan!",
  ui_story_5080_50801302_96_dialog_content = "<color=#FFB400>Tornado!</color>",
  ui_story_5080_50801302_97_dialog_content = "Itu berhasil! Saya memukulnya dari jarak yang sangat jauh!",
  ui_story_5080_50801302_98_dialog_content = "Ini terlalu panas—Aku tidak bisa melihat apa-apa dari sini.",
  ui_story_5080_50801302_99_dialog_content = "Grooooaaaar!",
  ui_story_5080_50801302_100_dialog_content = "Dia berusaha kabur.",
  ui_story_5080_50801302_101_dialog_content = "Jangan pernah berpikir untuk melarikan diri!",
  ui_story_5080_50801302_102_dialog_content = "Jangan kejar itu, Jeriah! Tanah di bawah kita akan segera ditelan oleh lava!",
  ui_story_5080_50801302_103_dialog_content = "... Jangan takut, setiap orang... Aku di sini.",
  ui_story_5080_50801302_104_dialog_content = "Para Pembicara telah menemukan titik lemah di dinding. Ke sini.",
  ui_story_5080_50801302_105_dialog_content = "Hosh... hosh... Ice Bridge, terapkan...",
  ui_story_5080_50801302_106_dialog_content = "Ini adalah sisa kekuatan yang tersisa padaku.",
  ui_story_5080_50801302_107_dialog_content = "Saya punya Anak Burung Dua di punggungku... Semuanya, keluar dari sini.",
  ui_story_5080_50801401_1_dialog_content = "<color=#FFB400>Bunga Es!</color>",
  ui_story_5080_50801401_2_dialog_content = "Itu tidak rusak?",
  ui_story_5080_50801401_3_dialog_content = "Suhu dinding ini terlalu tinggi. Sulit untuk menembusnya dengan kekuatan.",
  ui_story_5080_50801401_4_dialog_content = "Ini semua salahku... Eagle Hunter Satu dan Tiga hilang sia-sia.",
  ui_story_5080_50801401_5_dialog_content = "Ini terlalu panas di sini—terlalu panas untuk menggunakan bahan peledak tanpa perhitungan yang hati-hati...",
  ui_story_5080_50801401_6_dialog_content = "Berikan aku waktu sebentar, dan aku akan mengatur ledakan yang tepat.",
  ui_story_5080_50801401_7_dialog_content = "Hei, Roy, kamu melihat itu? Mereka terjebak di lorong itu.",
  ui_story_5080_50801401_8_dialog_content = "Aku tidak bisa mendapatkan bidikan yang baik dari sini...",
  ui_story_5080_50801401_9_dialog_content = "Tunggu sebentar, Eve, kekuatanmu terlalu tidak stabil untuk hal seperti ini!",
  ui_story_5080_50801401_10_dialog_content = "Hanya Sinsa yang bisa melakukan ini—Aku harus membangunkannya!",
  ui_story_5080_50801401_11_dialog_content = "Roy, keluarkan semua jatah!",
  ui_story_5080_50801401_12_dialog_content = "Hah? Apa yang kamu rencanakan untuk lakukan pada pria itu...?",
  ui_story_5080_50801401_13_dialog_content = "Hohoho! Sudah jelas, 'kan? Aku akan memberinya banyak makanan!",
  ui_story_5080_50801401_14_dialog_content = "Mengunyah, mengunyah, mengunyah, mengunyah, mengunyah, mengunyah...",
  ui_story_5080_50801401_15_dialog_content = "Berhenti! Apakah kamu mencoba mencekiknya?!",
  ui_story_5080_50801401_16_dialog_content = "<size=45>Hentikan sudah!</size>",
  ui_story_5080_50801401_17_dialog_content = "Vice... Vice... Jangan menakutiku seperti itu...",
  ui_story_5080_50801401_18_dialog_content = "Anak Burung Dua, Anak Burung Dua—bangun.",
  ui_story_5080_50801401_19_dialog_content = "Eagle Hunter Dua, aktifkan mode darurat segera! Atur defibrilator ke level dua! Mengisi daya!",
  ui_story_5080_50801401_20_dialog_content = "<color=#FFB400>Pertengkaran!</color>",
  ui_story_5080_50801401_21_dialog_content = "Aduh...",
  ui_story_5080_50801401_22_dialog_content = "Syukurlah kamu baik-baik saja...",
  ui_story_5080_50801401_23_dialog_content = "Anak Burung Dua! Bisakah kamu mendengar suaraku? Jangan khawatir, aku akan mengeluarkanmu dari sini...",
  ui_story_5080_50801401_24_dialog_content = "Kapten...",
  ui_story_5080_50801401_25_dialog_content = "Anak burung Dua? Anak burung Dua?",
  ui_story_5080_50801401_26_dialog_content = "...Cukup, Rachel!",
  ui_story_5080_50801401_27_dialog_content = "Jika kamu ingin membangkitkan hatinya, setidaknya panggil dia dengan namanya!",
  ui_story_5080_50801401_28_dialog_content = "Sebut namanya! Dia bukan \"Anak Burung Dua,\" dia punya nama–Vice!",
  ui_story_5080_50801401_29_dialog_content = "Caelestite Satu...",
  ui_story_5080_50801401_30_dialog_content = "Tidak masalah apa yang terjadi pada saya, tapi Vice...",
  ui_story_5080_50801401_31_dialog_content = "Dia mengidolakan dan menghormati kamu. Dia sangat senang hanya bisa bekerja sama dengan kamu.",
  ui_story_5080_50801401_32_dialog_content = "Namun, kau belum pernah sekali pun memanggilnya dengan namanya!",
  ui_story_5080_50801401_33_dialog_content = "...",
  ui_story_5080_50801401_34_dialog_content = "Namanya Vice! Dia akan begadang semalaman mengerjakan laporan misi untukmu, lelah tapi selalu begitu bersemangat...",
  ui_story_5080_50801401_35_dialog_content = "Meski kamu tidak pernah memanggilnya dengan nama, hanya berbicara dengan atasan seniornya sudah membuat harinya!",
  ui_story_5080_50801401_36_dialog_content = "Vice sangat mengagumi atasannya—dia hidup untuk pujian mereka. Dia tidak melakukan kesalahan apa pun... Ini hanya sebuah nama! Kenapa kamu begitu takut...?",
  ui_story_5080_50801401_37_dialog_content = "Tolong, setidaknya... setidaknya sekarang, panggil dia dengan namanya...",
  ui_story_5080_50801401_38_dialog_content = "Aku... tak bisa membiarkan diriku terikat lagi dengan hal-hal yang tak perlu...",
  ui_story_5080_50801401_39_dialog_content = "Burung pemangsa kecil...",
  ui_story_5080_50801401_40_dialog_content = "Kita sudah menyimpang dari misi... Aku tidak bisa... tidak bisa menyeret orang lain lagi...",
  ui_story_5080_50801401_41_dialog_content = "... Maafkan aku, dia sudah melakukan dengan sangat baik... Ini semua salahku...",
  ui_story_5080_50801401_42_dialog_content = "Aku takut menjadi beban lagi... Aku tidak ingin orang lain mati karena aku...",
  ui_story_5080_50801401_43_dialog_content = "Jika saya membentuk ikatan baru... jika lebih banyak orang-orangku mati karena perintahku... saya... tidak bisa menerima itu...",
  ui_story_5080_50801401_44_dialog_content = "Tidak! Saya tidak mencoba menyalahkan siapa pun!",
  ui_story_5080_50801401_45_dialog_content = "Kamu selalu menyembunyikan kebaikan hatimu sementara dengan tulus peduli pada semua orang. Kenapa harus disembunyikan?",
  ui_story_5080_50801401_46_dialog_content = "Ini karena ketika Anda tulus peduli pada orang lain, mereka bersedia untuk mempertaruhkan hidup mereka untuk melindungi Anda.",
  ui_story_5080_50801401_47_dialog_content = "Bagaimana kamu bisa menyebut itu sebagai lampiran yang tidak perlu...?",
  ui_story_5080_50801401_48_dialog_content = "Caelestite Satu, kamu tidak akan mengerti...",
  ui_story_5080_50801401_49_dialog_content = "Bagaimana mungkin aku tidak mengerti?! Aku hanya bisa menonton dengan tidak berdaya ketika orang lain mengorbankan diri mereka untukku! Bagaimana mungkin aku tidak mengerti?!",
  ui_story_5080_50801401_50_dialog_content = "Aku kalah dalam seluruh balapan, dan teman-teman yang akhirnya aku temukan... semua gara-gara aku...",
  ui_story_5080_50801401_51_dialog_content = "Aku mengerti rasa sakit kehilangan orang, kesepian, dan rasa bersalah...",
  ui_story_5080_50801401_52_dialog_content = "Saya benar-benar menghargai semua orang yang telah membantu saya. Dukungan mereka memungkinkan Vice, saya, dan semua teman kita untuk terus melanjutkan.",
  ui_story_5080_50801401_53_dialog_content = "Saya tidak berpikir lampiran-lampiran ini sama sekali tidak perlu.",
  ui_story_5080_50801401_54_dialog_content = "Hanya bisa bertemu dengan semua orang sudah merupakan pengalaman yang benar-benar luar biasa... Jika bisa, aku ingin memanggil nama mereka dan berbicara dengan mereka lagi.",
  ui_story_5080_50801401_55_dialog_content = "PlayerName...",
  ui_story_5080_50801401_56_dialog_content = "Cukup... Caelestite Satu...",
  ui_story_5080_50801401_57_dialog_content = "Orang-orang mengorbankan diri mereka untuk orang lain karena mereka memiliki cinta yang dalam di hati mereka.",
  ui_story_5080_50801401_58_dialog_content = "Orang-orang yang melindungimu, dan Vice, mereka tidak melakukannya demi misi!",
  ui_story_5080_50801401_59_dialog_content = "Mereka hanya ingin melindungimu... dan kenyataan bahwa kamu selamat sudah lebih dari cukup untuk membuat mereka bahagia.",
  ui_story_5080_50801401_60_dialog_content = "Seperti kapten dari Skuad Freebird... dia pasti sangat mencintai timnya, dia rela menodai reputasinya hanya untuk membawa mereka kembali.",
  ui_story_5080_50801401_61_dialog_content = "Pengorbanan adalah tentang melindungi orang-orang di belakangmu...",
  ui_story_5080_50801401_62_dialog_content = "Untuk mereka yang akhirnya saling memahami, bukankah itu sudah cukup menjadi alasan...?",
  ui_story_5080_50801401_63_dialog_content = "Jangan katakan lagi... Aku...",
  ui_story_5080_50801401_64_dialog_content = "Rachel, kamu tahu di dalam hatimu... Kamu seringkali mempertaruhkan nyawamu demi kami...",
  ui_story_5080_50801401_65_dialog_content = "Apakah ini benar-benar semua tentang efisiensi?",
  ui_story_5080_50801401_66_dialog_content = "Kamu hanya takut ada orang yang terluka... itulah mengapa kamu berusaha keras melindungi setiap orang...",
  ui_story_5080_50801401_67_dialog_content = "Kalau begitu... kenapa menolak untuk membentuk hubungan...?",
  ui_story_5080_50801401_68_dialog_content = "PlayerName... jangan menangis... kau sudah terlalu memaksakan diri...",
  ui_story_5080_50801401_69_dialog_content = "... Kita perlu mempersiapkan diri untuk ledakan, tunggu sebentar lagi.",
  ui_story_5080_50801401_70_dialog_content = "Burung pemangsa kecil... tidak, Rachel.",
  ui_story_5080_50801401_71_dialog_content = "Langit gurun sering melihat burung migran... bahkan ketika mereka tersesat sendirian, mereka akhirnya kembali ke kawanan.",
  ui_story_5080_50801401_72_dialog_content = "Saya... tidak mengerti itu sebelumnya. Tapi sekarang, saya menyadari bahwa memilih menjadi burung pemangsa masih berarti saya bisa memiliki teman.",
  ui_story_5080_50801401_73_dialog_content = "Aku... Aku... Aku tidak butuh teman...",
  ui_story_5080_50801401_74_dialog_content = "Kamu ini... keras kepala...",
  ui_story_5080_50801401_75_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_5080_50801401_76_dialog_content = "Apa yang terjadi? Apakah itu ledakan?",
  ui_story_5080_50801401_77_dialog_content = "Grooooaaaar!",
  ui_story_5080_50801401_78_dialog_content = "Awas!",
  ui_story_5080_50801401_79_dialog_content = "Rachel! Saya datang!",
  ui_story_5080_50801401_80_dialog_content = "Grooooaaaar!",
  ui_story_5080_50801401_81_dialog_content = "Sial, dia menyerang lantai.",
  ui_story_5080_50801401_82_dialog_content = "Pembicara, angkat putri kecil itu!",
  ui_story_5080_50801401_83_dialog_content = "<color=#e8d9bb>Duarr!!!</color>",
  ui_story_5080_50801401_84_dialog_content = "Dindingnya telah diledakkan! Ikutlah denganku!",
  ui_story_5080_50801401_85_dialog_content = "PlayerName dan yang lainnya masih di bawah sana!",
  ui_story_5080_50801401_86_dialog_content = "Grooooaaaar!",
  ui_story_5080_50801401_87_dialog_content = "Kamu tak akan... menyakiti teman-temanku lagi!",
  ui_story_5080_50801401_88_dialog_content = "PlayerName! Keluar dari sini bersama Carleen dan yang lainnya!",
  ui_story_5080_50801401_89_dialog_content = "Rachel... kamu... akhirnya terbuka...",
  ui_story_5080_50801401_90_dialog_content = "Mungkin tubuh lebih jujur daripada pikiran... PlayerName, pada saat saya melindungi Anda dari serangan itu...",
  ui_story_5080_50801401_91_dialog_content = "Kata-kata keras kepala itu terlepas dari saya.",
  ui_story_5080_50801401_92_dialog_content = "Jadi... ayo pergi.",
  ui_story_5080_50801401_93_dialog_content = "Lava datang! Caelestite, ambil tangan saya!",
  ui_story_5080_50801401_94_dialog_content = "Merry, Louis, Louis, Tarsi... Teman-temanku, tolong pinjamkan aku kekuatanmu.",
  ui_story_5080_50801401_95_dialog_content = "Lepaskan teman-temanku!",
  ui_story_5080_50801401_96_dialog_content = "Tidak... aku tidak akan kabur...",
  ui_story_5080_50801401_97_dialog_content = "PlayerName?!",
  ui_story_5080_50801401_98_dialog_content = "Aku mengatakan aku menghargai setiap orang yang telah membantuku... Aku sangat menghargai hubungan ini lebih dari apapun...",
  ui_story_5080_50801401_99_dialog_content = "Jadi, aku tidak akan menyerah pada teman-temanku, Rachel.",
  ui_story_5080_50801401_100_dialog_content = "...Kamu benar-benar prajurit yang tidak patuh.",
  ui_story_5080_50801401_101_dialog_content = "Tapi, PlayerName, aku senang...",
  ui_story_5080_50801401_102_dialog_content = "Saya merasa terhormat menjadi bagian dari tim yang sama dengan kalian semua.",
  ui_story_5080_50801401_103_dialog_content = "Ayo naik bersama.",
  ui_story_5080_50801401_104_dialog_content = "Carleen, gunakan sisa kekuatanmu untuk memperkuat pijakan kita!",
  ui_story_5080_50801401_105_dialog_content = "Jeriah, Pembicara seharusnya bisa menopang dinding yang runtuh, bukan?",
  ui_story_5080_50801401_106_dialog_content = "Fleur, kamu bertanggung jawab untuk menyerangnya langsung.",
  ui_story_5080_50801401_107_dialog_content = "Mari kita bertarung berdampingan.",
  ui_story_5080_50801402_1_dialog_content = "Lava semakin ganas, <color=#FFB400>Jalur Es</color> ku... hampir pecah!",
  ui_story_5080_50801402_2_dialog_content = "Sedikit lagi, baju besinya hampir kehabisan energi!",
  ui_story_5080_50801402_3_dialog_content = "Tidak! PlayerName, Rachel!",
  ui_story_5080_50801402_4_dialog_content = "(Oh tidak... aliran lava telah memotong jalan. Kita semua terpisah...)",
  ui_story_5080_50801402_5_dialog_content = "Lupakan tentang kami... Saya habis tenaga... kalian semua keluar melalui lubang yang Fleur hancurkan...",
  ui_story_5080_50801402_6_dialog_content = "Apa macam omong kosong itu? Tetap bertahan. Kita pasti bisa.",
  ui_story_5080_50801402_7_dialog_content = "Dari semua tempat... Mencoba membuat jembatan es lain di sini... hampir mustahil.",
  ui_story_5080_50801402_8_dialog_content = "<size=40>Astaga!!!</size>",
  ui_story_5080_50801402_9_dialog_content = "Aku tidak akan mundur, monster... bahkan jika yang tersisa hanyalah pistol ini...",
  ui_story_5080_50801402_10_dialog_content = "<color=#e8d9bb>Dor, dor, dor!</color>",
  ui_story_5080_50801402_11_dialog_content = "<color=#e8d9bb>Peluru dari Rachel mengenai Eclipsite satu per satu, tetapi mereka diblokir oleh panas terakhirnya.</color>",
  ui_story_5080_50801402_12_dialog_content = "<color=#e8d9bb>Klik—</color>",
  ui_story_5080_50801402_13_dialog_content = "Kehabisan amunisi...",
  ui_story_5080_50801402_14_dialog_content = "Senjataku habis, tapi aku masih punya tinjuku.",
  ui_story_5080_50801402_15_dialog_content = "PlayerName, bersembunyilah di belakangku dan jangan bergerak sedikitpun!",
  ui_story_5080_50801402_16_dialog_content = "Rachel... ayo pergi... aku tidak bisa bergerak lagi...",
  ui_story_5080_50801402_17_dialog_content = "Aku... tidak akan pernah meninggalkanmu!",
  ui_story_5080_50801402_18_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5080_50801402_19_dialog_content = "Erupsi lava lainnya, gunung berapi ini tampaknya akan... tunggu, apa itu?!",
  ui_story_5080_50801402_20_dialog_content = "Sebuah kunci pas... Kunci pas milik Sinsa? Bagaimana bisa ada di sini?",
  ui_story_5080_50801402_21_dialog_content = "Waktu yang tepat.",
  ui_story_5080_50801402_22_dialog_content = "Berhenti, Rachel, kunci pas itu terlalu berat untukmu! Jangan menyakiti diri sendiri!",
  ui_story_5080_50801402_23_dialog_content = "Hosh... Hosh... Kami kembali... Ah!",
  ui_story_5080_50801402_24_dialog_content = "Tunggu, dia benar-benar mengangkat kunci inggris Sinsa! Itu baru pamer!",
  ui_story_5080_50801402_25_dialog_content = "A... aku... benci saat anggota tim berusaha pamer...",
  ui_story_5080_50801402_26_dialog_content = "Tapi aku memang suka memamerkan diriku sendiri.",
  ui_story_5080_50801402_27_dialog_content = "Keren!!!",
  ui_story_5080_50801402_28_dialog_content = "Jangan berani-berani menyakiti rekan setimku!",
  ui_story_5080_50801402_29_dialog_content = "Grooo—!!!",
  ui_story_5080_50801402_30_dialog_content = "Bagaimana itu mungkin? Saya tidak pernah berpikir akan melihat seseorang selain Sinsa yang mengayunkan kunci pas itu...",
  ui_story_5080_50801402_31_dialog_content = "Auuu... Auuu... Auuu...!!!",
  ui_story_5080_50801402_32_dialog_content = "Belum mati?!",
  ui_story_5080_50801402_33_dialog_content = "Lalu... mari kita lakukan sekali lagi...",
  ui_story_5080_50801402_34_dialog_content = "(Ini buruk... Aku bisa merasakan tubuh Rachel sudah mencapai batasnya... Dia terlalu memaksakan diri... hanya sedikit lagi, dan...)",
  ui_story_5080_50801402_35_dialog_content = "Aku... tidak akan pernah menyerah... Satu kali lagi!",
  ui_story_5080_50801402_36_dialog_content = "Keren!!!",
  ui_story_5080_50801402_37_dialog_content = "Jembatan Es... Cepat!",
  ui_story_5080_50801402_38_dialog_content = "Dia kehabisan tenaga... Jika ini terus berlanjut... keduanya akan...",
  ui_story_5080_50801402_39_dialog_content = "Apa ini semua keributan?! Tidak bisakah seseorang mendapatkan sedikit istirahat di sini?!",
  ui_story_5080_50801402_40_dialog_content = "Kamu... Sinsa?!",
  ui_story_5080_50801402_41_dialog_content = "Hei, gadis kecil, kamu punya semangat.",
  ui_story_5080_50801402_42_dialog_content = "Dapat mengangkat kunci pas ini berarti kamu memiliki kekuatan yang sebenarnya.",
  ui_story_5080_50801402_43_dialog_content = "Menggunakan kekuatan itu untuk melindungi orang lain menunjukkan bahwa Anda memiliki kehendak yang lebih cerah.",
  ui_story_5080_50801402_44_dialog_content = "Ayo! Demi <color=#FFB400>keadilan</color> di hatimu, gunakan <color=#FFB400>kekuatan tertinggi</color> itu!",
  ui_story_5080_50801402_45_dialog_content = "<size=45>Hyaaaaaaah—!!!</size>",
  ui_story_5080_50801402_46_dialog_content = "<color=#e8d9bb>Duar!</color>",
  ui_story_5080_50801402_47_dialog_content = "Orang-orang dari dunia yang sangat berbeda, mengangkat kunci pas itu untuk hati yang mereka jaga...",
  ui_story_5080_50801402_48_dialog_content = "Dua siluet itu...",
  ui_story_5080_50801402_49_dialog_content = "Jangan berani-berani menyakiti mereka!",
  ui_story_5080_50801402_50_dialog_content = "Anda tidak akan melewati saya!",
  ui_story_5080_50801402_51_dialog_content = "Bahkan orang yang awalnya tidak bisa memahamimu, sekarang mengangkat kunci pas itu—",
  ui_story_5080_50801402_52_dialog_content = "Heh... kehendakmu masih hidup hingga hari ini... Attar...",
  ui_story_5080_50801402_53_dialog_content = "Dia tetap hidup sebagai... <color=#FFB400>Rediesel Wrench</color>.",
  ui_story_5080_50801402_54_dialog_content = "Akhirnya selesai juga... Inilah lava yang datang, ayo bergerak.",
  ui_story_5080_50801402_55_dialog_content = "Jembatan es terakhir sudah siap. Ayo pergi.",
  ui_story_5080_50801402_56_dialog_content = "Hei—! Di sini!",
  ui_story_5080_50801402_57_dialog_content = "Ke sini! Aku sudah melempar cangkuk panjat ke atas, kita bisa memanjat keluar!",
  ui_story_5080_50801402_58_dialog_content = "PlayerName... ayo pergi... ugh!",
  ui_story_5080_50801402_59_dialog_content = "Hei, apa kamu baik-baik saja? Menyiksa dirimu sendiri dengan semua luka itu—kamu sudah tidak punya tenaga lagi, bukan?",
  ui_story_5080_50801402_60_dialog_content = "Sepertinya kamu tidak punya pilihan. Butuh bantuan dari bandit Rediesel ini?",
  ui_story_5080_50801402_61_dialog_content = "...",
  ui_story_5080_50801402_62_dialog_content = "Ah!",
  ui_story_5080_50801402_63_dialog_content = "<color=#e8d9bb>Sebuah batu meluncur melewati kedua orang tersebut dan jatuh ke dalam lava.</color>",
  ui_story_5080_50801402_64_dialog_content = "... Siapa bilang saya tidak bisa berdiri? Butuh bantuan dari prajurit Illumina ini?",
  ui_story_5080_50801402_65_dialog_content = "Hahahaha! Kamu jauh lebih imut daripada yang kamu tunjukkan.",
  ui_story_5080_50801402_66_dialog_content = "Batu kecil seperti itu bukan masalah besar... tapi aku tidak seharusnya membuat Eve khawatir tentang lukaku.",
  ui_story_5080_50801402_67_dialog_content = "Sangat berterima kasih.",
  ui_story_5080_50801402_68_dialog_content = "Maaf... tapi bisakah ada yang membantu saya? Saya terlalu memaksakan kemampuan psikisku. Saya benar-benar lelah...",
  ui_story_5080_50801402_69_dialog_content = "...",
  ui_story_5080_50801402_70_dialog_content = "Heh...",
  ui_story_5080_50801402_71_dialog_content = "Hahaha!",
  ui_story_5080_50801402_72_dialog_content = "Berhenti tertawa di sana, ayo kita bergerak!",
  ui_story_5080_50801402_73_dialog_content = "<color=#e8d9bb>Gemuruh, gemuruh!</color>",
  ui_story_5080_50801402_74_dialog_content = "Oh ho! Akhirnya keluar juga! Udara segar dan suhu yang sempurna!",
  ui_story_5080_50801402_75_dialog_content = "Wah! Bagaimana kalian bisa begitu cepat?!",
  ui_story_5080_50801402_76_dialog_content = "Sepertinya membiarkan kalian berdua berlari di depan adalah keputusan yang tepat. Kemampuan menemukan jalur itu benar-benar luar biasa...",
  ui_story_5080_50801402_77_dialog_content = "Zeta memimpin jalan.",
  ui_story_5080_50801402_78_dialog_content = "A-Apa masalahnya?! Aku adalah legenda balapan reli! Jadi apa kalau aku bukan ahli gua!",
  ui_story_5080_50801402_79_dialog_content = "Hahahaha!",
  ui_story_5080_50801402_80_dialog_content = "Hei, Berserker! Jangan tertawa!",
  ui_story_5080_50801402_81_dialog_content = "Nah, tentu saja, kita harus tertawa, Zeta kecil.",
  ui_story_5080_50801402_82_dialog_content = "Kamu?! Bahkan kamu ingin mengganggu pahlawan hebat ini...?!",
  ui_story_5080_50801402_83_dialog_content = "Kita sebenarnya bisa kembali tepat waktu untuk pesta! Serius!",
  ui_story_5080_50801402_84_dialog_content = "Untuk apa kita berlama-lama di sini? Mereka mungkin akan memulai tanpa kita!",
  ui_story_5080_50801402_85_dialog_content = "Apa? Dengan Pahlawan Greta Zeta di sini? Aku akan membawamu kembali dalam sekejap!",
  ui_story_5080_50801402_86_dialog_content = "Masuk ke dalam mobil!",
  ui_story_5080_50801402_87_dialog_content = "Halo... Jonah?",
  ui_story_5080_50801402_88_dialog_content = "Azure?",
  ui_story_5080_50801402_89_dialog_content = "Oh tidak... Saya jarang pulang, dan ketika saya pulang, tempat ini sepi sekali.",
  ui_story_5080_50801402_90_dialog_content = "Tunggu! Apa itu di sana?",
  ui_story_5080_50801402_91_dialog_content = "<color=#e8d9bb>Bang!!! Bang, bang, bang!</color>",
  ui_story_5080_50801402_92_dialog_content = "<color=#e8d9bb>Sebuah ledakan dari perangkap memicu reaksi berantai di antara semua ranjau darat. Dalam sekejap, seluruh kamp tidak bisa dikenali lagi.</color>",
  ui_story_5080_50801402_93_dialog_content = "Itu adalah medan ranjau...",
  ui_story_5080_50801402_94_dialog_content = "Ada apa ini?",
  ui_story_5080_50801402_95_dialog_content = "Bagaimana kamp ini bisa berakhir dalam keadaan seperti ini? Uh... apakah kita masih akan mengadakan pesta malam ini?",
  ui_story_5080_50801402_96_dialog_content = "Ahhhhhhh!",
  ui_story_5080_50801402_97_dialog_content = "Kalian idiot! Apa yang telah kalian lakukan?!",
  ui_story_5080_50801402_98_dialog_content = "Hanya salah perhitungan kecil, bos!",
  ui_story_5080_50801402_99_dialog_content = "Berhenti berlari! Berdiri diam! Akan kuberi kau satu pelajaran!",
  ui_story_5080_50801402_100_dialog_content = "Baiklah, baiklah, berhenti memukul anak itu untuk sekarang. Mari kita lihat apa yang masih bisa dimakan di sini, maukah kita?",
  ui_story_5080_50801402_101_dialog_content = "Wahaaah! Panggung cantikku...!",
  ui_story_5080_50801402_102_dialog_content = "Jangan menangis, biarkan aku lihat apakah aku bisa memperbaikinya...",
  ui_story_5080_50801402_103_dialog_content = "Heh, aku tidak pernah berpikir akan melihatmu mengalami hari yang berat, gadis penyihir!",
  ui_story_5080_50801402_104_dialog_content = "Tentu saja kamu tidak tahu apa yang bisa dilakukan oleh Zeta yang Hebat, bukan?!",
  ui_story_5080_50801402_105_dialog_content = "... Ah, lupakan saja... Aku senang melihatmu, Kakak.",
  ui_story_5080_50801402_106_dialog_content = "Apa semua ini?",
  ui_story_5080_50801402_107_dialog_content = "Sungguh—",
  ui_story_5080_50801402_108_dialog_content = "Hei? Rachel! Rachel!",
  ui_story_5080_50801402_109_dialog_content = "Apa yang terjadi? Coba kulihat...",
  ui_story_5080_50801402_110_dialog_content = "Oh, dia baik-baik saja. Dia hanya begitu rileks sampai-sampai dia pingsan.",
  ui_story_5080_50801402_111_dialog_content = "Dronenya rusak lagi? Hmph, Odi, perhatikan dan belajarlah saat saya memamerkan keterampilan perbaikan yang luar biasa!",
  ui_story_5080_50801402_112_dialog_content = "Bagaimana bisa giliranmu saat aku di sini?",
  ui_story_5080_50801402_113_dialog_content = "Apakah ini... Kota Gannon?",
  ui_story_5080_50801402_114_dialog_content = "Kapan saya pulang...?",
  ui_story_5080_50801402_115_dialog_content = "Kapten! Kapten!",
  ui_story_5080_50801402_116_dialog_content = "Aku… aku…",
  ui_story_5080_50801402_117_dialog_content = "Angsa Putih... tidak, Merry, kamu...",
  ui_story_5080_50801402_118_dialog_content = "Ah, sudah begitu lama... Hmm?!",
  ui_story_5080_50801402_119_dialog_content = "Kapten, kamu... Kenapa kamu menangis?",
  ui_story_5080_50801402_120_dialog_content = "Maaf, aku minta maaf... Sudah lama sekali aku ingin memberitahumu ini.",
  ui_story_5080_50801402_121_dialog_content = "Saya bukan kapten yang baik... Saya membiarkanmu... membiarkanmu...",
  ui_story_5080_50801402_122_dialog_content = "Hahaha, tak pernah terpikir kapten akan menumpahkan air mata begitu bebas.",
  ui_story_5080_50801402_123_dialog_content = "Ini pertama kalinya aku melihatnya... dan semoga, itu adalah yang terakhir.",
  ui_story_5080_50801402_124_dialog_content = "Kamu adalah orang yang selamat, Kapten. Bukankah itu sangat hebat?",
  ui_story_5080_50801402_125_dialog_content = "Kami sangat senang bisa menyelamatkan kamu.",
  ui_story_5080_50801402_126_dialog_content = "Dan sekarang kamu bahkan lebih sempurna dari sebelumnya! Maksudku, kamu menyelamatkan semua orang, 'kan?",
  ui_story_5080_50801402_127_dialog_content = "Kau kini adalah kapten utama.",
  ui_story_5080_50801402_128_dialog_content = "Kalian...",
  ui_story_5080_50801402_129_dialog_content = "Saya sangat senang bisa bertemu denganmu, Kapten.",
  ui_story_5080_50801402_130_dialog_content = "Dari semua skuad, aku beruntung bisa dipilih olehmu... Aku sangat beruntung.",
  ui_story_5080_50801402_131_dialog_content = "Jadi kamu juga harus bahagia, Kapten.",
  ui_story_5080_50801402_132_dialog_content = "Kalian mau ke mana? Kembalilah ke sini! Dengarkan aku...",
  ui_story_5080_50801402_133_dialog_content = "Waktunya untuk kembali, Kapten. Kami bukanlah orang yang perlu Anda lindungi sekarang.",
  ui_story_5080_50801402_134_dialog_content = "Mohon hiduplah dengan baik... Tertawalah lebih banyak—itu saja yang kami inginkan!",
  ui_story_5080_50801402_135_dialog_content = "Tunggu, semua orang, jangan pergi!",
  ui_story_5080_50801402_136_dialog_content = "Kapten...",
  ui_story_5080_50801402_137_dialog_content = "T-Tunggu aku!",
  ui_story_5080_50801402_138_dialog_content = "Kapten...!",
  ui_story_5080_50801402_139_dialog_content = "Kau...",
  ui_story_5080_50801402_140_dialog_content = "Vice?",
  ui_story_5080_50801402_141_dialog_content = "Kapten...?",
  ui_story_5080_50801402_142_dialog_content = "Kamu baik-baik saja... Syukurlah.",
  ui_story_5080_50801402_143_dialog_content = "Tunggu! Apa kau baru saja... menyebut namaku?",
  ui_story_5080_50801402_144_dialog_content = "Waaah! Kapten! Kapten!!!",
  ui_story_5080_50801402_145_dialog_content = "<color=#e8d9bb>Vice, yang diliputi kegembiraan, memeluk Rachel dengan erat, tidak peduli betapa kaku penerima pelukannya.</color>",
  ui_story_5080_50801402_146_dialog_content = "(Tapi... hati tulus itu pasti tidak akan sia-sia.)",
  ui_story_5080_50801402_147_dialog_content = "Tidak apa-apa sekarang... Semuanya baik-baik saja...",
  ui_story_5080_50801402_148_dialog_content = "Terima kasih, Vice.",
  ui_story_5080_50801402_149_dialog_content = "Terima kasih, semuanya.",
  ui_story_5080_50801500_1_dialog_content = "Kita membunuh Eclipsite itu untuk menyelamatkan diri kita sendiri, tapi sekarang, gempa telah mereda, dan gunung berapi belum meletus.",
  ui_story_5080_50801500_2_dialog_content = "Maksudmu... masih ada sesuatu yang menekan energi gunung berapi?",
  ui_story_5080_50801500_3_dialog_content = "Ini hanya tebakan, tapi sebelum kita pergi, Pembicara menemukan-",
  ui_story_5080_50801500_4_dialog_content = "Tempat di mana kamu meratakan Eclipsite itu telah ditembus. Ada lapisan lain di bawahnya, dengan jalur sendiri.",
  ui_story_5080_50801500_5_dialog_content = "Sebuah jalur di dalam inti gunung berapi?",
  ui_story_5080_50801500_6_dialog_content = "Tapi sekarang semuanya sudah tertutup lava, jadi kita mungkin tidak bisa menyelidikinya.",
  ui_story_5080_50801500_7_dialog_content = "... Roy berpendapat bahwa Eclipsite itu bukanlah yang dari dulu.",
  ui_story_5080_50801500_8_dialog_content = "Memang. Jika bukan karena medan, hal-hal tidak akan menjadi begitu sulit. Jika ini adalah yang dari dulu, Attar tidak akan mati...",
  ui_story_5080_50801500_9_dialog_content = "Sepertinya semua hal erat kaitannya dengan kedalaman sejati dari gunung berapi.",
  ui_story_5080_50801500_10_dialog_content = "Musuh <color=#FFB400>sejati</color> kita... mungkin bersembunyi di sana.",
  ui_story_5080_50801500_11_dialog_content = "Ayo kita selidiki bersama setelah lava mendingin dan luka semua orang sembuh.",
  ui_story_5080_50801500_12_dialog_content = "Pasti cukup merepotkan bagi Rediesel Wrench, tidur di atas gunung berapi yang begitu aktif, bukan?",
  ui_story_5080_50801500_13_dialog_content = "Siapa yang bisa mengatakan... Kita semua hanyalah sekumpulan orang bodoh yang hidup di saat ini. Apakah benar ada di antara kita yang begitu khawatir tentang hal seperti itu?",
  ui_story_5080_50801500_14_dialog_content = "Panggung sudah diperbaiki... Aku telah bekerja di atasnya tanpa henti, dan anak laki-laki, aku benar-benar lelah!!!",
  ui_story_5080_50801500_15_dialog_content = "Jangan khawatir, serahkan saja bagian berikutnya padaku! Biarkan gairahku membakar langit malam—!",
  ui_story_5080_50801500_16_dialog_content = "Hah? Zeta?! Kamu, kamu...",
  ui_story_5080_50801500_17_dialog_content = "Kenapa kamu berdandan seperti hantu?",
  ui_story_5080_50801500_18_dialog_content = "Eh? Ini semua ide gadis penyihir, membuat Zeta tampak seperti orang dewasa!",
  ui_story_5080_50801500_19_dialog_content = "Maksudmu... gadis penyihir itu!!!",
  ui_story_5080_50801500_20_dialog_content = "Jangan lari! Bukankah kamu bilang akan menari bersamaku? Kita akan segera naik ke panggung untuk pertunjukan terakhir!",
  ui_story_5080_50801500_21_dialog_content = "Brock, kamu juga melihatnya, kan? Semua orang lapar.",
  ui_story_5080_50801500_22_dialog_content = "Pencuci sayuran tercepat pasti akan dipuji sebagai pahlawan sejati yang menyelesaikan krisis ini—seorang pahlawan yang layak mendapatkan rasa hormat dari setiap orang.",
  ui_story_5080_50801500_23_dialog_content = "Oh, oh, oh! Anda tidak perlu memberitahu saya dua kali—saya telah berlatih untuk ini, lihat saja!",
  ui_story_5080_50801500_24_dialog_content = "Benarkah? Wah, andai saja semua orang sepolos ini... Hei! Saya punya mesin pencuci sayuran di sini! Tertarik?",
  ui_story_5080_50801500_25_dialog_content = "Kamp ini berantakan... Aku juga ingin membantu.",
  ui_story_5080_50801500_26_dialog_content = "Iya, aku juga.",
  ui_story_5080_50801500_27_dialog_content = "Minggir! Tak ada yang boleh mencuri gunturku!",
  ui_story_5080_50801500_28_dialog_content = "Biarkan saja dia melakukannya, jika kamu menginginkan kehidupan yang damai.",
  ui_story_5080_50801500_29_dialog_content = "Azure? Azure? Ke mana kamu pergi?",
  ui_story_5080_50801500_30_dialog_content = "Saya hampir mengosongkan gudang. Kamu harus benar-benar minum denganku malam ini!",
  ui_story_5080_50801500_31_dialog_content = "Sungguh, betapa gaduhnya kerumunan ini...",
  ui_story_5080_50801500_32_dialog_content = "Aku bukan orang tua sejati, hanya anak nakal yang tersandung ke dalam semua ini setengah jalan.",
  ui_story_5080_50801500_33_dialog_content = "Astra sangat luas... tapi ini adalah satu-satunya tempat yang menerima saya dan Eve ketika kami tidak memiliki tempat untuk pergi.",
  ui_story_5080_50801500_34_dialog_content = "Akhirnya kita sampai sejauh ini. Kita akhirnya bisa mengandalkan diri kita sendiri untuk melanjutkan dan hidup bersama sebagai sebuah keluarga.",
  ui_story_5080_50801500_35_dialog_content = "Tidak perlu lagi khawatir untuk menyenangkan orang lain atau takut ditolak.",
  ui_story_5080_50801500_36_dialog_content = "Tahu apa? Ini pertama kalinya aku mendengar kamu mengatakan ini.",
  ui_story_5080_50801500_37_dialog_content = "Kita semua seperti orang aneh, seperti butiran pasir yang saling bergesekan dengan putus asa. Jika benar darah lebih kental daripada air, maka kita pasti sudah mencampur darah kita bersama-sama sejak lama.",
  ui_story_5080_50801500_38_dialog_content = "Jadi, aku senang menghabiskan setiap hari bersama para pria ini.",
  ui_story_5080_50801500_39_dialog_content = "Tidak peduli tantangan apa yang datang, kita selalu bersatu untuk menciptakan kehidupan yang bahagia. Itulah arti kebebasan bagi kita!",
  ui_story_5080_50801500_40_dialog_content = "Dan untuk menjaga cara hidup kita, aku akan mengangkat kunci inggris ini berulang kali untuk mengusir siapa saja yang berusaha mengacaukan kita!",
  ui_story_5080_50801500_41_dialog_content = "Kamu adalah pemimpin yang luar biasa, Sinsa.",
  ui_story_5080_50801500_42_dialog_content = "Sekarang, aku punya permintaan. Misiku sudah selesai, tapi aku masih belum puas.",
  ui_story_5080_50801500_43_dialog_content = "Jika bahaya masih mengintai di dekat, saya ingin menghadapinya bersama setiap orang di sini.",
  ui_story_5080_50801500_44_dialog_content = "Selain itu, pemimpin tua itu menyelamatkan bibi saya, dan saya ingin membayar hutang budi itu.",
  ui_story_5080_50801500_45_dialog_content = "Jadi, biarkan saya bertanya kepada Anda sekarang—apakah Anda mengerti arti dari \"pengorbanan\"?",
  ui_story_5080_50801500_46_dialog_content = "Heh...",
  ui_story_5080_50801500_47_dialog_content = "Hah? Kenapa kau menatap kami?",
  ui_story_5080_50801500_48_dialog_content = "Aku sudah memutuskan. Untuk menghindari teman-teman satu timku selalu khawatir, aku tidak akan sembarangan berbicara tentang pengorbanan.",
  ui_story_5080_50801500_49_dialog_content = "Tapi... jika kita pernah dalam bahaya, aku akan memberikan nyawaku untuk mereka yang berada di sisiku.",
  ui_story_5080_50801500_50_dialog_content = "Tidak peduli apa pun, aku ingin melindungi mereka yang berjalan bersamaku.",
  ui_story_5080_50801500_51_dialog_content = "Ya... Prajurit Illumina seharusnya tidak hanya bertindak demi misi atau demi kehormatan.",
  ui_story_5080_50801500_52_dialog_content = "Tapi karena kita ingin melindungi segala sesuatu dalam hidup kita.",
  ui_story_5080_50801500_53_dialog_content = "Rachel...",
  ui_story_5080_50801500_54_dialog_content = "Meskipun saya harus menjadi api yang menyala untuk menerangi jalan dan menjamin masa depan mereka di sekitar saya—ini adalah tujuan sejati dari Illumina!",
  ui_story_5080_50801500_55_dialog_content = "Leluhurku dibantu oleh orang lain dan berkorban untuk orang lain pada gilirannya, dan aku tidak akan menjadi pengecualian!",
  ui_story_5080_50801500_56_dialog_content = "Mulai sekarang, aku akan berjuang untuk melindungi keinginan hatiku dan menjadi benteng pertahanan yang tak tergoyahkan untuk Illumina.",
  ui_story_5080_50801500_57_dialog_content = "Kata-katamu terdengar agak sama seperti biasanya, tetapi matamu menceritakan kisah yang berbeda.",
  ui_story_5080_50801500_58_dialog_content = "Kamu yakin sudah siap untuk mulai membuat pilihanmu sendiri sekarang?",
  ui_story_5080_50801500_59_dialog_content = "Credo Illumina adalah \"satu untuk semua, semua untuk satu.\"",
  ui_story_5080_50801500_60_dialog_content = "Meski begitu, kita masih bisa membuat keputusan sendiri melalui kehendak kita sendiri. Kita bisa memutuskan apa yang kita perjuangkan, dan apa yang kita rela korbankan nyawa kita untuk itu.",
  ui_story_5080_50801500_61_dialog_content = "Jenis keteguhan ini tidak mungkin palsu... Ah!",
  ui_story_5080_50801500_62_dialog_content = "Bisakah kamu masih menemukan Illumina di dalam hatimu?",
  ui_story_5080_50801500_63_dialog_content = "Ada apa, Kapten Rachel? Apakah lukamu kambuh?",
  ui_story_5080_50801500_64_dialog_content = "...Tidak, jangan khawatir, Vice.",
  ui_story_5080_50801500_65_dialog_content = "Aku baru saja... akhirnya tahu bagaimana menjawab pertanyaan itu.",
  ui_story_5080_50801500_66_dialog_content = "Pertanyaan apa...?",
  ui_story_5080_50801500_67_dialog_content = "Heh... sepertinya akhirnya kau tahu apa yang sedang kau cari.",
  ui_story_5080_50801500_68_dialog_content = "Baiklah, saya setuju untuk membiarkan Anda membantu dalam penyelidikan.",
  ui_story_5080_50801500_69_dialog_content = "Tapi dengan luka-luka itu, jangan berpikir untuk terburu-buru masuk.",
  ui_story_5080_50801500_70_dialog_content = "Tetap di sini malam ini, nikmati makanan yang enak, dan istirahatlah.",
  ui_story_5080_50801500_71_dialog_content = "Hmm... Tapi...",
  ui_story_5080_50801500_72_dialog_content = "Tapi?",
  ui_story_5080_50801500_73_dialog_content = "Meski kita adalah sekutu, jika Rediesel Wrench membuat masalah lagi, aku akan menanganimu seperti aku menangani orang lain!",
  ui_story_5080_50801500_74_dialog_content = "Jika kamu mencemarkan kehendak yang diwakili oleh kunci pas itu, aku akan membuatmu menyerahkannya.",
  ui_story_5080_50801500_75_dialog_content = "Eh...",
  ui_story_5080_50801500_76_dialog_content = "Jika kamu menginginkannya, datang dan ambil sendiri.",
  ui_story_5080_50801500_77_dialog_content = "Sejujurnya, otak Illumina gilamu ini sepertinya ada beberapa baut yang longgar.",
  ui_story_5080_50801500_78_dialog_content = "Hahahaha!",
  ui_story_5080_50801500_79_dialog_content = "Apa yang kautertawakan?",
  ui_story_5080_50801500_80_dialog_content = "Ini adalah pertama kalinya aku melihatmu tampak begitu tak berdaya, Sinsa! Hahahaha!",
  ui_story_5080_50801500_81_dialog_content = "Beri aku istirahat...",
  ui_story_5080_50801500_82_dialog_content = "Bos! Bos! Lihat ini!",
  ui_story_5080_50801500_83_dialog_content = "Kami menemukannya saat membersihkan puing-puing—sepertinya ini mungkin buku harian bos lama.",
  ui_story_5080_50801500_84_dialog_content = "Kami menemukannya dalam kotak kecil yang terbuka akibat ledakan... Sepertinya ini telah tersembunyi sepanjang waktu.",
  ui_story_5080_50801500_85_dialog_content = "... Baiklah. Untuk saat ini, mari kita simpan saja.",
  ui_story_5080_50801500_86_dialog_content = "Ini adalah waktu pesta setelah semua. Kita akan khawatir tentang semua hal lainnya besok—mari kita bersenang-senang!",
  ui_story_5080_50801500_87_dialog_content = "Mengerti! Hei! Berhenti mendorong... Aduh!",
  ui_story_5080_50801500_88_dialog_content = "Sekarang giliranku untuk tertawa! Hahahaha!",
  ui_story_5080_50801500_89_dialog_content = "Burung kecil pemangsa ku, tolong tunggu sebentar.",
  ui_story_5080_50801500_90_dialog_content = "Ada apa?",
  ui_story_5080_50801500_91_dialog_content = "Saya ingin menceritakan bagian akhir dari cerita yang dibagikan Attar kepadaku.",
  ui_story_5080_50801500_92_dialog_content = "Setelah dia menyelamatkan rekan timnya dan meninggalkan misinya, dia meninggalkan Illumina. Tanpa tujuan, dia mengembara di dunia untuk sementara waktu.",
  ui_story_5080_50801500_93_dialog_content = "Dia secara kebetulan tiba di gurun yang sama tempat dia gagal dalam misinya, mengetahui bahwa musuhnya masih berada di sana.",
  ui_story_5080_50801500_94_dialog_content = "Dia mengatakan bahwa dia lahir di gurun ini. Dia tahu bahwa gurun ini adalah tempat tanpa hukum dan bebas. Hanya saja, dia belum pernah tinggal di sini sebelumnya.",
  ui_story_5080_50801500_95_dialog_content = "Jadi dia ingin melihatnya sendiri. Paling tidak, dia ingin menemukan tempat peristirahatan untuk anggota timnya yang telah meninggal.",
  ui_story_5080_50801500_96_dialog_content = "...",
  ui_story_5080_50801500_97_dialog_content = "Dia bertemu dengan bandit saat mengembara di gurun, dan oleh suatu takdir, dia memimpin mereka untuk melawan Eclipsite, mengambil kunci inggris legendaris itu untuk bertempur melawan mereka.",
  ui_story_5080_50801500_98_dialog_content = "Untuk orang-orang itu, dia mengangkat kunci pasnya, menyatukan para bandit gurun, dan mengakhiri kekacauan di tanah tandus ini.",
  ui_story_5080_50801500_99_dialog_content = "Dia memimpin orang-orang tersebut untuk menetap di oasis dan mempelajari cerita legendaris di balik kunci pas tersebut.",
  ui_story_5080_50801500_100_dialog_content = "Dan dengan demikian, dia mencelupkan kunci pas dengan rediesel yang diekstrak dari oasis, resmi mendirikan Rediesel Wrench.",
  ui_story_5080_50801500_101_dialog_content = "Dia hidup dengan baik, tidak hanya menemukan kebebasan sejati tetapi pada akhirnya mengorbankan segalanya untuk melindunginya.",
  ui_story_5080_50801500_102_dialog_content = "Kenapa... kamu memberitahuku semua ini?",
  ui_story_5080_50801500_103_dialog_content = "Tolong beri tahu bibi Anda saat Anda kembali.",
  ui_story_5080_50801500_104_dialog_content = "Kaptennya tidak hanya meninggalkan negaranya tanpa tujuan. Sepanjang perjalanan hidupnya, dia menggunakan senjatanya untuk kebebasan orang lain, hingga akhir hayatnya.",
  ui_story_5080_50801500_105_dialog_content = "Semoga informasi ini bisa memberikan sedikit ketenangan untuk bibimu.",
  ui_story_5080_50801500_106_dialog_content = "Terima kasih... Aku benar-benar tidak tahu bagaimana lagi cara mengungkapkan rasa terima kasihku.",
  ui_story_5080_50801500_107_dialog_content = "Nyanyikanlah, burung pemangsa kecil! Tidakkah kamu mendengar lagunya?",
  ui_story_5080_50801500_108_dialog_content = "Lagu ini...?",
  ui_story_5080_50801500_109_dialog_content = "Terbakarlah dengan terang, surga indah, rumah kami!",
  ui_story_5080_50801500_110_dialog_content = "Bernyanyi, bernyanyi, meskipun dunia esok hari dipenuhi luka!",
  ui_story_5080_50801500_111_dialog_content = "Nyanyikan suaramu dalam lagu... Itu adalah... kekuatan hidup.",
  ui_story_5080_50801500_112_dialog_content = "Kapten Rachel! Di sini! Pesta akan segera dimulai!",
  ui_story_5080_50801500_113_dialog_content = "Ah... Aku akan segera datang!",
  ui_story_5080_50801500_114_dialog_content = "... Sudah saatnya juga bagi saya untuk pergi...",
  ui_story_5080_50801500_115_dialog_content = "Mau pergi ke mana? Hei, ambil ini.",
  ui_story_5080_50801500_116_dialog_content = "Ini...",
  ui_story_5080_50801500_117_dialog_content = "Kaktus dengan hati kalajengking kristal panggang. Itu lezat! Aku menebak kamu belum pernah mencobanya sebelumnya.",
  ui_story_5080_50801500_118_dialog_content = "Kamu telah menjelajahi begitu banyak, di begitu banyak tempat yang bahkan saya tidak tahu ada.",
  ui_story_5080_50801500_119_dialog_content = "Bicara tentang menyatakan yang jelas...",
  ui_story_5080_50801500_120_dialog_content = "Hei... Jeriah, kamu juga harus pulang ke rumah sesekali. Mari kita makan bersama.",
  ui_story_5080_50801500_121_dialog_content = "... Sepertinya tidak ada jalan keluar dari pesta ini,",
  ui_story_5080_50801500_122_dialog_content = "Jadi apa lagi yang harus dikatakan? Ayo!",
  ui_story_5080_50801500_123_dialog_content = "Rachel, di sini! Aku telah menyimpankan tempat duduk untukmu.",
  ui_story_5080_50801500_124_dialog_content = "Begitu dagingnya dipanggang, ambillah bagianmu selagi bisa—biasanya orang-orang ini tidak punya waktu untuk basa-basi!",
  ui_story_5080_50801500_125_dialog_content = "Terima kasih... Terima kasih semuanya.",
  ui_story_5080_50801500_126_dialog_content = "Untuk apa? Ini bukan apa-apa, sungguh.",
  ui_story_5080_50801500_127_dialog_content = "Tidak... Aku berterima kasih karena kamu selalu berusaha menerima aku, meski dengan segala kekuranganku.",
  ui_story_5080_50801500_128_dialog_content = "Mari berjabat tangan—ini adalah tradisi Illumina.",
  ui_story_5080_50801500_129_dialog_content = "... Oke!",
  ui_story_5080_50801500_130_dialog_content = "Menarik, bukan? Meskipun kamu seorang Caelestite, kenapa aku merasa begitu akrab saat bersamamu?",
  ui_story_5080_50801500_131_dialog_content = "Dan kamu tidak pernah menghakimi saya. Kamu tampak nyaman dengan orang-orang Illumina.",
  ui_story_5080_50801500_132_dialog_content = "(Dimana aku harus mulai? Ini telah menjadi perjalanan yang panjang... dengan Gram, Revy, Reinhardt, Barton, dan yang lainnya...)",
  ui_story_5080_50801500_133_dialog_content = "PlayerName, ayo kita lakukan ini bersama, seperti yang baru saja saya katakan!",
  ui_story_5080_50801500_134_dialog_content = "Kanan!",
  ui_story_5080_50801500_135_dialog_content = "Jayalah Illumina!! Salam untukmu!",
  ui_story_5080_50801500_136_dialog_content = "Terima kasih telah menyelamatkan aku dan Vice!",
  ui_story_5080_50801500_137_dialog_content = "Salut militer yang sangat baik... Heh, sepertinya kalian berdua telah melalui banyak hal. Inilah sebabnya kalian menjadi teman seperjuangan yang legendaris.",
  ui_story_5080_50801500_138_dialog_content = "Sekarang aku mengerti mengapa Grand Marshal menyebutmu luar biasa.",
  ui_story_5080_50801500_139_dialog_content = "Tapi untuk saat ini, kalian juga teman-temanku...",
  ui_story_5080_50801500_140_dialog_content = "Ayo kita nikmati makan malam ini bersama-sama, semuanya!",
  ui_story_5080_50801500_141_dialog_content = "<color=#e8d9bb>Lagu kasar dari Rediesel Wrench, meski tidak halus, memancarkan rasa kebebasan yang tak terbatas. Lagu ini membangkitkan gurun, bergema sepanjang malam dalam melodi yang liar.</color>",
  ui_story_5080_50801500_142_dialog_content = "Merry... Louis... Tarsi... Lina... bisakah kamu mendengarnya?",
  ui_story_5080_50801500_143_dialog_content = "Mereka bilang gurun ini merangkul semua jiwa... Jadi...",
  ui_story_5080_50801500_144_dialog_content = "Tentunya itu juga merangkulmu.",
  ui_story_5080_50801500_145_dialog_content = "Terbang... di malam penuh kebebasan ini.",
  ui_story_5080_50801500_146_dialog_content = "Hingga roh kalian menemukan istirahat."
}
return config
